-- 2. STORED PROCEDURES
-- ============================================================================

-- 2.1. Stored Procedure: sp_CreateOverflowLocation
CREATE OR ALTER PROCEDURE [dbo].[sp_CreateOverflowLocation]
    @category_id INT,
    @new_location_id INT OUTPUT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @zone VARCHAR(10);
    SELECT TOP 1 @zone = zone
    FROM dbo.Warehouse_Locations
    WHERE category_id = @category_id
    ORDER BY location_id ASC;

    IF @zone IS NULL
    BEGIN
        RAISERROR(N'Thể loại này chưa có tầng gốc nào, không xác định được zone để tạo tầng phụ.', 16, 1);
        RETURN;
    END

    DECLARE @rack INT = 90, @shelf INT, @found BIT = 0;
    DECLARE @rack_str VARCHAR(10), @shelf_str VARCHAR(10);

    WHILE @rack <= 99 AND @found = 0
    BEGIN
        SET @shelf = 1;
        WHILE @shelf <= 5 AND @found = 0
        BEGIN
            SET @rack_str = RIGHT('0' + CAST(@rack AS VARCHAR(2)), 2);
            SET @shelf_str = RIGHT('0' + CAST(@shelf AS VARCHAR(2)), 2);

            IF NOT EXISTS (
                SELECT 1 FROM dbo.Warehouse_Locations
                WHERE zone = @zone AND rack = @rack_str AND shelf = @shelf_str
            )
            BEGIN
                SET @found = 1;
            END
            ELSE
            BEGIN
                SET @shelf += 1;
            END
        END
        IF @found = 0 SET @rack += 1;
    END

    IF @found = 0
    BEGIN
        RAISERROR(N'Đã hết chỗ trong dải rack phụ 90-99 cho zone này, cần mở zone mới.', 16, 1);
        RETURN;
    END

    DECLARE @cat_name NVARCHAR(255);
    SELECT @cat_name = category_name FROM dbo.Categories WHERE category_id = @category_id;

    INSERT INTO dbo.Warehouse_Locations (zone, rack, shelf, category_id, description, max_capacity)
    VALUES (
        @zone, @rack_str, @shelf_str, @category_id,
        CONCAT(N'Khu ', @zone, N' - Kệ ', @rack_str, N' - Tầng ', @shelf_str, N' - Tầng phụ thể loại ', @cat_name),
        100
    );

    SET @new_location_id = SCOPE_IDENTITY();
END;
GO

-- 2.2. Stored Procedure: sp_ReceivePurchaseOrder
CREATE OR ALTER PROCEDURE [dbo].[sp_ReceivePurchaseOrder]
    @purchase_order_id INT,
    @created_by NVARCHAR(128) = NULL
AS
BEGIN
    SET NOCOUNT ON;
    BEGIN TRY
        BEGIN TRANSACTION;

        DECLARE @details TABLE (
            book_id INT,
            received_quantity INT,
            import_price DECIMAL(18,2)
        );

        INSERT INTO @details (book_id, received_quantity, import_price)
        SELECT book_id, received_quantity, price
        FROM dbo.Purchase_Order_Details
        WHERE purchase_order_id = @purchase_order_id
          AND received_quantity > 0;

        UPDATE b
        SET
            b.cost_price = CASE
                WHEN ISNULL(b.stock_quantity, 0) + d.received_quantity = 0
                    THEN d.import_price
                ELSE
                    (ISNULL(b.cost_price, d.import_price) * ISNULL(b.stock_quantity, 0)
                        + d.import_price * d.received_quantity)
                    / (ISNULL(b.stock_quantity, 0) + d.received_quantity)
            END,
            b.stock_quantity = ISNULL(b.stock_quantity, 0) + d.received_quantity
        FROM dbo.Books b
        INNER JOIN @details d ON d.book_id = b.book_id;

        INSERT INTO dbo.Inventory_History
            (book_id, transaction_type, quantity_changed, related_id, created_at, created_by)
        SELECT
            d.book_id, 'IMPORT', d.received_quantity, @purchase_order_id, GETDATE(), @created_by
        FROM @details d;

        COMMIT TRANSACTION;
    END TRY
    BEGIN CATCH
        IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
        THROW;
    END CATCH
END;
GO

