INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (426, N'Người Bà Tài Giỏi Vùng Saga', N'Yoshichi Shimada', N'Huy Hoang Bookstore', CAST(103000.00 AS Decimal(18, 2)), N'Hạnh phúc không phải là thứ được định đoạt bằng tiền. Hạnh phúc phải được định đoạt bằng tâm thế của mỗi chúng ta.', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_231202.jpg', 216, 2021, 50, 0, N'NXB Thanh Niên', N'8935095631537', 2, 1, 36, 26, CAST(72100.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (427, N'Người Đàn Ông Mang Tên OVE (Tái Bản)', N'Fredrik Backman', N'NXB Trẻ', CAST(136000.00 AS Decimal(18, 2)), N'NGƯỜI ĐÀN ÔNG MANG TÊN OVE - CUỐN SÁCH KHIẾN TRIỆU ĐỘC GIẢ CƯỜI RỒI KHÓC Bạn có tin rằng một ông lão cộc cằn, khó tính lại có thể khiến bạn rơi nước mắt vì xúc động? Bạn đã bao giờ nghĩ rằng lòng nhân ái có thể đến từ những con người tưởng chừng khô khan nhất? Một ông lão cộc cằn, một con mèo hoang, vài người hàng xóm phiền phức - tất cả có thể tạo nên một câu chuyện khiến bạn bật khóc? VỀ TÁC GIẢ : Fredrik Backman - Hành trình trở thành nhà Văn được yêu thích Fredrik Backman (sinh năm 1981) là nhà văn, blogger và nhà báo người Thụy Điển. Trước khi trở thành tiểu thuyết gia, ông từng viết blog và làm phóng viên cho một tờ báo địa phương. Năm 2012, ông xuất bản Người Đàn Ông Mang Tên Ove, tác phẩm nhanh chóng trở thành hiện tượng toàn cầu, lọt top bán chạy tại nhiều quốc gia. Ông nổi tiếng với lối viết hài hước, cảm động và đầy tính nhân văn, đưa những câu chuyện đời thường trở nên sâu sắc và đáng nhớ. VỀ DỊCH GIẢ : Hoàng Anh - Người thổi hồn vào tác phẩm Hoàng Anh là dịch giả tận tâm, mang văn học thế giới đến gần hơn với độc giả Việt. Với lối dịch trôi chảy, giàu cảm xúc, anh đã giúp những câu chuyện nước ngoài trở nên gần gũi và chân thực hơn. Một số tác phẩm dịch tiêu biểu: Người Đàn Ông Mang Tên Ove - Fredrik Backman Britt-Marie Đã Ở Đây - Fredrik Backman Lời Hứa Lúc Bình Minh - Romain Gary TÓM TẮT NỘI DUNG SÁCH Ove là một người đàn ông 59 tuổi, sống một cuộc đời nghiêm túc, theo nguyên tắc và không thích thay đổi. Ông cộc cằn, khó gần, thậm chí có vẻ đáng ghét. Nhưng sâu bên trong, Ove là một người đàn ông mang nhiều nỗi đau, đặc biệt là sau khi mất đi người vợ yêu dấu. Cuộc sống của Ove đảo lộn khi một gia đình trẻ chuyển đến bên cạnh nhà ông và sự xuất hiện của con mèo hoang. Họ vô tình “xâm nhập” vào cuộc sống đơn độc của ông, kéo theo những tình huống dở khóc dở cười. Dần dần, tấm lòng nhân hậu của Ove được hé lộ , chứng minh rằng ngay cả những người khép kín nhất cũng có thể mở lòng khi gặp đúng người. Cuốn sách này cũng đã được chuyển thể thành bộ phim đình đám với sự tham gia của Tom Hanks , đã được đề cử ở hạng mục phim nói tiếng nước ngoài hay nhất tại Oscar 2017 . Quyển sách mang đến cho độc giả: Chạm đến cảm xúc – Hài hước, cảm động và đầy nhân văn. Nhìn cuộc sống theo cách khác – Đằng sau vẻ ngoài cộc cằn là một trái tim ấm áp. Tình người giản dị nhưng sâu sắc – Những kết nối nhỏ bé có thể thay đổi cả một đời người. Chữa lành và truyền cảm hứng – Dành cho những ai từng cô đơn, lạc lõng Tại sao độc giả nên đọc? Cuốn sách mang chất trào lộng duyên dáng kiểu Bắc Âu nhưng cũng tràn đầy tính nhân văn, đã trở thành hiện tượng toàn cầu với gần 3 triệu bản in bán ra. Sách xuất bản bằng tiếng Anh vào năm 2013 và lọt vào danh sách Sách bán chạy nhất của New York Times 18 tháng sau khi xuất bản và ở trong danh sách thứ 42 tuần. Độc giả đã sẵn sàng bước vào thế giới của Ove. Chốt đơn tại Fahasa ngay nào', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974182375.jpg', 452, 2022, 50, 0, N'Trẻ', N'8934974182375', 2, 1, 36, 34, CAST(95200.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (428, N'Bộ Mưa Đỏ - Ấn Bản Kỷ Niệm - Bìa Cứng - Tặng Kèm Bookmark + Móc Khoá Balo Mũ Cối - Độc Quyền Fahasa', N'Chu Lai', N'CÔNG TY TNHH VĂN HÓA VÀ TRUYỀN THÔNG THẢO NGUYÊN', CAST(175000.00 AS Decimal(18, 2)), N'Mưa Đỏ “Mưa đỏ” là tiểu thuyết của nhà văn Chu Lai, kết quả sau nhiều năm trăn trở và sáng tạo. Tiểu thuyết lấy bối cảnh chính là cuộc chiến đấu bảo vệ Thành cổ Quảng Trị mùa hè năm 1972, cả ở hai bên chiến tuyến (ta và địch), xoay quanh trục hai nhân vật chính: Cường (chiến sĩ Giải phóng) và Quang (tên chỉ huy hắc báo của ngụy). Bên cạnh đó là bối cảnh trên bàn đàm phán ở Pa-ri với nhân vật bà mẹ của Cường - một nhà ngoại giao là thành viên của đoàn đàm phán phía ta… Tác giả đã mượn phông nền của một sự kiện lịch sử điển hình nhưng cũng khá “nhạy cảm” trong cuộc kháng chiến chống Mỹ, cứu nước để dựng lại bức tranh bi tráng về cuộc chiến đấu bảo vệ Thành cổ 81 ngày đêm mùa hè đỏ lửa năm 1972. Bằng ngòi bút đậm chất văn miêu tả, không ôm đồm đi vào “bề rộng” của không gian cuộc chiến, mà đi vào chiều sâu của những chi tiết, những nhân vật; lột tả tính chất khốc liệt và bi tráng, tác giả nhập hồn vào từng nhân vật để giúp bạn đọc thấy được tâm trạng giằng xé trong từng cảnh huống: Cả sự dũng cảm và đớn hèn, cái thiện và cái á.c,… sự bùng n.ổ những trạng thái tích cực và tiêu cực… của những con người từng giây, từng phút phải đối mặt với sự hy sinh, chết chóc đến bất cứ lúc nào. Đan cài trong những trang miêu tả cuộc chiến đọc đến gai người là những khoảng bình yên, lãng mạn đầy chất thơ của tình yêu nảy mầm trong lửa đạn, của những sự hào hoa, phóng túng rất đời… (Trích giới thiệu trên báo Quân đội nhân dân đăng tải ngày 29/04/2016)', N'https://cdn1.fahasa.com/media/catalog/product/z/7/z7524933271610_1ef60b420a04d34b2.jpg', 392, 2025, 50, 0, N'Quân Đội Nhân Dân', N'8938563609069', 2, 1, 40, 18, CAST(122500.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (429, N'Hai Mặt Của Gia Đình (Tái Bản 2025)', N'Choi Kwanghuyn', N'AZ Việt Nam', CAST(104000.00 AS Decimal(18, 2)), N'Hai Mặt Của Gia Đình Tại sao chúng ta lại chịu tổn thương bởi gia đình – những người gần chúng ta nhất? Tại sao dù ở cạnh gia đình nhưng bạn vẫn cảm thấy xa cách và cô đơn? Vì sao chúng ta luôn bộc phát cảm xúc khi đứng trước gia đình mình. Vì sao nỗi đau của gia đình nơi bạn sinh ra và lớn lên lại lặp lại trong gia đình hiện tại? Nhiều khi những tổn thương đến từ gia đình nơi chúng ta sinh ra và lớn lên lại chính là nguyên nhân của các vấn đề trong gia đình hiện tại. Gia đình trở thành nơi tiếp thêm sức mạnh và cũng là nơi khiến đôi vai chúng ta thêm nặng trĩu, là nơi ẩn náu của những mâu thuẫn tinh vi đằng sau những phút giây thân mật, là nơi tràn đầy thương yêu nhưng có cả sự ghét bỏ. Gia đình lúc nào cũng có hai mặt như vậy. Choi Kwang Huyn – một nhà tâm lý học hàng đầu Hàn Quốc, người đã tham vấn tâm lý cho rất nhiều trường hợp có khúc mắc về tổn thương tâm lý xuất phát từ gia đình sẽ chỉ ra nguyên nhân của những tổn thương, những nỗi đau mà chúng ta phải chịu từ gia đình mình, đồng thời đưa ra cách giải quyết đối với các vấn đề gia đình nhức nhối hiện tại. Cuốn sách cho ta cái nhìn mới về mối quan hệ gia đình. Qua những câu chuyện của các gia đình khác nhau, người đọc lần lượt sẽ thấy được sự tương đồng và có thêm hiểu biết về những khái niệm như: ngoại tình, chứng nghiện một điều gì đó, lựa chọn người bạn đời tương đồng, chuyển di nỗi đau…từ đó tìm được cách chấp nhận và xoa dịu những tổn thương trong lòng mỗi người.', N'https://cdn1.fahasa.com/media/catalog/product/b/_/b_a-1---hai-m_t-c_a-gia-_nh.jpg', 288, 2025, 50, 0, N'Thế Giới', N'8935325027482', 3, 1, 37, 8, CAST(72800.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (430, N'Bộ Nơi Nào Có Mẹ - Nơi Ấy Là Nhà - Tặng Kèm Bookmark', N'Hạ Mer', N'AZ Việt Nam', CAST(72000.00 AS Decimal(18, 2)), N'Nơi Nào Có Mẹ - Nơi Ấy Là Nhà Trên đời này, sẽ chẳng có ai vì bạn quan tâm mà hỏi “Dạo này con làm gì, dạo này con có đủ tiền không, dạo này con có ăn uống đầy đủ không?”... ngoại trừ MẸ của bạn. Trên đời này, sẽ chẳng có ai sẵn sàng mua những thứ tốt nhất cho bạn dù họ có thể cả năm không mua lấy một bộ quần áo mới… ngoại trừ MẸ của bạn. Trên đời này, sẽ chẳng có ai cho bạn những bữa ăn miễn phí, yêu thương bạn vô điều kiện…ngoại trừ MẸ của bạn. Đúng thật là “thế gian rộng lớn, có mẹ là đủ”, nơi chúng ta muốn quay trở về để được chữa lành, được an ủi. Dù cả thế giới có bỏ mặc bạn, vẫn dám chắc chắn một điều, trong lòng mẹ, bạn chính là cả thế giới. NƠI NÀO CÓ MẸ, NƠI ẤY LÀ NHÀ là lời nhắn mà tác giả Hạ Mer gửi đến tất cả chúng ta: Khi bạn tìm hoài chẳng thấy hạnh phúc, về nhà đi! Nơi có Mẹ, có một mâm cơm ấm, một vòng tay êm, một góc sân nhỏ. Nơi có mẹ tựa một gốc đại thụ che trời, luôn đóng vai trầm mặc, che gió, che mưa cho bạn, sẵn sàng hy sinh mọi thứ mà không cần hồi đáp. Cuốn sách này không có triết lý hay bài học cao siêu gì cả, ở đây chỉ có những mẩu chuyện nho nhỏ mà tác giả Hạ Mer góp nhặt từ những năm tháng tuổi thơ cho tới lúc trải nghiệm và trưởng thành giữa cuộc đời rộng lớn. Mong rằng những con chữ này sẽ giúp ích gì đó cho bạn hoặc bạn sẽ bắt gặp hình ảnh của bản thân mình trong đó. “- Mẹ ơi, con sắp lên xe rồi, chắc khoảng hai, ba tiếng nữa là về đến nhà. Mẹ làm dưa xào, canh chuối đậu với mua mận cho con nhé. - Mẹ biết rồi, bao giờ về gần đến nơi thì gọi mẹ ra đón.” - Vâng ạ.” Hy vọng rằng khi cầm trên tay cuốn sách này, đọc từng mẩu chuyện nhỏ có thể giúp bạn vui vẻ, hạnh phúc hơn và những vết thương trong tâm hồn từ thời thơ ấu sẽ được chữa lành.', N'https://cdn1.fahasa.com/media/catalog/product/z/5/z5288994344245_f98249489626ef768c679043558bebee.jpg', 192, 2024, 50, 0, N'Văn Học', N'8935325019395', 3, 1, 37, 8, CAST(50400.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (431, N'Bộ Làm Bạn Với Cô Nàng Dễ Thương Nhì Lớp - Tập 4 - Bản Giới Hạn - Tặng Kèm Postcard + Bookmark + Kẹp File Ivory', N'Takata, Azuri Hyuga', N'Nhà Xuất Bản Kim Đồng', CAST(90000.00 AS Decimal(18, 2)), N'Làm Bạn Với Cô Nàng Dễ Thương Nhì Lớp - Tập 4 Mùa xuân này, tôi - Maehara Maki, và “cô gái dễ thương nhì lớp” Asanagi Umi đã lên lớp 11. Dù học khác lớp với Umi… nhưng 30 phút trước giờ đến trường vẫn là khoảng thời gian quý giá của đôi tình nhân chúng tôi. Những tin nhắn điện thoại gửi cho nhau từ phía bên kia hành lang cũng mang lại cảm giác mới mẻ. Tôi được bạn bè mới của Umi chào đón với tư cách là “cậu bạn trai”, vừa bối rối lại vừa rộn ràng mong đợi trước những mối quan hệ dần rộng mở… Ở lớp tôi, ngoài Amami còn có một nhân vật nổi bật khác: Arae Nagisa, người thường xuyên đi học muộn và luôn tỏ ra lạnh lùng. Dù Amami có bắt chuyện thì cô ấy cũng chỉ phớt lờ, khiến bầu không khí trong lớp khó có thể gọi là đồng lòng. Mà trong lúc ấy, giải đấu thể thao đối kháng giữa các lớp đang đến gần!? Đồng hành và xung đột. Thanh xuân và tình yêu cùng nảy nở trong tập 4.', N'https://cdn1.fahasa.com/media/catalog/product/l/a/lam-ban-voi-co-nang-de-thuong-nhi-lop_tap-4_ban-gioi-han.jpg', 400, 2026, 50, 0, N'Kim Đồng', N'8935352627518', 4, 1, 8, 1, CAST(63000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (432, N'Bộ Thưa Ngoại Con Mới Về - Tặng Kèm Bookmark', N'Lam', N'Skybooks', CAST(84000.00 AS Decimal(18, 2)), N'Thưa Ngoại Con Mới Về “Trong những tháng ngày lớn lên, có ai đó đã an ủi tôi rằng: “Khi rời đi, người thương của bạn sẽ hóa thành một vì sao lấp lánh.” Ngày ấy tôi không thích lời an ủi đó lắm, vì tôi chẳng thể tìm được vì sao nào trên bầu trời thành phố nơi tôi sống, dù đêm đó trăng có sáng hay không. Mãi sau này tôi mới hiểu, có những vì sao không mọc trên bầu trời, không thể nhìn bằng mắt thường, không thể chụp bằng điện thoại, bởi vì những vì sao ấy mọc ở trong tim.” Đó là những dòng viết đầy xúc động trong cuốn sách mới nhất của tác giả Lam - “Thưa ngoại con mới về”, một cuốn sách viết về những điều giản dị mà thiêng liêng, về ông bà, gia đình - nơi lưu giữ những yêu thương nguyên sơ và bình yên nhất. Nếu như "Trốn lên mái nhà để khóc" đã từng chạm đến trái tim HÀNG VẠN ĐỘC GIẢ bằng cách tiếp thêm cho chúng ta can đảm để đối mặt với những tổn thương, thì “Thưa ngoại con mới về” sẽ nhẹ nhàng nắm tay bạn, đưa bạn trở về với miền ký ức êm đềm của tuổi thơ. Nơi có mùi hương ấm áp của ông bà, của những bữa cơm gia đình, của tiếng cười giòn tan bên bếp lửa hồng. Nơi mà có lẽ, mỗi chúng ta đều vô tình lãng quên khi bị cuốn đi theo dòng chảy xô bồ của thời gian, hoặc buộc phải rời xa khi “làm một người trưởng thành”. Xuyên suốt 216 trang tản văn, Lam dệt nên những cung bậc cảm xúc vừa gần gũi, vừa lắng đọng về ông bà, gia đình. Từng câu chữ như thấm đẫm vị ngọt ngào của kẹo đường tuổi thơ, lại phảng phất đâu đó vị mặn mòi của những giọt nước mắt chia ly. Đọc “Thưa ngoại con mới về”, ta chợt nhận ra rằng thời gian có thể làm lu mờ nét mặt người thân yêu, nhưng những kỷ niệm quý giá về gia đình thì vẫn luôn vẹn nguyên trong tim mỗi người, như những vì sao lấp lánh, soi sáng cho ta trên mọi nẻo đường đời. “nếu như con biết trước rằng sẽ có một ngày con sẽ lạc mãi mãi hơi ấm một bàn tay con sẽ ôm chầm lấy nức nở trong lòng bà để thời gian chẳng thể mang bà của con xa.” “Thưa ngoại con mới về” mang sự nhẹ nhàng của hương vị tình thân qua từng bữa cơm cùng ông bà buổi chiều hè, hương khói căn bếp ló rạng trong lòng bạn, mang mọi phiền muộn của bạn đi xa như một giấc ngủ êm. Để trên hành trình trưởng thành, nếu có cô đơn, lạc lối, bạn vẫn có những hạnh phúc tuổi thơ nhỏ xinh làm điểm tựa, nâng đỡ đôi chân bạn bước đi chậm rãi tận hưởng mộng ước tuổi trẻ, xoa dịu bao nỗi buồn cuộn trào nơi lồng ngực, đập tan cơn nức nở và vỡ òa của những đêm tối trong phòng trọ nơi xa… “Thưa ngoại con mới về” tựa như chiếc rương ký ức nhỏ trong trái tim bạn, ghi lại những hoài niệm đẹp đẽ, đồng thời cũng là người bạn đồng hành để chúng ta tiếp tục bước đi đến tương lai. Đồng thời cuốn sách cũng là một nốt trầm để nhắc ta có thể dừng lại một chút, lắng nghe tiếng lòng mình, để biết trân trọng hơn những giá trị bình dị mà thiêng liêng của hai chữ “gia đình”. Sau khi khép lại cuốn sách này của Lam, mong bạn nhẹ nhàng bước tiếp hành trình trở thành “người lớn” hạnh phúc của mình, vì những người bạn yêu quý luôn ở bên cạnh bạn không bao giờ rời xa!', N'https://cdn1.fahasa.com/media/catalog/product/z/5/z5919252030585_22f8867c87aacc0e58cbdba585ca9e1d.jpg', 216, 2024, 50, 0, N'Dân Trí', N'8935325023583', 3, 1, 41, 37, CAST(58800.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (433, N'Kẻ Tử Tế Độc Hại', N'Higashino Keigo', N'1980 Books', CAST(168000.00 AS Decimal(18, 2)), N'Kẻ Tử Tế Độc Hại Cuốn sách là một tuyển tập truyện ngắn trứ danh, đỉnh cao của Higashino Keigo với các cốt truyện hài hước, châm biếm sâu cay và những tưởng tượng kì quái: Ông ngoại lên kế hoạch bắt cóc cháu ruột; Một cô gái dựa vào cuốn sách Hướng dẫn sử dụng sát ý để lên kế hoạch giết người; Cách con người đối xử với một sinh vật lạ có vẻ ngoài như thiên sứ, không rõ giống loài, chuyên ăn nhựa; Một người đàn ông giết hại vợ mình và muốn ra tự thú nhưng bị một cuốn “cẩm nang” gây cản trở;... Mỗi câu chuyện là một lát cắt hiện thực với những tình tiết “quay xe” không thể lường trước. Ẩn sau những tiếng cười đó, tác giả đã lồng ghép một cách tinh tế những bài học về con người, mối quan hệ trong gia đình và các vấn đề xã hội. Mục lục: 1. Thiên đường bắt cóc 2. Angel 3. Quý bà khéo tay 4. Cẩm nang cảnh sát 5. Cụ ông trông nhà 6. Búp bê chú rể 7. Nữ nhà văn 8. Hướng dẫn sử dụng sát ý 9. Chuộc lỗi 10. Nhân chứng hiển hách 11. Chương trình giám định vật chứng kinh điển 12. Vòng quay tống tiền Chương kết đặc biệt: Kyogoku Natsuhiko vs Higashino Keigo Thông tin về tác phẩm: 1. Đây là một tuyển tập truyện ngắn trứ danh của Higashino Keigo, không phải theo phong cách trinh thám ly kỳ quen thuộc, mà là những câu chuyện hài hước, châm biếm sâu cay và đầy tưởng tượng kỳ quái. 2. Sự rùng mình pha trộn với tiếng cười – vừa ghê rợn vừa buồn cười đến dựng tóc gáy. Một tuyển tập gồm 12 truyện ngắn đỉnh cao với chất hài đen đặc trưng, mang lại nụ cười đắng cay nhưng đầy thỏa mãn! 3. Tính “hài đen” châm biếm để lại sau tiếng cười là sự đắng cay, mỉa mai, bùng nổ của mâu thuẫn xã hội. 4. Tất cả bối cảnh đều là những câu chuyện xuất phát từ những điều bình thường từ các mối quan hệ gia đình, đời sống, xã hội, công việc, học tập… nhưng bị đẩy đến cực hạn để bộc lộ những mâu thuẫn tiềm ẩn. 5. Dễ dàng cảm nhận những nhân vật với phần cảm xúc chân thật nhất mà ta vẫn thấy hàng ngày qua những vấn đề nhức nhối và thời sự vượt thời gian. Trích dẫn hay trong sách: - “Tiếng cười là một công tác rất cứng đầu. Không dễ gì mà kích hoạt nó. Nên khi cố gắng bật công tắc cười lên, ta lại vô tình chạm vào công tắc khác…” - “Thật ra cảm giác sau khi hoàn thành nó (truyện cười) còn thỏa mãn hơn cả lúc viết xong một truyện trinh thám”. - “Về kỹ thuật, làm người ta cười khó hơn làm người ta khóc nhiều.” - “Tôi đọc các truyện theo thứ tự. Đang đọc vui vẻ thì lại bị truyện đó đánh úp. ‘Ơ, đây là truyện trinh thám rồi còn gì.’ Một sự phản bội dễ chịu. Cú bẻ hướng ấy ngược lại rất thú vị.” Tác giả: HIGASHINO KEIGO sinh năm 1958 tại Osaka. Tốt nghiệp khoa Kỹ thuật Đại học Công lập Osaka (Osaka Prefecture University). Năm 1985, ông bắt đầu sự nghiệp nhà văn với tác phẩm Houkago, đoạt giải thưởng Edogawa Ranpo lần thứ 31. Năm 1999, ông nhận giải thưởng Hiệp hội nhà văn trinh thám Nhật Bản lần thứ 52 cho tác phẩm Himitsu. Năm 2006, ông đoạt giải thưởng Naoki lần thứ 134 và giải thưởng Honkaku Mystery lần thứ 6 cho tác phẩm Yougisha X no Kenshin. Năm 2012, ông nhận giải thưởng Văn học Công luận Trung ương lần thứ 7 cho tác phẩm Namiya Zakka-ten no Kiseki. Năm 2013, ông đoạt giải thưởng Shibata Renza-buro lần thứ 26 cho tác phẩm Mugen Hana. Năm 2014, ông nhận giải thưởng Văn học Eiji Yoshikawa lần thứ 48 cho tác phẩm Inori no Maku ga Oriru Toki. Năm 2019, ông được trao giải thưởng Văn hóa Xuất bản Noma lần thứ nhất. Các tác phẩm tiêu biểu của ông bao gồm: Bunshin, Byakuyakou, Genya, Kokushou Shousetsu, loạt truyện Masquerade Hotel, Hakuchou to Koumori, Toumei na Rasen và nhiều tác phẩm khác.', N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia-1-ke-tu-te-doc-hai.jpg', 372, 2025, 50, 0, N'Hà Nội', N'8936230473562', 3, 1, 41, 6, CAST(117600.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (434, N'Bộ Cuộc Cách Mạng Ma Thuật Của Công Chúa Chuyển Sinh Và Tiểu Thư Thiên Tài - Tập 1 - Tặng Kèm Bookmark Hai Mặt + Postcard Hai Mặt', N'Piero Karasu, Yuri Kisaragi', N'CÔNG TY CỔ PHẦN TRUYỀN THÔNG VÀ XUẤT BẢN AMAK', CAST(132000.00 AS Decimal(18, 2)), N'Cuộc Cách Mạng Ma Thuật Của Công Chúa Chuyển Sinh Và Tiểu Thư Thiên Tài - Tập 1 Điều gì sẽ xảy ra khi một nàng công chúa không thể dùng ma pháp lại quyết tâm tự tạo ra thứ phép thuật cho riêng mình? Một cuộc gặp gỡ định mệnh là khởi đầu cho cuộc cách mạng ma thuật, và hai cô gái sẽ cùng nhau viết lại vận mệnh của chính mình. Sinh ra trong vương quốc nơi ma pháp là tất cả, công chúa Anisphia lại mang một khiếm khuyết: cô hoàn toàn không thể sử dụng phép thuật. Thay vì chấp nhận số phận, Anisphia chọn một con đường khác: vận dụng ký ức tiền kiếp về thế giới hiện đại để nghiên cứu “ma pháp học”, mở ra những phát minh chưa từng tồn tại. Mọi thứ thay đổi khi cô vô tình giải cứu Euphyllia – vị tiểu thư thiên tài vừa bị hủy hôn ngay giữa buổi lễ hoàng gia. Một người mất đi danh dự, một người luôn bị cả giới quý tộc ghét bỏ. Từ cuộc gặp gỡ ấy, hai số phận tưởng chừng xa lạ bắt đầu song hành. Cuộc Cách Mạng Ma Thuật của Công Chúa Chuyển Sinh và Tiểu Thư Thiên Tài không chỉ là câu chuyện fantasy đầy sáng tạo, mà còn là hành trình tìm kiếm bản thân, phá vỡ định kiến và lựa chọn con đường mình tin tưởng. Với nhịp truyện cuốn hút, thế giới phép thuật mới lạ cùng mối liên kết dần nảy nở giữa Anisphia và Euphyllia, tập 1 hứa hẹn sẽ mở ra một khởi đầu rực rỡ cho hành trình này.', N'https://cdn1.fahasa.com/media/catalog/product/z/7/z7497191227520_b8bf83db11c8bb663bece889273a02ec.jpg', 368, 2026, 50, 0, N'Hà Nội', N'9786044465296', 4, 1, 8, 12, CAST(92400.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (435, N'Arya Bàn Bên Thỉnh Thoảng Lại Trêu Ghẹo Tôi Bằng Tiếng Nga - Tập 10 - Bản Boxset - Tặng Kèm Box + Set 6 Bookmark + Standee Acrylic', N'Sunsunsun, Momoco', N'Nhà Xuất Bản Kim Đồng', CAST(250000.00 AS Decimal(18, 2)), N'Arya Bàn Bên Thỉnh Thoảng Lại Trêu Ghẹo Tôi Bằng Tiếng Nga - Tập 10 “И наменятоже обрати внимание” “Anh sẽ trở lại là Suou Masachika để trở thành một bản thân mà anh có thể tự hào.” Sự giác ngộ đặt cược vào vị trí gia chủ nhà Suou, cùng quyết tâm không lay chuyển với cuộc chiến bầu cử. Sau khi bộc bạch hết nỗi lòng với nhau, Masachika và Yuki cuối cùng cũng làm hòa. (Không... đây thật ra là ai? Người khác à? Làm… gì có chuyện đó chứ?) Mặt khác, dù bị Yuki trong “chế độ em gái” xoay như chong chóng, Alisa vẫn thấu hiểu quá khứ mà hai anh em nhà Suou phải gánh vác và chấp nhận sự thật. Giữa lúc ấy, Ayano lại có vẻ như đang một mình trầm tư suy nghĩ điều gì đó. Và rồi, Nonoa với ác ý ngây thơ ẩn giấu đã bất ngờ tiếp cận cô...!? “… Thực ra cậu thấy ngứa mắt Kujou Alisa lắm đúng không?” Những âm mưu cuộn xoáy bắt đầu hiển lộ trong tập 10 này của câu chuyện hài lãng mạn tuổi thanh xuân cùng nữ sinh trung học gốc Nga!', N'https://cdn1.fahasa.com/media/catalog/product/a/r/arya-ban-ben-thinh-thoang-lai-treu-gheo-toi-bang-tieng-nga_tap-10_limited-edition_bia_qua-tang.jpg', 312, 2026, 50, 0, N'Kim Đồng', N'9786042399579', 4, 1, 42, 1, CAST(175000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (436, N'Bộ Dan Da Dan - Tập 9 - Tặng Kèm Special Cover', N'Yukinobu Tatsu', N'Nhà Xuất Bản Kim Đồng', CAST(42750.00 AS Decimal(18, 2)), N'Dan Da Dan - Tập 9 Để đánh bại con quái thú đang tấn công, Okarun nảy ra ý định biến đổi lớp nano skin từng dùng để sửa chữa nhà Momo, nhưng cậu lại không thể hình dung rõ hình dạng cần tái cấu trúc. Xung phong tưởng tượng thay cậu lại chính là người bị cuốn vào vụ việc: Sakata Kinta “Dê xồm”. Bằng trí tưởng tượng của Kinta, nhà của Momo bất ngờ biến thành một robot khổng lồ…', N'https://cdn1.fahasa.com/media/catalog/product/d/a/dan-da-dan_tap-9_bia_special-cover.jpg', 194, 2026, 50, 0, N'Kim Đồng', N'9786042416672', 22, 1, 10, 1, CAST(29925.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (437, N'Bộ 86-EIGHTY SIX - Alter.1 - Đôi Nét Thanh Xuân Của Tử Thần - Bản Đặc Biệt - Tặng Kèm 2 Postcard', N'Asato Asato, Shirabii, I-IV', N'IPM', CAST(100000.00 AS Decimal(18, 2)), N'86-EIGHTY SIX - Alter.1 - Đôi Nét Thanh Xuân Của Tử Thần Tận hưởng tuổi trẻ thì đâu phân biệt địa điểm. Dù là ở giữa chiến trường, họ vẫn đã có “thanh xuân”. Trên trận địa chết chóc, lúc nghỉ ngơi dọc đường rồi lại xông pha chiến đấu, ở đất nước băng tuyết lần đầu đặt chân tới. Cùng chiến hữu, anh chị em, người yêu, người thân… quây quần bên bàn, cùng nhau nâng chén, còn có lúc cùng chúc mừng sinh nhật. Đó là khoảnh khắc yên bình ngắn ngủi của Shin, Lena và chiến hữu, những người bị định sẵn số mệnh ngày ngày chỉ có chiến đấu. Đây là một “86” khác, gói ghém những niềm hạnh phúc nhỏ bé, khiến người đọc ước mong ngày mai những thiếu niên thiếu nữ kia sẽ lại có được chút yên bình. Một tuyển tập nhiều truyện ngắn tặng kèm các đợt phát hành/sự kiện hoặc từng được đăng trên Dengeki Bunko Magazine, và còn có các truyện mới toanh do tác giả Asato Asato chấp bút!', N'https://cdn1.fahasa.com/media/catalog/product/3/0/300725.jpg', 276, 2025, 50, 0, N'Lao Động', N'8935250717175', 4, 1, 42, 27, CAST(70000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (438, N'Bộ Bộ Sách Đuổi Theo Mùa Hạ - Tập 1 + Tập 2 (Bộ 2 Tập) (Tái Bản 2025)', N'Mộc Qua Hoàng', N'AZ Việt Nam', CAST(280000.00 AS Decimal(18, 2)), N'Bộ Sách Đuổi Theo Mùa Hạ - Tập 1 + Tập 2 (Bộ 2 Tập) Đây là câu chuyện thầm yêu lẫn nhau cực ngọt ngào và đáng yêu của một cặp đôi thanh mai trúc mã. Trì Diệu và Lâm Chiết Hạ đã quen biết nhau từ nhỏ, khi ấy Trì Diệu vẫn còn là một cậu nhóc yếu ớt thường xuyên ra vào bệnh viện như cơm bữa, còn Lâm Chiết Hạ là cô bé nghịch ngợm hiếu động, thích đứng lên bảo vệ người khác, tự xưng là "anh Hạ" cầm đầu đám trẻ con quậy phá trong phố Ngõ Nam. Hai đứa trẻ vô tư cứ thế nắm tay nhau cùng trải qua biết bao mùa hạ rộn tiếng ve kêu, dù luôn miệng trêu chọc cà khịa nhau nhưng không một ai có thể xen vào bầu không khí giữa họ. Thế rồi tất cả đã thay đổi khi cả hai cùng đỗ vào trường trung học số Hai Liên Vân. Từ đấy, họ cùng sánh vai đến trường, cùng làm bài tập, cùng vượt qua những rung động ngây ngô của tuổi hoa niên. Chính vào vào cái năm mười sáu tuổi ấy, Lâm Chiết Hạ phát hiện hình như tình cảm mà cô dành cho Trì Diệu đã chẳng còn đơn thuần như trước… *** Ở mỗi thời khắc anh đuổi theo cô, dường như cô cũng đang đuổi theo mùa hạ, một mùa hạ có sự tồn tại của đối phương.', N'https://cdn1.fahasa.com/media/catalog/product/7/f/7fcbb597511044589db1ae6ab834d58a.jpg', 880, 2025, 50, 0, N'Dân Trí', N'8935325033117', 5, 1, 14, 8, CAST(196000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (439, N'Bộ Bến Xe (Tái Bản 2020)', N'Thương Thái Vi', N'Đinh Tị', CAST(54720.00 AS Decimal(18, 2)), N'Bến Xe (Tái Bản 2020) Bến Xe Thứ tôi có thể cho em trong cuộc đời này chỉ là danh dự trong sạch và một tương lai tươi đẹp mà thôi. Thế nhưng, nếu chúng ta có kiếp sau, nếu kiếp sau tôi có đôi mắt sáng, tôi sẽ ở bến xe này… đợi em.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935212349208.jpg', 284, 2020, 50, 0, N'Văn Học', N'8935212349208', 5, 1, 14, 24, CAST(38304.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (440, N'Bộ Khi Tóc Mai Đã Bạc Người Có Còn Bên Ta? - Bản Đặc Biệt - Tặng Kèm Bookmark + Postcard + Standee + Huy Hiệu', N'Phù Hoa', N'AZ Việt Nam', CAST(224100.00 AS Decimal(18, 2)), N'Khi Tóc Mai Đã Bạc Người Có Còn Bên Ta? Vào hôm kỉ niệm ngày cưới, Du Dao đi chợ mua thức ăn, chớp mắt một cái đã xuyên tới bốn mươi năm sau, người chồng hào hoa phong nhã giờ đây đã biến thành một ông giáo sư già điềm đạm. Lúc trẻ, vợ thầy Giang đột nhiên mất tích, được xác nhận là đã qua đời, thầy góa vợ đằng đẵng bốn mươi năm. Không ngờ lại có ngày vợ thầy trở về, đã vậy dung mạo còn chẳng hề thay đổi. Thế là tin đồn giáo sư Giang trâu già gặm cỏ non lan truyền khắp trường, thanh danh, khí tiết thầy gìn giữ cả đời đứng trước nguy cơ bị hoen ố. Thời gian thấm thoắt thoi đưa, khi dung nhan của ta không còn, người vẫn nguyện yêu ta chứ?', N'https://cdn1.fahasa.com/media/catalog/product/n/g/ng1.jpg', 424, 2026, 50, 0, N'Dân Trí', N'8935325036347-qt', 5, 1, 43, 8, CAST(156870.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (441, N'Bộ Những Kẻ Xuất Chúng (Tái Bản 2021)', N'Malcolm Gladwel', N'Alpha Books', CAST(111000.00 AS Decimal(18, 2)), N'Cuốn sách Những kẻ xuất chúng sẽ giúp bạn tìm ra câu trả lời thông qua các phân tích về xã hội, văn hóa và thế hệ của những nhân vật kiệt xuất như Bill Gates, Beatles và Mozart, bên cạnh những thất bại đáng kinh ngạc của một số người khác (ví dụ: Christopher Langan, người có chỉ số IQ cao hơn Einstein nhưng rốt cuộc lại quay về làm việc trong một trại ngựa). Theo đó, cùng với tài năng và tham vọng, những người thành công đều được thừa hưởng một cơ hội đặt biệt để rèn luyện kỹ năng và cho phép họ vượt lên những người cùng trang lứa. Với giọng văn lôi cuốn và cách kể chuyện hết sức có duyên, Malcom Gladwell cũng viện dẫn rất nhiều giai thoại thú vị như tại sao phần lớn các cậu bé giỏi môn khúc côn cầu lại sinh vào tháng một, tại sao con cái của những người Do Thái nhập cư lại trở thành những luật sư quyền lực nhất New York, tại sao truyền thống văn hóa của nền nông nghiệp lúa nước lại có thể giúp trẻ em châu Á giỏi toán... Nhưng không chỉ có thế. Thông qua những ví dụ này, Gladwell muốn bàn luận về những con đường phức tạp dẫn đến thành công của con người. Thách thức niềm tin về “con người tự lực”, tác giả quả quyết rằng các vĩ nhân không tự dưng mà có, cũng không được thúc đẩy bởi thiên tài hay tài năng. Họ là những người được hưởng một “lợi thế vô hình” và cơ hội khác thường từ môi trường và hoàn cảnh, nhờ đó họ vươn tới những đỉnh cao mà người khác không thể đạt được. Theo ông, “một vài người xứng đáng với điều đó, một vài người khác thì không, một số người tạo ra thành công, một số đơn giản là do may mắn”.', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_230370.jpg', 416, 2021, 50, 0, N'NXB Thế Giới', N'8935251416909', 7, 1, 15, 7, CAST(77700.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (442, N'Bộ Nghĩ Giàu & Làm Giàu (Tái Bản 2020)', N'Napoleon Hill', N'FIRST NEWS', CAST(80000.00 AS Decimal(18, 2)), N'Nghĩ Giàu & Làm Giàu (Tái Bản) - (Tái bản của cuốn "Cách Nghĩ Để Thành Công") NGHĨ GIÀU VÀ LÀM GIÀU Think and Grow Rich - Nghĩ giàu và làm giàu là một trong những cuốn sách bán chạy nhất mọi thời đại. Đã hơn 60 triệu bản được phát hành với gần trăm ngôn ngữ trên toàn thế giới và được công nhận là cuốn sách tạo ra nhiều triệu phú, một cuốn sách truyền cảm hứng thành công nhiều hơn bất cứ cuốn sách kinh doanh nào trong lịch sử. Tác phẩm này đã giúp tác giả của nó, Napoleon Hill, được tôn vinh bằng danh hiệu “người tạo ra những nhà triệu phú”. Đây cũng là cuốn sách hiếm hoi được đứng trong top của rất nhiều bình chọn theo nhiều tiêu chí khác nhau - bình chọn của độc giả, của giới chuyên môn, của báo chí. Lý do để Think and Grow Rich - Nghĩ giàu và làm giàu có được vinh quang này thật hiển nhiên và dễ hiểu: Bằng việc đọc và áp dụng những phương pháp đơn giản, cô đọng này vào đời sống của mỗi cá nhân mà đã có hàng ngàn người trên thế giới trở thành triệu phú và thành công bền vững. Điều thú vị nhất là các bí quyết này có thể được hiểu và áp dụng bởi bất kỳ một người bình thường nào, hoạt động trong bất cứ lĩnh vực nào. Qua hơn 70 năm tồn tại, những đúc kết về thành công của Napoleon Hill đến nay vẫn không hề bị lỗi thời, ngược lại, thời gian chính là minh chứng sống động cho tính đúng đắn của những bí quyết mà ông chia sẻ. Sinh ra trong một gia đình nghèo vùng Tây Virginia, con đường thành công của Napoleon Hill cũng trải qua nhiều thăng trầm. Khởi đầu bằng chân cộng tác viên cho một tờ báo địa phương lúc 15 tuổi, đến năm 19 tuổi Hill trở thành nhà quản lý mỏ than trẻ tuổi nhất, sau đó bỏ ngang để theo đuổi ngành luật. Napoleon Hill còn kinh qua nhiều nghề như kinh doanh gỗ, xe hơi, viết báo về kinh doanh… Đó là những công việc ông từng nếm trải trước khi 25 tuổi! Song khác với những người thành đạt khác, ông cẩn thận phân tích từng sự kiện trọng đại trong đời mình, rút ra những bài học, rồi tiếp tục rút gọn chúng thành các nguyên tắc căn bản, tổ chức các nguyên tắc ấy thành triết lý sống và rèn luyện... Cơ hội đặc biệt đã đến với Hill trong một lần phỏng vấn để viết về chân dung Andrew Carnegie - ông “vua thép” huyền thoại của Mỹ đã đi lên từ hai bàn tay trắng. Từ lần phỏng vấn đó, Napoleon Hill có dịp tiếp cận với những con người thành đạt và có quyền lực nhất tại Mỹ để tìm hiểu và học hỏi những bí quyết thành công của họ, trong thế so sánh và kiểm chứng với những công thức thành công của Andrew Carnegie. Ông muốn qua đó có thể đúc kết và viết nên một cuốn sách ghi lại những bí quyết giúp các cá nhân bình thường thành những người thành công trong xã hội. Để thực hiện cuốn sách này, Napoleon Hill dành hầu như toàn bộ thời gian và công sức trong suốt gần ba mươi năm để phỏng vấn hơn 500 người nổi tiếng và thành công nhất trong nhiều lĩnh vực khác nhau, cùng hàng ngàn doanh nhân khác - cả những kẻ thất bại và những người thành công. Kết quả của những nghiên cứu không mệt mỏi đó là Think and Grow Rich - Nghĩ giàu và làm giàu - công thức, hay “cẩm nang” để trở thành vượt trội và được xã hội nể trọng. Cuốn sách cũng đưa Napoleon Hill vào danh sách một trong những tác giả có tác phẩm bán chạy nhất thế giới từ trước đến nay. Được viết ra từ vô số những câu chuyện có thật, tác phẩm có một sức thuyết phục và lay động rất lớn. Bạn không chỉ được biết bí quyết về sự thành công của các tên tuổi như Edison - nhà phát minh lỗi lạc mà thời gian rèn luyện trong trường học chỉ… vỏn vẹn 3 tháng; như Henry Ford - người bị coi là không có học vấn nhưng đã trở thành ông trùm trong nền công nghiệp xe hơi với một gia tài kếch xù… mà còn của rất nhiều cá nhân trong nhiều lĩnh vực khác nhau đã đi lên từ con số không. Think and Grow Rich - Nghĩ giàu và làm giàu là cuốn sách đầu tiên đưa ra triết lý thành đạt - một triết lý đầy đủ và toàn diện về thành công của cá nhân, đồng thời cung cấp cho bạn phương pháp để tạo một ý thức thành công cũng như đưa ra kế hoạch sơ bộ và chi tiết để đạt được thành công đó. Các bí quyết thành công được đề cập đến trong cuốn s', N'https://cdn1.fahasa.com/media/catalog/product/n/g/nghigiaulamgiau_110k-01_bia-1.jpg', 400, 2020, 50, 0, N'NXB Tổng Hợp TPHCM', N'8935086844342', 7, 1, 15, 25, CAST(56000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (443, N'Bộ Bẻ Khóa Bí Mật Triệu Phú - Khám Phá Tư Duy Làm Giàu (Tái Bản 2023)', N'Thomas J Stanley, William D Danko', N'FIRST NEWS', CAST(64000.00 AS Decimal(18, 2)), N'Bẻ Khóa Bí Mật Triệu Phú - Khám Phá Tư Duy Làm Giàu Cuốn sách bán chạy 3 năm liền của The New Your Times và có mặt trong danh sách bán chạy của The Wall Street Journal, Business Week, USA Today, Los Angeles Times . Đã hơn hai mươi năm kể từ khi hai tác giả Thomas J. Stanley và William D. Danko bắt đầu nghiên cứu về phương thức làm giàu. Ban đầu, họ chỉ thực hiện nghiên cứu đơn thuần, tức là khảo sát những người sống ở các khu vực thượng lưu trên khắp nước Mỹ. Nhưng rồi họ đã phát hiện một điều kỳ lạ: Nhiều người sống trong những ngôi nhà sang trọng và lái những chiếc xe đắt tiền thực ra lại không quá giàu có! Sự thật này kéo theo một sự thật còn kỳ lạ hơn: Nhiều người cực kỳ giàu có lại không sống ở những khu vực thượng lưu như vậy! Phát hiện nho nhỏ ấy đã thay đổi cuộc sống của họ, khiến một người trong nhóm nghiên cứu là Tom Stanley quyết định gác lại sự nghiệp học thuật để cho ra đời ba cuốn sách về hoạt động marketing hướng đến tầng lớp giàu có ở Hoa Kỳ. Tom trở thành chuyên gia cố vấn cho các tập đoàn chuyên cung ứng hàng hóa và dịch vụ cho tầng lớp thượng lưu, đồng thời còn tiến hành các chương trình nghiên cứu về tầng lớp giàu có cho 7 trong số 10 tập đoàn cung cấp dịch vụ tài chính hàng đầu ở Mỹ. Riêng Thomas J. Stanley và William D. Danko cũng đã tổ chức hàng trăm cuộc hội thảo về chủ đề nhắm đến sự giàu có. Tại sao lại có nhiều người quan tâm tới những buổi nói chuyện của họ đến vậy? Bởi vì họ đã khám phá ra ai mới thực sự là người giàu có. Và quan trọng hơn cả là họ chỉ ra được cái cách mà những người bình thường có thể làm để trở nên giàu có. Vậy thì có gì uyên thâm ẩn sau những khám phá này? Chính là đây: Hầu hết mọi người đều đã hiểu sai về khái niệm giàu có. Của cải không đồng nghĩa với thu nhập. Nếu hàng năm bạn kiếm được nhiều tiền và phung phí hết sạch thì bạn không thể giàu lên. Bạn sống vương giả thật đấy, nhưng của cải là số tài sản bạn tích lũy được, chứ không phải số tiền mà bạn tiêu đi. Vậy bạn phải làm thế nào để trở nên giàu có? Một lần nữa, hầu hết mọi người lại hiểu sai. Những trường hợp giàu có nhờ may mắn trúng xổ số, được thừa kế, địa vị xã hội cao hay thậm chí là sự thông minh xuất chúng rất hiếm xảy ra. Thông thường, của cải là kết quả của lối sống đề cao sự lao động chăm chỉ, tính kiên nhẫn, bền bỉ, làm việc có kế hoạch, và quan trọng hơn hết là tính tự giác kỷ luật. Chính vì những nghiên cứu giàu tính khoa học, những khái niệm về sự giàu có vô cùng mới mẻ đã mang đến sự yêu quý của bạn đọc dành cho « The Millionaire next door – Bẻ khóa bí mật triệu phú ». Quyển sách đã bán được hơn 2 triệu bản và là cuốn sách bán chạy 3 năm liền của The New York Times.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935086851609-2023.jpg', 208, 2023, 50, 0, N'Tổng Hợp Thành Phố Hồ Chí Minh', N'8935086851609-2023', 7, 1, 44, 25, CAST(44800.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (444, N'Bộ Vị Giám Đốc Một Phút', N'Ken Blanchard, Ph D Spencer Johnson, M D', N'FIRST NEWS', CAST(42000.00 AS Decimal(18, 2)), N'Vị Giám Đốc Một Phút Với hàng triệu bản được bán ra, "Vị giám đốc một phút" được xếp hạng là một trong những cuốn sách quản lý thành công nhất mọi thời đại. "Vị giám đốc một phút" kể về quá trình tìm kiếm và tích lũy những kinh nghiệm quản lý của một chàng trai trẻ vừa tốt nghiệp đại học. Trong suốt hành trình kéo dài ròng rã nhiều năm, anh đã chứng kiến nhiều cách quản lý khác nhau nhưng vẫn chưa tìm ra người và nơi mình mong được gặp, mãi cho đến khi anh gặp được một vị giám đốc rất đặc biệt - Vị giám đốc một phút. Đây là người thành công với phương pháp làm việc chỉ gói gọn trong vòng một phút nhưng rất hoàn hảo: Vừa tạo hiệu quả công việc cao nhất, vừa xây dựng được một môi trường làm việc thân thiện giữa các nhân viên với nhau. Nhờ áp dụng những bí quyết hữu ích từ "Vị giám đốc một phút", chàng thanh niên trẻ đã tìm ra phương cách quản lý cho riêng mình và anh cũng sớm trở thành giám đốc một phút. Những ý tưởng bổ ích trong "Vị giám đốc một phút" đã nhanh chóng lan rộng và được hàng triệu giám đốc, những nhà quản lý trong danh sách 500 tập đoàn, công ty hàng đầu thế giới của tạp chí Fortune cũng như các doanh nghiệp khắp thế giới đã và đang ứng dụng những kinh nghiệm quản lý quý báu trong cuốn sách này. Cuốn sách bé nhỏ này đã làm được những điều đáng ngạc nhiên: Làm tăng năng suất, hiệu quả trong công việc và những thành tích, tiến bộ đối với từng cá nhân cũng như đối với các công ty, tập đoàn lớn trên thế giới như Toyota, Toshiba, Doughnut, Wells Fargo, Sony Corp, Victoria’s Secret, Yellow Pages, Abbot Labs, Foodmaker, Hilton Hotels, Bayer Corporation… Charles Lee, chủ tịch công ty Verizon đã viết: “Sau ngần ấy năm, tôi vẫn cầm đến cuốn sách "Vị giám đốc một phút" trong những phút giây rãnh rỗi hiếm hoi nhằm ôn lại những kỹ thuật quản lý của mình. Cho đến lúc này, tôi chưa tìm thấy một cuốn sách nào có những lời hướng dẫn quản lý con người tốt hơn và dễ sử dụng hơn cuốn sách này.” "Vị giám đốc một phút" là một câu chuyện thú vị, dễ đọc và ngắn gọn, thể hiện ba bí quyết rất thiết thực: Mục tiêu một phút, một phút khen ngợi và một phút khiển trách đã liên tục xuất hiện trong danh sách những cuốn sách bán chạy nhất trong hơn hai thập kỷ qua và trở thành một hiện tượng toàn cầu. Bất cứ ai làm công tác quản lý cũng đều biết đến cuốn sách Vị Giám đốc một phút cũng như giá trị to lớn của nó. Báo chí nói gì về "Vị giám đốc một phút": "Khi nói đến việc học nghệ thuật giao tiếp của một người giám đốc, bạn không thể bỏ qua "Vị giám đốc một phút". Nó chứa đầy những lời khuyên của chuyên gia về việc giao tiếp có hiệu quả giữa quản lý và người làm của họ. Hãy đọc cuốn sách này nếu bạn mới trở thành một nhà quản lý, hoặc một nhà quản lý kỳ cựu sẵn sàng nâng cấp lối tiếp cận nhân viên của mình" –10 Cuốn Sách Tuyệt Vời Về Kinh Doanh Để Vươn Tới Thành Công Nhanh Hơn (Lao Động) "Áp dụng bí quyết "mục tiêu một phút" bạn có thể quản lý cuộc sống của bạn tốt hơn, mọi thứ có mục tiêu, kế hoạch rõ ràng hơn" –Chuyện cuối tuần: "Vị giám đốc một phút" và bài học – "Mục tiêu một phút" (CafeF) "Vị giám đốc một phút (The One minute manager - Spencer Johnson) rất hay, rất ngắn gọn và dễ đọc, hữu ích, hướng dẫn các thủ thuật quản lý hiệu quả. Sách khoảng vài chục trang mà mang nhiều bài học" - Hãy trở thành giám đốc một phút (Tuổi Trẻ) "Trong Vị giám đốc một phút – một trong những quyển sách bán chạy nhất mọi thời đại – hai tác giả Ken Blanchard và Spencer Johnson đã dựa vào những nghiên cứu của mình để đề ra phong cách quản trị linh hoạt nhằm giải quyết những mâu thuẫn cũng như những khó khăn trong vấn đề quản trị nhóm nói riêng và phát triển doanh nghiệp nói chung" - 4 giai đoạn quản trị doanh nghiệp startup (Infonet.vn) "Vị giám đốc một phút" là bí kíp để đạt được sự thành công trong giao tiếp giữa lãnh đạo với nhân viên. Cuốn sách này sẽ chỉ cho người đọc cách phá bỏ rào cản lãnh đạo với nhân viên, nó phù hợp cho dù bạn đang làm vị trí nào đi chăng nữa" –Thay vì lướt Facebook, bạn chỉ mất vài buổi tối để hoàn thành 9 cuốn sách tuyệt vời về kinh tế', N'https://cdn1.fahasa.com/media/catalog/product/z/3/z3171678206749_70bec29051b87bfc03da1e8d0d064542.jpg', 186, 2021, 50, 0, N'NXB Tổng Hợp TPHCM', N'8935086855270', 8, 1, 21, 25, CAST(29400.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (445, N'Right To Win - "Cửa Thắng" Của Nông Nghiệp Việt - Cách Thức Agris Và Betrimex Tham Gia Chuỗi Cung Ứng Toàn Cầu', N'Đặng Huỳnh Ức My', N'Cty Anbooks', CAST(256000.00 AS Decimal(18, 2)), N'Right To Win - "Cửa Thắng" Của Nông Nghiệp Việt - Cách Thức Agris Và Betrimex Tham Gia Chuỗi Cung Ứng Toàn Cầu Cuốn sách này không chỉ dành cho những nhà quản lý doanh nghiệp, mà còn cho nhà nghiên cứu, nhà hoạch định chính sách, nông dân và cả những ai quan tâm đến tương lai nông nghiệp Việt Nam. Khi đồng hành cùng chúng tôi qua từng trang sách, bạn sẽ tìm thấy những bài học thực tiễn trong hơn 50 năm xây dựng ESG tại AgriS và Betrimex; các case study cụ thể. Đó là câu chuyện làm thế nào để AgriS trở thành doanh nghiệp Việt Nam đầu tiên cung ứng đường cho Nestlé những năm 2000, làm thế nào để chúng tôi có thể đưa đường Việt Nam lên sàn giao dịch hàng hóa London và New York, làm thế nào để trở thành doanh nghiệp đầu tiên đạt chứng chỉ Bonsucro, loại chứng chỉ cao nhất của ngành mía đường quốc tế và nhận được nguồn tiền chi trả cho năng lực bền vững này từ Nestlé Thụy Sĩ; hay làm thế nào để Betrimex đạt chứng chỉ Fairtrade giúp nông dân Bến Tre có tiền xây trường, sửa đường xá, lắp đặt điện…; hay làm thế nào để các viện nghiên cứu đầu ngành của các nước bạn phải nể phục vì câu chuyện nhân nuôi ong mắt đỏ phục vụ cho canh tác hữu cơ, nền tảng của toàn bộ năng lực tích hợp ESG vào chiến lược như bây giờ. Trong khuôn khổ cuốn sách, chúng tôi muốn cùng bạn tiếp cận con đường kinh tế nông nghiệp công nghệ cao hướng tuần hoàn toàn diện, với những câu hỏi quan trọng: Vì sao lại là con đường này mà không phải con đường khác? Loại tư duy nào cần cho sự chuyển đổi từ sản xuất sang kinh tế nông nghiệp, từ “cày sâu cuốc bẫm” sang trồng trọt thông minh, từ mua bán địa phương sang kinh doanh toàn cầu? Loại văn hóa nào để dẫn dắt tiến trình này đi đến đích, tạo ra lợi ích đột phá cho kinh tế, ổn định xã hội, hài hòa các bên liên quan, và bảo vệ môi trường? Và trên hết, phương thức nào để có thể cộng lực, đồng kiến tạo và thúc đẩy các bên tham gia vào một sân chơi tri thức, khó khăn nhưng đầy tiềm năng của nông nghiệp Việt Nam? Và vì sao phải tích hợp ESG vào nền tảng vận hành, và hiểu ESG ở gốc rễ, bản chất bền vững, không chỉ dừng lại ở tuân thủ và đo lường. Khi mở cánh cửa chuẩn mực quốc tế từ bên trong hai doanh nghiệp đang cung ứng cho 3.400 khách hàng tại 80 quốc gia, bạn sẽ thấy những “bí mật” được tích lũy hơn 50 năm của AgriS và Betrimex. Tuy nhiên, chúng tôi cũng tin rằng, ESG không phải đặc quyền của những tập đoàn lớn, mà là cơ hội để mọi doanh nghiệp Việt Nam nâng cấp, hội nhập và chia sẻ giá trị. Đồng hành cùng chúng tôi qua từng trang sách, bạn sẽ tìm thấy những bài học thực tiễn tại AgriS và Betrimex thông qua các case study cụ thể: Làm thế nào để AgriS trở thành doanh nghiệp Việt Nam đầu tiên cung ứng đường cho Nestlé những năm 2000, làm thế nào để chúng tôi có thể đưa đường Việt Nam lên sàn giao dịch hàng hóa London và New York, làm thế nào để trở thành doanh nghiệp đầu tiên đạt chứng nhận Bonsucro - tiêu chuẩn về sản xuất mía bền vững và nhận được nguồn tiền chi trả cho năng lực bền vững này từ Nestlé Thụy Sĩ; hay làm thế nào để Betrimex đạt chứng chỉ Fairtrade - tiêu chuẩn thương mại công bằng, và nguồn tiền từ đó giúp nông dân Bến Tre làm đường sá, hỗ trợ phân bón hữu cơ cho các hộ khó khăn, hỗ trợ các gia đình có người thân bị bệnh hiểm nghèo; hay làm thế nào để các viện nghiên cứu đầu ngành của các nước bạn phải nể phục vì câu chuyện nhân nuôi ong mắt đỏ phục vụ cho canh tác hữu cơ, nền tảng của toàn bộ năng lực tích hợp ESG vào chiến lược. Vì vậy, cuốn sách cũng có thể hữu ích cho những người mang theo câu hỏi: Làm sao để kiến tạo chuẩn mực quốc tế cho doanh nghiệp của mình? Làm sao để tham gia vào chuỗi cung ứng quốc tế? Ngành nông nghiệp giải quyết vấn đề phát thải như thế nào, và đóng góp vào tiến trình thực thi Net Zero 2050 của quốc gia ra sao? Cuốn sách này được hoàn thành vào tháng 9/2025, một năm đặc biệt, năm bản lề cho vận hội mới của đất nước, cũng là dấu mốc hơn nửa thế kỷ phát triển của AgriS và Betrimex. Với mong muốn góp phần vào tiến trình suy ngẫm, tái định hình nông nghiệp Việt, kiến tạo vận hội mới ch', N'https://cdn1.fahasa.com/media/catalog/product/r/i/right-to-win-cua-thang-cua-nong-nghiep-viet---1.jpg', 252, 2025, 50, 0, N'Phụ Nữ Việt Nam', N'9786326234848', 8, 1, 21, 20, CAST(179200.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (446, N'High Output Management - Quản Trị Hiệu Suất Cao - Bí Quyết Tối Ưu Năng Suất Mọi Đội Nhóm', N'Andrew S.Grove', N'CÔNG TY CỔ PHẦN SÁCH OMEGA VIỆT NAM', CAST(118000.00 AS Decimal(18, 2)), N'High Output Management - Quản Trị Hiệu Suất Cao - Bí Quyết Tối Ưu Năng Suất Mọi Đội Nhóm Trong cuốn sách này, cựu chủ tịch kiêm giám đốc điều hành của Intel, Andrew Grove chia sẻ quan điểm của ông về cách xây dựng và điều hành một tổ chức. Một cẩm nang thực tế giúp xử lý các tình huống kinh doanh thực tế và cũng là một bản tuyên ngôn quản lý mạnh mẽ với khả năng cách mạng hóa cách chúng ta làm việc. Cuốn sách này đề cập đến ba nội dung chính 1. Phương pháp quản trị hướng đến hiệu suất, nghĩa là sẽ áp dụng một số nguyên tắc và quy định trong quy trình sản xuất – một lĩnh vực luôn đặt hiệu suất lên hàng đầu – sang những lĩnh vực khác của công tác điều hành doanh nghiệp, đặc biệt là trong quy trình làm việc của nhà quản lý. 2. Công việc của bất kỳ một tổ chức nào dù là doanh nghiệp hay cơ quan chính phủ, là một nỗ lực đến từ tập thể chứ không phải của một cá nhân. Ý tưởng này được đúc kết thành nguyên tắc mấu chốt của cuốn sách: Hiệu suất của nhà quản lý là hiệu suất của cả phòng ban do chính người đó điều hành hoặc gây ảnh hưởng. 3. Đội ngũ sẽ làm việc hiệu quả chỉ khi từng thành viên được khích lệ hoàn thành tốt nhất công việc của mình. Nội dung này trả lời câu hỏi: Liệu các công ty có thể áp dụng những biện pháp thúc đẩy “vận động viên” của mình thường xuyên thể hiện “phong độ xuất sắc nhất” không? Cuốn sách đồng thời cũng giúp tất cả chúng ta nâng cao hiệu suất, cải thiện sự nghiệp cá nhân, càng đóng góp nhiều giá trị cho tổ chức chúng ta càng trụ vững được trong thời kỳ biến động. Đối tượng của cuốn sách - Những quản lý cấp trung, những người thường bị coi là vô danh trong tổ chức nhưng lại nắm giữ những huyết mạch chính của công ty. - Những quản lý cấp cao, những nhà lãnh đạo, vốn vô cùng bận rộn nhưng luôn cần nắm rõ hoạt động trong tổ chức của mình, đặc biệt là các nhân viên. - Tất cả nhân viên ở mọi vị trí, cấp bậc trong bất cứ tổ chức nào, nếu các bạn đang muốn tìm chỗ đứng cho mình, đặc biệt trong giai đoạn biến động hiện nay, thì cuốn sách là một cẩm nang hữu ích giúp các bạn trụ lại qua nhiều thay đổi khắc nghiệt. THÔNG TIN TÁC GIẢ Andrew S. Grove (1936-2016), sinh ra tại Budapest, Hungary, di cư đến Hoa Kỳ vào năm 1956. Ông đồng sáng lập Intel và trở thành chủ tịch của tập đoàn vào năm 1979, rồi giữ vị trí giám đốc điều hành vào năm 1987.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935251422764.jpg', 206, 2025, 50, 0, N'Công Thương', N'8935251422764', 8, 1, 45, 11, CAST(82600.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (447, N'Tạo Video Triệu Views Với Capcut AI', N'Unica, Sam Nguyễn', N'CÔNG TY CỔ PHẦN ĐÀO TẠO TRỰC TUYẾN UNICA', CAST(239000.00 AS Decimal(18, 2)), N'Tạo Video Triệu Views Với Capcut AI Trong thời đại video ngắn bùng nổ trên các nền tảng mạng xã hội, việc biết cách tạo ra những video thu hút và lan tỏa mạnh mẽ đã trở thành một lợi thế lớn cho bất kỳ ai muốn xây dựng thương hiệu cá nhân, kinh doanh online hay phát triển sự nghiệp sáng tạo nội dung. Tuy nhiên, rất nhiều người gặp khó khăn khi bắt đầu: không biết lên ý tưởng, mất nhiều thời gian chỉnh sửa video, hoặc e ngại những công cụ dựng video quá phức tạp. Cuốn sách Tạo Video Triệu Views với Capcut AI của tác giả Sam Nguyễn được xây dựng như một bản đồ thực chiến, giúp bạn từng bước làm chủ quy trình sáng tạo video chỉ với một chiếc điện thoại. Không dừng lại ở việc hướng dẫn thao tác, cuốn sách còn giúp bạn hiểu tư duy tạo nội dung viral, cách thu hút người xem ngay từ những giây đầu tiên và tận dụng sức mạnh của AI trong CapCut để viết kịch bản, tạo giọng đọc, thiết kế hình ảnh và dựng video nhanh chóng, tiết kiệm đến 90% thời gian. Bên cạnh kiến thức trong sách, bạn còn được tặng kèm video hướng dẫn chi tiết, 14 dự án thực tế để luyện tập giúp việc học trở nên trực quan và dễ áp dụng ngay vào thực tế. Đăng ký cuốn sách ngay hôm nay để bắt đầu hành trình sáng tạo video chuyên nghiệp, xây dựng nội dung thu hút.', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786326285727.jpg', 240, 2026, 50, 0, N'Tri Thức', N'9786326285727', 9, 1, 11, 10, CAST(167300.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (448, N'[Sách Đồng Giá 40K] Mượn Xu Thế, Lên Xu Hướng - Đột Phá Thương Hiệu Từ Con Số 0', N'Kim Thương Đại Thúc', N'AZ Việt Nam', CAST(40000.00 AS Decimal(18, 2)), N'Sản phẩm có tình trạng chất lượng tương đương 80% so với hàng mới. Lưu ý: Các sản phẩm thuộc [Sách Đồng Giá] sẽ không được áp dụng chính sách đổi trả của Fahasa.com Mượn Xu Thế, Lên Xu Hướng - Đột Phá Thương Hiệu Từ Con Số 0 “MƯỢN XU THẾ, LÊN XU HƯỚNG - ĐỘT PHÁ THƯƠNG HIỆU TỪ CON SỐ 0” - Giải mã cơn sốt “đu trend” trong chiến lược xây dựng thương hiệu. Nhờ sự phát triển rầm rộ của mạng xã hội, hàng loạt xu hướng như bánh đồng xu, trà chanh giã tay, cafe muối… đã được ra đời. Nắm bắt cơ hội làm giàu, không ít người dốc tiền ra khởi nghiệp để “đu trend” kiếm lời. Một câu hỏi đặt ra rằng: Liệu sau khi trào lưu qua đi, họ sẽ tiếp tục công việc kinh doanh như thế nào? Theo khảo sát của Nielsen, có tới 59% khách hàng có xu hướng chọn mua sản phẩm/dịch vụ của những thương hiệu quen thuộc. Thế nhưng, việc xây dựng thương hiệu có thực sự cần thiết trong khi vô số doanh nghiệp nổi tiếng đang rơi vào khủng hoảng? Làm thế nào để sống sót trong “thời đại bắt trend” này? Quy luật phát triển bền vững của thị trường là gì?... Tất cả sẽ được tác giả Kim Thương Đại Thúc - người được mệnh danh là “Thiên tài quảng cáo nghìn năm có một” giải đáp trong cuốn sách “Mượn xu thế, lên xu hướng - Đột phá thương hiệu từ con số 0”. Bằng kinh nghiệm thực hiện hàng nghìn chiến dịch quảng cáo chuyên nghiệp trên 20 quốc gia, tác giả sẽ chia sẻ những bí quyết marketing hiệu quả như: cách tạo trend thay vì bắt trend, thời điểm vàng để xây dựng thương hiệu, phương pháp nghiên cứu tâm lý khách hàng để thúc đẩy tiêu dùng, quy tắc “lấy yếu địch mạnh” cho những doanh nghiệp trẻ… Sáng tạo và dễ ứng dụng, “Mượn xu thế, lên xu hướng - Đột phá thương hiệu từ con số 0” chính là lời giải cho bài toán xây dựng thương hiệu và cách tỉnh táo trước những “làn sóng” trend marketing ngày nay. Hy vọng cuốn sách sẽ giúp các bạn tự tin tìm ra ưu thế cá nhân, mượn thế lớn để làm việc lớn.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935325017131_1.jpg', 272, 2024, 50, 0, N'Thanh Niên', N'3300000061467-mau115', 9, 1, 11, 8, CAST(28000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (449, N'Bộ Tăng Tốc Bán Hàng Bằng SPIN (Tái Bản 2024)', N'Neil Rackham', N'CÔNG TY CỔ PHẦN SÁCH OMEGA VIỆT NAM', CAST(97000.00 AS Decimal(18, 2)), N'Tăng Tốc Bán Hàng Bằng SPIN Trong lĩnh vực quản trị kinh doanh, bán hàng luôn được coi là một nghề đầy sức hấp dẫn và thú vị. Có lẽ vì như một chuyên gia bán hàng đã nói, hầu như chúng ta ai cũng phải bán một cái gì đó. Nhưng để thành công trong bán hàng lại là việc không hề đơn giản. Đã có rất nhiều cuốn sách viết về bán hàng. Mỗi cuốn lại tiếp cận bán hàng theo những khía cạnh và cách thức khác nhau. Nhưng khác với các cuốn sách về nghệ thuật bán hàng, Cuốn sách Tăng tốc bán hàng bằng SPIN của tác giả Neil Rackham không nói về nghệ thuật bán hàng thông qua các bí kíp mà đưa ra mô hình chuỗi câu hỏi SPIN (viết tắt của Situation questions, Problem questions, Implication questions, Need-payoff questions hay còn gọi là các câu hỏi Tình hình, câu hỏi Vấn đề, câu hỏi Gợi ý và câu hỏi Chi phí nhu cầu). Cuốn sách Tăng tốc bán hàng bằng SPIN của Neil Rackham không phải là lý thuyết sáo rỗng về cách bán hàng mà là những nghiên cứu hết sức khoa học và cụ thể của Huthwaite – công ty chuyên nghiên cứu về phương pháp bán hàng hiệu quả của Neil Rackham. Đọc Tăng tốc bán hàng bằng SPIN , bạn có thể thấy được sự khác nhau giữa bán hàng quy mô lớn và bán hàng quy mô nhỏ. Bạn cũng sẽ hiểu được tại sao có những thủ thuật bán hàng có thể thành công với các cuộc bán hàng quy mô nhỏ nhưng lại kém hiệu quả với các cuộc bán hàng quy mô lớn và rất, rất nhiều điều thú vị khác chỉ có thể tìm thấy trong Tăng tốc bán hàng bằng SPIN . Quan trọng hơn, Tăng tốc bán hàng bằng SPIN còn giúp bạn biến lý thuyết thành những chiến lược bán hàng hiệu quả hơn. Tăng tốc bán hàng bằng SPIN của Neil Rackham là cuốn sách gây được rất nhiều sự chú ý của giới bán hàng chuyên nghiệp và của những ai thật sự coi bán hàng là một nghệ thuật. Thông tin về tác giả NEIL RACKHAM nổi tiếng trên toàn thế giới với tư cách là diễn giả, nhà nghiên cứu, đào tạo, viết sách về bán hàng và marketing. Ba trong số các cuốn sách của ông đã lọt vào danh sách bestseller của tờ The New York Times, và các tác phẩm của ông đã được dịch ra trên 50 thứ tiếng. Neil Rackham là chủ tịch, đồng thời là người sáng lập công ty Huthwaite, Inc. Công ty của ông chuyên nghiên cứu, tổ chức các buổi seminar và tư vấn về bán hàng cho hơn 200 doanh nghiệp hàng đầu tại Mỹ như Xerox, IBM, AT&T, Kodak và Citicorp.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935251421668.jpg', 326, 2024, 50, 0, N'Công Thương', N'8935251421668', 9, 1, 46, 11, CAST(67900.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (450, N'Bộ Tiếp Thị 4.0 - Dịch Chuyển Từ Truyền Thống Sang Công Nghệ Số (Tái Bản 2022)', N'Philip Kotler, Hermawan Kartajaya, Iwan Setiawan', N'NXB Trẻ', CAST(89000.00 AS Decimal(18, 2)), N'Quyển cẩm nang vô cùng cần thiết cho những người làm tiếp thị trong thời đại số. Được viết bởi cha đẻ ngành tiếp thị hiện đại, cùng hai đồng tác giả là lãnh đạo của công ty MarkPlus, quyển sách sẽ giúp bạn lèo lái thế giới không ngừng kết nối và khách hàng không ngừng thay đổi để có được nhiều khách hàng hơn, xây dựng thương hiệu hiệu quả hơn, và cuối cùng kinh doanh thành công hơn. Ngày nay khách hàng không có nhiều thời gian và sự chú ý dành cho thương hiệu của bạn – và họ còn bị bao quanh bởi vô số các chọn lựa. Bạn phải tách khỏi đám đông, phải nổi trội, để gây sự chú ý và truyền đạt thông điệp mà khách hàng muốn nghe. “Tiếp thị 4.0” tận dụng tâm lý thay đổi của khách hàng để tiếp cận nhiều khách hàng hơn và khiến họ gắn bó với thương hiệu hơn bao giờ hết. Quyển sách cho bạn kiến thức sâu rộng để bạn thành công trong thế giới tiếp thị ngày nay: Khám phá những nguyên tắc mới trong tiếp thị; Nổi bật và tạo ra những khoảnh khắc WOW; Xây dựng nền tảng khách hàng trung thành và có tiếng nói; và Biết ai sẽ là người định hình tương lai của các chọn lựa của khách hàng… Quyển sách gồm ba phần, với các nội dung: “Phần đầu tiên của cuốn sách là kết quả quan sát của chúng tôi về thế giới chúng ta đang sinh sống. Chúng tôi bắt đầu bằng cách bám sát ba thay đổi lớn đang định hình thế giới chúng ta. Chúng tôi đi vào chi tiết hơn để khám phá xem khả năng kết nối đã thay đổi cơ bản cuộc sống của con người như thế nào. Không chỉ dừng lại ở đó, chúng tôi đi sâu hơn vào một số nhóm tiểu văn hóa chính trong kỷ nguyên số - đó là giới trẻ, phụ nữ và công dân mạng, hứa hẹn sẽ là nền tảng cho một thế hệ khách hàng mới. Phần thứ hai cũng là phần trọng tâm của cuốn sách, sẽ thảo luận về cách người làm tiếp thị có thể gia tăng hiệu suất bằng cách tìm hiểu về hành trình khách hàng trong kỷ nguyên số. Phần này sẽ giới thiệu một hệ thống mới các chỉ số tiếp thị và cách nhìn hoàn toàn mới về cách đánh giá hoạt động tiếp thị của chúng ta. Chúng tôi cũng đào sâu hơn vào một số ngành quan trọng và cách áp dụng những ý tưởng từ “Tiếp thị 4.0” vào các ngành này. Cuối cùng, phần thứ ba miêu tả chi tiết về các chiến thuật chủ đạo của “Tiếp thị 4.0”. Chúng tôi bắt đầu với hoạt động tiếp thị lấy con người làm trung tâm với mục tiêu nhân cách hóa thương hiệu với các giá trị của con người. Sau đó, chúng tôi tiếp tục thảo luận chuyên sâu về tiếp thị nội dung nhằm tạo ra thảo luận giữa các khách hàng. Ngoài ra, chúng tôi còn mô tả những cách giúp người làm tiếp thị có thể áp dụng phương thức tiếp thị tích hợp đa kênh nhằm tăng doanh thu cao hơn. Sau cùng, chúng tôi đào sâu vào các khái niệm về sự gắn kết với khách hàng ở kỷ nguyên số.”', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8934974179559.jpg', 264, 2022, 50, 0, N'Trẻ', N'8934974179559', 9, 1, 46, 34, CAST(62300.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (451, N'Cách Nhìn Mới Về Vàng - The New Case For Gold', N'James Rickards', N'NXB Trẻ', CAST(81000.00 AS Decimal(18, 2)), N'Cách Nhìn Mới Về Vàng - The New Case For Gold ** Sách bán chạy nhất trên USA Today và sách kinh doanh bán chạy nhất trên Wall Street Journal ** Họ nói rằng John Maynard Keynes đã gọi vàng là một "thánh tích man rợ". Họ nói rằng không có đủ vàng để chống đỡ cho nền tài chính và thương mại. Họ nói rằng nguồn cung vàng không thể tăng đủ nhanh để chống đỡ cho tăng trưởng thế giới. Họ đã sai. Trong bản tuyên ngôn đầy táo bạo này, tác giả sách bán chạy nhất và nhà bình luận kinh tế James Rickards đã lên tiếng bênh vực vàng — vừa với tư cách một vật lưu trữ tài sản không thể thay thế, vừa với tư cách một tiêu chuẩn cho tiền tệ. Mức độ bất ổn chính trị toàn cầu và biến động thị trường ngày càng tăng cao. Vàng, thứ tài sản khôn ngoan mà ai cũng nên sở hữu, đã trở thành công cụ bảo toàn tài sản quan trọng nhất đối với các ngân hàng cũng như cá nhân. Dựa trên các nghiên cứu điển hình trong lịch sử, lý thuyết tiền tệ và kinh nghiệm cá nhân với tư cách một nhà đầu tư của mình, Rickards kết luận rằng: • Vụ sụp đổ tài chính tiếp theo sẽ lớn gấp nhiều lần cuộc khủng hoảng năm 2008. • Tình trạng mua vào trong hoảng loạn và chỉ có các ngân hàng trung ương, quỹ phòng hộ và những người chơi lớn khác mới có thể mua được vàng sẽ xảy ra sớm hơn chúng ta tưởng. • Việc chủ động chuẩn bị để đương đầu với những gì sắp xảy ra với tư cách một quốc gia không bao giờ là quá muộn: luôn có đủ vàng cho một chế độ bản vị vàng nếu chúng ta ấn định một mức giá ổn định, không gây giảm phát. Cung cấp hướng dẫn rõ ràng về số lượng vàng cần mua và nơi cất giữ nó, lập luận ngắn gọn, đầy tính kích thích trong cuốn sách này sẽ thay đổi cách nhìn của bạn về “thánh tích man rợ” này mãi mãi.', N'https://cdn1.fahasa.com/media/catalog/product/n/x/nxbtre_full_06222021_032231.jpg', 224, 2021, 50, 0, N'NXB Trẻ', N'8934974174868', 10, 1, 17, 34, CAST(56700.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (452, N'How Money Works - Hiểu Hết Về Tiền - Bìa Cứng', N'DK', N'Nhã Nam', CAST(248000.00 AS Decimal(18, 2)), N'How Money Works - Hiểu Hết Về Tiền Cẩm nang giới đơn giản, dễ hình dung nhất từ trước đến nay về tiền tệ và hệ thống tài chính thế giới. Tiền đến từ đâu? Sự khác biệt giữa giàu có và thu nhập là gì? Các chính phủ kiểm soát tiền tệ như thế nào? Tại sao một khoản nợ lại là tốt? How money works – Hiểu hết về tiền tìm hiểu cách thức các chính phủ kiểm soát tiền tệ, cách các công ty kiếm ra tiền, cách các thị trường tài chính vận hành, cách các cá nhân tối đa hóa thu nhập thông qua đầu tư… Đưa ra định nghĩa cho hàng trăm khái niệm, cùng với những kiến thức nền tảng nhất về các hệ thống tài chính, như trái phiếu, cổ phiếu, tiền mã hóa, bitcoin, quản lý nợ, tránh vỡ nợ trực tuyến và gọi vốn cộng đồng, cũng như cách tiền vận hành thế giới.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235243682.jpg', 258, 2024, 50, 0, N'Thế Giới', N'8935235243682', 10, 1, 17, 29, CAST(173600.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (453, N'Trung Quốc Thoát Khỏi Bẫy Nghèo Như Thế Nào', N'Yuen Yuen Ang', N'CÔNG TY TNHH TRUYỀN THÔNG VÀ GIÁO DỤC LYCEUM', CAST(245000.00 AS Decimal(18, 2)), N'Trung Quốc Thoát Khỏi Bẫy Nghèo Như Thế Nào Trung Quốc đang trong bầu không khí kỉ niệm 73 năm thành lập nước Cộng Hòa Nhân Dân Trung Hoa. Gác lại những mâu thuẫn chính trị, ta không thể phủ nhận những thành tựu phát triển vượt bậc của đất nước này, đặc biệt là về kinh tế. Trên tinh thần học hỏi để tiến bộ, Book Hunter xin gửi đến bạn cuốn sách TRUNG QUỐC THOÁT KHỎI BẪY NGHÈO NHƯ THẾ NÀO của nữ tiến sĩ Yuen Yuen Ang, cuốn sách mới nhất thuộc Tủ sách Kiến Tạo của chúng mình. Được ngợi ca là “thay đổi cuộc chơi” và “xoay chuyển đấu trường”, TRUNG QUỐC THOÁT KHỎI BẪY NGHÈO NHƯ THẾ NÀO đã thúc đẩy một mô hình mới trong sự phát triển của nền kinh tế chính trị và làm sáng tỏ sự trỗi dậy của Trung Quốc. Làm thế nào để một đất nước nghèo nàn bạc nhược có thể thoát khỏi cạm bẫy đói nghèo? Các nhà kinh tế chính trị thường đưa ra ba câu trả lời: “trước tiên hãy kích thích tăng trưởng”, “trước tiên hãy xây dựng thể chế tốt”, hoặc “một số quốc gia may mắn đã được thừa hưởng thể chế tốt dẫn đến tăng trưởng”. Yuen Yuen Ang bác bỏ cả ba học phái này và các giả định cơ bản của chúng bao gồm nhân quả tuyến tính, thuyết cơ giới và thuyết tất định của lịch sử. Thay vào đó, bà đưa ra một mô hình mới dựa trên các hệ thống có khả năng thích nghi phức tạp, bao gồm thực tế về sự phụ thuộc lẫn nhau và khả năng đổi mới của nhân loại. Kết hợp với lăng kính gốc này cùng hơn 400 cuộc phỏng vấn với các quan chức và doanh nhân Trung Quốc, Ang đã tái hiện một cách có hệ thống quá trình phức tạp đã biến Trung Quốc từ vũng nước tù của chủ nghĩa xã hội trở thành kẻ phá bĩnh toàn cầu chỉ trong 35 năm. Trái ngược với những quan niệm sai lầm phổ biến, bà cho thấy điều đã thúc đẩy sự thay đổi lớn của Trung Quốc không phải là chế độ kiểm soát độc tài tập trung mà là “sự ứng biến có định hướng” – chỉ đạo từ Bắc Kinh song hành với sự ứng biến từ dưới lên của các quan chức địa phương. Phân tích của bà cho thấy hai bài học lớn về sự phát triển. Thứ nhất, sự thay đổi mang tính chuyển đổi đòi hỏi một hệ thống quản lí có khả năng thích nghi trao quyền cho các nhân tố ở cấp cơ sở để đưa ra giải pháp mới cho các vấn đề đang tiến triển. Thứ hai, bước đầu tiên thoát khỏi bẫy nghèo là “sử dụng những gì bạn có” – khai thác các nguồn lực hiện có để khởi động các thị trường mới, ngay cả khi điều đó đồng nghĩa với việc bất chấp các tiêu chuẩn của “Thế giới thứ nhất”. Được nghiên cứu một cách táo bạo và tỉ mỉ, Trung Quốc thoát khỏi bẫy nghèo như thế nào mở ra một hướng tư duy hoàn toàn mới cho các nhà nghiên cứu, nhà thực hiện và bất kì ai đang tìm cách xây dựng hệ thống có khả năng thích nghi.', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786048468118.jpg', 417, 2022, 50, 0, N'Đà Nẵng', N'9786048468118', 10, 1, 47, 17, CAST(171500.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (454, N'Bộ Nền Kinh Tế Tăng Trưởng Và Sụp Đổ Như Thế Nào? (Tái Bản 2023)', N'Peter D Schiff, Andrew J Schiff', N'Cty Sách Dân Trí', CAST(125000.00 AS Decimal(18, 2)), N'Nền Kinh Tế Tăng Trưởng Và Sụp Đổ Như Thế Nào? Hàng ngày, tất cả chúng ta đều tham gia vào các hoạt động kinh tế. Các phương tiện thông tin đại chúng như truyền hình, báo chí, internet v.v… cũng đầy rẫy những bài viết, phân tích hay đưa tin về các sự kiện kinh tế. Tuy nhiên, với đa số người dân, kinh tế học dường như vẫn là điều gì đó khó hiểu, trừu tượng, một lĩnh vực mà chỉ các “chuyên gia” mới biết và dám bàn đến mà thôi. Chính vì lẽ đó, trong những năm gần đây nhiều học giả kinh tế nước ngoài đã bắt đầu biên soạn những cuốn sách đơn giản, dễ hiểu, nhằm giới thiệu đến độc giả đại chúng những khái niệm cơ bản nhất của kính tế học, hy vọng giúp lĩnh vực khô khan này trở nên gần gũi hơn với mọi người. Cuốn sách này cũng nằm trong số đó.', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_40495_1.jpg', 290, 2023, 50, 0, N'Hồng Đức', N'9786043899993', 10, 1, 47, 21, CAST(87500.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (455, N'Những Quy Luật Của Bản Chất Con Người', N'Robert Greene', N'NXB Trẻ', CAST(231000.00 AS Decimal(18, 2)), N'Robert Greene, tác giả rất được ưa chuộng do New York Times bình chọn của các tác phẩm 48 nguyên tắc chủ chốt của quyền lực; 33 chiến lược của chiến tranh; Nghệ thuật quyến rũ; Nguyên tắc 50 - không sợ hãi; Làm chủ bản thân đã được nhà xuất bản Trẻ lần lượt xuất bản, và nhận được sự ủng hộ nhiệt tình của bạn đọc. Vẫn sử dụng thủ pháp luận cổ suy kim, trong tác phẩm mới nhất của mình, Những quy luật của bản chất con người, ông chuyển sang chủ đề hệ trọng nhất – thấu hiểu những thôi thúc và động cơ của mọi người, thậm chí cả khi họ không ý thức về chính mình. Trong cuốn sách này, Robert Greene tìm cách… biến độc giả thành một ‘quan sát viên điềm tĩnh hơn và có đầu óc chiến lược hơn’, miễn nhiễm với ‘bi kịch cảm xúc’. Đó là những hứa hẹn khá cao, nhưng ngay cả những kẻ hoài nghi cũng sẽ trở thành những người tin tưởng sau khi đọc kỹ tác phẩm chỉnh chu của ông. Việc vượt qua ‘quy luật của sự thiếu sáng suốt’, chẳng hạn, dẫn tới khả năng ‘mở rộng tâm trí bạn ra trước những gì thật sự đang diễn ra, trái hẳn với những gì bạn cảm thấy’. Điều tra thận trọng của Robert Greene về cái tôi và xã hội sẽ mang tới cho độc giả trung thành một quan điểm mới mẻ và tràn đầy sức sống.', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_38609.jpg', 892, 2020, 50, 0, N'NXB Trẻ', N'8934974168010', 12, 1, 7, 34, CAST(161700.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (456, N'Bộ Thay Đổi Câu Hỏi Thay Đổi Cuộc Đời (Tái Bản)', N'Tiến Sỹ Marilee Adams', N'Tân Việt', CAST(55250.00 AS Decimal(18, 2)), N'Thay đổi câu hỏi thay đổi cuộc đời Tài sản giá trị nhất trên đời mà bạn có thể sở hữu được chính là một thái độ sống', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_244718_1_1498.jpg', 240, 2022, 50, 0, N'Lao Động', N'8935210289063', 12, 1, 7, 38, CAST(38675.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (457, N'Con Đường Chẳng Mấy Ai Đi', N'M. Scott Peck', N'CÔNG TY CỔ PHẦN VĂN HOÁ & CÔNG NGHỆ TUỆ TRI', CAST(115500.00 AS Decimal(18, 2)), N'Con Đường Chẳng Mấy Ai Đi Có lẽ không quyển sách nào trong thế kỷ này có tác động sâu sắc đến đời sống trí tuệ và tinh thần của chúng ta hơn Con Đường Chẳng Mấy Ai Đi. Với doanh số trên 10 triệu bản in trên toàn thế giới và được dịch sang hơn 25 ngôn ngữ, đây là một hiện tượng trong ngành xuất bản, với hơn mười năm nằm trong danh sách Best-sellers của New York Times. Với cách hành văn kinh điển và thông điệp đầy thấu hiểu, quyển sách Con Đường Chẳng Mấy Ai Đi giúp chúng ta khám phá bản chất của các mối quan hệ và của một tinh thần trưởng thành. Quyển sách giúp chúng ta học cách phân biệt sự lệ thuộc với tình yêu; làm thế nào để trở thành những bậc phụ huynh tinh tế và nhạy cảm; và cuối cùng là làm thế nào để sống chân thật với chính mình. Với dòng mở đầu bất hủ của quyển sách, "Cuộc đời này rất khó sống", thể hiện quan điểm hành trình phát triển tinh thần là một chặng đường dài và gian nan, Tiến sĩ Peck thể hiện sự đồng cảm, nhẹ nhàng dẫn dắt độc giả vượt qua quá trình khó khăn đó, để thay đổi hướng tới tầm mức thấu hiểu bản thân sâu sắc hơn.', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786044009674.jpg', 344, 2024, 50, 0, N'Dân Trí', N'9786044009674', 12, 1, 48, 13, CAST(80850.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (458, N'Bộ Dám Thay Đổi - Từ A Đến Z (Tái Bản 2020)', N'Inner Space, Covent Garden', N'FIRST NEWS', CAST(100740.00 AS Decimal(18, 2)), N'Trong cuốn sách này, ngoài việc chỉ ra những tâm trạng tiêu cực mà mọi người vẫn luôn phải đối diện trong cuộc sống, hai tác giả Inner Space và Covent Garden còn cung cấp cho bạn đọc tác hại mà những tâm trạng tiêu cực đó mang lại. Thêm vào đó, Inner Space và Covent Garden cũng giúp bạn đọc những cách thức để chuyến hóa những thái độ tiêu cực thành tích cực. Chẳng hạn với thái độ phàn nàn, hai tác giả chỉ ra: “Phàn nàn phá hỏng tâm trạng và triệt tiêu động lực của ta, cũng như của những người khác”. Để quên đi thái độ phàn nàn, hai tác giả đưa ra lời khuyên: “Luôn có điều gì đó để ta trân trọng và biết ơn, chẳng hạn như một mái nhà che mưa che nắng hay một buổi bình minh tuyệt đẹp”. Những trích dẫn đặc sắc trong cuốn sách: “Sự nhàm chán chỉ tạm thời nguôi ngoai trong khi ta mải mê với những trò tiêu khiển, nhưng ngay khi dừng cuộc chơi, ta lại rơi vào cảm giác chán chường”. “Nỗi sợ cũng giống như một thỏi nam châm. Nếu cứ tập trung vào nỗi sợ mơ hồ nào đó, dù không chủ ý thì bạn cũng sẽ hành động với nỗi sợ hãi, từ đó làm cho nó trở nên sống động y như thật”. “Những tổn thương quá khứ cứ mãi dai dẳng bởi vì ta liên tục hồi tưởng về chúng. Chính BẠN mới là người làm cho mình bị tổn thương”. “Ghen tị thường xuất phát từ việc hạ thấp bản thân và so sánh”.', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_226328.jpg', 106, 2020, 50, 0, N'NXB Tổng Hợp TPHCM', N'8935086851067', 13, 1, 22, 25, CAST(70518.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (459, N'Kĩ Năng Vàng Cho Học Sinh Trung Học - Học Cách Quản Lí Cuộc Sống (Tái Bản 2023)', N'Liu Yong', N'Nhà Xuất Bản Kim Đồng', CAST(32000.00 AS Decimal(18, 2)), N'Kĩ Năng Vàng Cho Học Sinh Trung Học - Học Cách Quản Lí Cuộc Sống Thế giới rộng lớn có biết bao điều phức tạp khiến những bạn trẻ mới chập chững bước vào đời phải bối rối, băn khoăn. Cuốn sách Học Cách Quản Lí Cuộc Sống của Liu Yong mang đến những câu chuyện, bài học giản dị, gần gũi, giúp các bạn trẻ phần nào đó thấu hiểu thế nào là tình yêu, biết cách ứng xử với thất bại, thành công, cùng những tình huống khó khăn khác trong cuộc sống. ĐÔI ĐIỀU VỀ TÁC GIẢ Liu Yong vừa là họa sĩ, nhà văn, vừa là diễn giả nổi tiếng, một người sống tích cực, chăm chỉ, luôn muốn vượt qua chính mình. Ông từng là họa sĩ tại Viện Bảo tàng Mĩ thuật Danville, họa sĩ chuyên trách tại Trường Đại học St.John’s, là Phó giáo sư Trường Saint Vincent tại Mĩ, là Giáo sư thỉnh giảng của Trường Đại học Hạ Môn, Trung Quốc. Cho đến nay Liu Yong đã xuất bản hơn một trăm đầu sách bằng tiếng Anh và tiếng Trung, những bài luận về cuộc sống cùng những bài tản văn truyền cảm hứng ấm áp của ông đã trở thành những cuốn sách bán chạy nhất. Ông cũng được mệnh danh là “nhà văn gắn kết tâm hồn với lứa tuổi thanh thiếu niên”. Ông đã từng quyên góp xây dựng 40 trường tiểu học và ông cũng là một trong số ít họa sĩ đương đại thường xuyên có tranh được vào Nhà đấu giá Quốc tế Sotheby’s. “Đọc thêm nhiều sách hơn, đi nhiều nơi hơn, suy nghĩ nhiều hơn, sáng tạo nhiều hơn, thì bạn càng dễ dàng đến với thành công.” - Liu Yong', N'https://cdn1.fahasa.com/media/catalog/product/k/i/ki-nang-vang-cho-hoc-sinh-trung-hoc_hoc-cach-quan-ly-cuoc-song_tb-2023.jpg', 124, 2023, 50, 0, N'Kim Đồng', N'8935244895131', 13, 1, 22, 1, CAST(22400.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (460, N'Sống An Vui (Tái Bản 2025)', N'Khangser Rinpoche', N'FIRST NEWS', CAST(36500.00 AS Decimal(18, 2)), N'Sống An Vui Theo thống kê của Tổ chức Y tế thế giới (WHO), mỗi năm trên thế giới có hơn một triệu người chết vì tự sát. Trung bình, cứ 40 giây thì có người tự kết liễu đời mình. Và, tỉ lệ người tự tử đã tăng 60% trong 45 năm qua. Dự báo, đến năm 2020, cứ sau 20 giây sẽ có một người chết vì nguyên nhân này – một con số khủng khiếp. Cũng theo WHO, hơn 90% người chết vì tự sát mắc bệnh rối loạn tinh thần tại thời điểm họ qua đời, và nguyên nhân hàng đầu dẫn đến tự sát là chứng trầm cảm lâu ngày không được điều trị. Chưa bao giờ, giải tỏa những cảm xúc tiêu cực như căng thẳng, buồn bã, sợ hãi… lại trở nên cấp bách như hiện tại. “Trước đây khoảng 15 năm, một người em họ gọi điện cho tôi và nói có một người bạn đang trải qua căng thẳng và bất an. Em hỏi tôi có thể giúp bạn cậu ấy hay không. Lúc đó, tôi đang bận và bảo em tôi hãy đưa bạn cậu ấy đến gặp tôi sau. Một tuần sau đó, cậu bạn ấy đã tự sát. Tôi bị sốc và vô cùng buồn bã. Tôi đã có thể giúp cậu ấy nếu tôi có thời gian gặp cậu ấy sớm hơn”, thiền sư Khangser Rinpoche, tiến sĩ phật học đến từ Ấn Độ chia sẻ. Sau câu chuyện đau lòng này, ông dành thời gian nghiên cứu sâu về cơ chế của sự căng thẳng. Càng nghiên cứu, ông càng nhận ra giải tỏa căng thẳng không quá khó khăn. Đó cũng chính là động lực để thiền sư bắt tay vào thực hiện tập sách Sống An Vui, với mong muốn đây sẽ là chìa khóa để vượt qua sợ hãi, đối trị với những sân si, giận dữ trong lòng. Cung cấp cho người đọc những kiến thức chi tiết về những diễn biến nội tâm, quyển sách nhỏ này giúp người đọc nhận ra những yếu tố để sống đời hạnh phúc như: Cần có động lực sống; Thấu hiểu quy luật tự nhiên; Kiểm soát lòng tham; Đối trị phiền não…. Tám yếu tố mà tác giả đề cập là bản thống kê tương đối đầy đủ nhu cầu để một con người có thể tìm được bình an trong tâm tưởng. Không dừng lại ở đó, với những người đang vướng những cảm xúc tiêu cực, tập sách này sẽ là cẩm nang thực hành giải stress hiệu quả. Từng bài tập thanh lọc, rèn luyện, tiếp năng lượng tích cực cho cơ thể mà thiền sư đưa ra khá cụ thể, kèm theo hình minh họa chi tiết để bạn đọc có thể thực hành, luyện tập tại nhà. Đáng chú ý, không chỉ thiên về đời sống tâm lý, sách còn có những bài tập hỗ trợ các cơ quan nội tạng. Nghĩa là, giúp cơ thể khỏe mạnh cả về vật lý. Bởi, cơ thể khỏe mạnh sẽ là chỗ dựa tốt nhất cho việc vực dậy tinh thần. Văn phong giản dị, gẫn gũi… độc giả như đang được trò chuyện, tâm tình với một chuyên gia, với người dẫn dắt mình chạm đến bến bình yên. Như lời thiền sư Khangser Rinpoche, khi tâm căng thẳng, bất an được ngăn chặn và giải tỏa kịp thời, chúng ta không những tìm được bình an và hạnh phúc nội tại mà còn có thể lan tỏa niềm vui sống tới gia đình và cộng đồng xung quanh. Đây cũng là những gì bạn đọc có thể nhận được từ tập sách này.', N'https://cdn1.fahasa.com/media/catalog/product/-/1/-1740566419.jpg', 100, 2025, 50, 0, N'Hồng Đức', N'8935086858974', 13, 1, 49, 25, CAST(25550.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (461, N'Đừng Gọi Là Bí Ẩn - Tập 2 - Tặng Kèm Filmstrip', N'Yumi Tamura', N'Nhà Xuất Bản Kim Đồng', CAST(33250.00 AS Decimal(18, 2)), N'Đừng Gọi Là Bí Ẩn - Tập 2 Kunou Totonou bị bắt cóc trên chuyến xe buýt khi anh đang đi trên đường đến triển lãm mĩ thuật. Cả nhóm 10 người bao gồm cả tài xế bị đưa đến biệt thự, nơi kẻ bắt cóc của gia tộc Inudou gọi là “nhà của bọn tôi”. Bị nhốt trong một căn phòng, họ sẽ phải đối mặt với chuyện gì...? Tập truyện bao gồm phần cuối của chương 2. Chương 3 và 4 khởi đầu bằng chuyến đi của Totonou đến Hiroshima!!', N'https://cdn1.fahasa.com/media/catalog/product/d/u/dung-goi-la-bi-an_tap-2_bia_filmstrip.jpg', 192, 2026, 50, 0, N'Kim Đồng', N'9786042419055', 22, 1, 10, 1, CAST(23275.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (462, N'Cẩm Nang Tư Duy Đạo Đức', N'Richard Paul , Linda Elder', N'NXB Tổng Hợp TPHCM', CAST(24000.00 AS Decimal(18, 2)), N'Bộ sách CẨM NANG TƯ DUY này dành cho mọi bạn đọc, từ học sinh, sinh viên đến các giảng viên, các nhà nghiên cứu, doanh nhân, người đã đi làm cũng như quý phụ huynh... muốn nâng cao năng lực tư duy của mình. Học sinh, sinh viên có thể đọc cẩm nang như tài liệu tham khảo để học tốt các bộ môn; quý phụ huynh có thể sử dụng cẩm nang để vừa nâng cao năng lực tư duy của mình vừa giúp con em mình phát triển các kỹ năng tư duy cần thiết để học tốt; các giảng viên, nhà nghiên cứu có thể sử dụng cẩm nang để học tốt; các chủ đề của mình; người đã đi làm, doanh nhân... có thể áp dụng các kỹ năng, ý tưởng của cẩm nang vào công việc và cuộc sống. Bộ sách do “The Foundation for Critical Thinking (Quỹ Tư duy Phản biện) biên soạn. Đây là một tổ chức học thuật, cung cấp nhiều “cẩm nang” về tư duy khoa học được biên soạn chặt chẽ, chắt lọc, ngắn gọn và thiết thực, đúc kết nhiều thành tựu về phương pháp trên “mẫu số chung” là khuyến khích tư duy phân tích và phản biện, cùng với các kỹ năng nghe, nói, đọc, viết, học tập, và nghiên cứu một cách có thực chất, có chiều sâu và dễ dàng áp dụng vào cuộc sống.', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_119074.jpg', 88, 102016, 50, 0, N'NXB Tổng Hợp TPHCM', N'9786045856611', 13, 1, 49, 33, CAST(16800.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (463, N'Tiến Trình Thành Nhân (Tái Bản 2024)', N'Carl R. Rogers', N'Bách Việt', CAST(108500.00 AS Decimal(18, 2)), N'Tiến Trình Thành Nhân (Tái Bản 2024) Carl R. Roger sinh ngày 8/1/1902, tại Oak, Mỹ. Ông là con thứ trong một gia đình theo Tin Lành nghiêm khắc. Gia đình ông có trang trại rộng, cùng với lòng say mê nghiên cứu khoa học nên không khó hiểu khi ông theo học ngành Canh nông tại Đại học Wisconsin. Sau khi tốt nghiệp đại học, ông quyết định học ở Chủng viện Union Theologial Seminary năm 1924. Tại đây ông bị hấp dẫn bởi các bài thuyết giảng về tâm lý và tâm lý trị liệu. Sau đó ông chuyển tới trường Sư phạm thuộc đại học Columbia. Năm 1931, ông nhận bằng tâm lý học giáo dục và lâm sàng. Ông giảng dạy tại đại học Rochester từ năm 1935 và đến năm 1940 trở thành giáo sư tâm lý học lâm sang tại Đại học bang Ohio. Tại đây, ông có bài phát biểu đầu tiên về học thuyết phát triển mới và xây dựng phương pháp tiếp cận thân chủ mà ngày nay gọi là Liệu pháp lấy thân chủ là trọng tâm. Carl R. Rogers được coi là một trong những nhà tâm lý học có ảnh hưởng nhất thế kỷ 20. Liệu pháp Thân chủ Trọng tâm (Client-centered) của ông là một liệu pháp theo trường phái Nhân văn, tập trung vào cá nhân thân chủ (person-centered counseling). Ở đó nhà tâm lý đóng vai trò là người hướng dẫn và hỗ trợ để thân chủ tự trả lời được những câu hỏi của mình. Rogers nhận ra rằng thân chủ chính là người biết rõ được điều gì đã làm nên những tổn thương và các vấn đề nơi họ. Trong phòng trị liệu, Rogers tạo ra một bầu không khí cởi mở, an toàn, xây dựng mối tương giao hòa hảo, đáng tin cậy, chân thật giữa nhà trị liệu với thân chủ. Ông nhấn mạnh vào sự thấu cảm, chân thành và chấp nhận mọi điều từ thân chủ vốn như là mà không phán xét. Ông đặt niềm tin mạnh mẽ vào khả năng tự thay đổi và chữa lành ở bên trong mỗi con người. GIỚI THIỆU VỀ CUỐN SÁCH “Mỗi chúng ta có thể là một mảnh vỡ giữa đời này, chính chúng ta cũng vỡ làm muôn mảnh. Nhưng xin bạn hãy nhớ, luôn có những giọt vàng quý giá giúp bạn hàn gắn những mảnh vỡ ấy, để một ngày, bạn trở nên vẹn toàn hơn bao giờ hết. Từ giữa những đau thương khốn khó của đời, bạn luôn tỏa sáng lấp lánh” Trong tâm tưởng sinh viên khoa Tâm lí, đọc Tiến Trình Thành Nhân chẳng những là niềm tự hào để hỉ hả khoe ngầm với bạn bè, mà còn là mục tiêu phấn đấu đầy quyến rũ không dễ đạt tới ngay tắp lự. Với những ai ít nhiều trải nghiệm trong lĩnh vực chăm sóc sức khoẻ và làm kẻ trợ giúp nói chung, các phẩm chất nhân cách nhà trị liệu mà Carl Rogers khởi phát hơn nửa thế kỉ qua vẫn tiếp tục gợi mở nhiều điều đòi buộc phản tỉnh, thay đổi, dựng xây và phát triển, không chỉ kiến thức, kĩ năng mà bao gồm cả đạo đức nhân văn lẫn thành tựu tương tác liên nhân kết hợp dựa trên cả nền tảng khoa học và nghệ thuật. Với những ai đang tìm kiếm câu trả lời khi bản thân đang trải qua giai đoạn khủng hoảng tuổi đôi mươi, Tiến Trình Thành Nhân của Carl Rogers như người bạn lớn tâm tình bao chuyện ban sơ, ngỡ khô khan xa lạ mà rốt ráo, lại vô cùng thân thiết. Tiến Trình Thành Nhân vô hình trung, thiết thực giúp đỡ chính họ bước vào con đường tự giáo dục: Nhận chân sự thật của riêng mình, định hình tính cách và từ đólần hồi thấu hiểu về ý nghĩa và mục đích sống ở đời. CUỐN SÁCH MANG ĐẾN CHO BẠN ĐIỀU GÌ? Cuốn sách này không chỉ dành cho những nhà trị liệu, hơn hết, nó dành cho mỗi người trong chúng ta, đang trên hành trình Trở thành một con người - Một bản thể tự do và toàn vẹn, một cá nhân độc lập & sáng tạo. Đây là cuốn sách sẽ cho bạn những chỉ dẫn để: - Đến gần hơn và gần hơn nữa với nội tâm mình, dù cho là khó khăn hay khổ đau, dù cho khỏe mạnh hay tật bệnh, dù bất kể hoàn cảnh nào chăng nữa. - Thực hiện những mối tương giao giữa người với người một cách chân thành, ấm áp và hữu hiệu, giúp cho sự trưởng thành của mỗi người. - Tìm ra con đường đi tích cực để phát triển nhân cách, hàn gắn những vết thương và trở thành một con người toàn vẹn, tỏa sáng. Nhớ nhé, dù cho bạn là ai, đã từng trải qua điều gì, bạn ở đâu, luôn có những giọt vàng quý giá giúp bạn hàn gắn những mảnh vỡ tâm hồn và trong bạn luôn có một nguồn sáng chỉ lối dẫn đường đến một tương lai đẹp đẽ.', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786044908144.jpg', 456, 2024, 50, 0, N'Phụ Nữ Việt Nam', N'9786044908144', 14, 1, 29, 9, CAST(75950.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (464, N'Dám Bị Ghét (Tái Bản 2026)', N'Kishimi Ichiro, Koga Fumitake', N'Nhã Nam', CAST(127800.00 AS Decimal(18, 2)), N'Dám Bị Ghét Các mối quan hệ xã hội thật mệt mỏi. Cuộc sống sao mà nhạt nhẽo và vô nghĩa. Bản thân mình xấu xí và kém cỏi. Quá khứ đầy buồn đau còn tương lai thì mờ mịt. Yêu cầu của người khác thật khắc nghiệt và phi lý. TẠI SAO BẠN CỨ PHẢI SỐNG THEO KHUÔN MẪU NGƯỜI KHÁC ĐẶT RA? Dưới hình thức một cuộc đối thoại giữa Chàng thanh niên và Triết gia, cuốn sách trình bày một cách sinh động và hấp dẫn những nét chính trong tư tưởng của nhà tâm lý học Alfred Adler, người được mệnh danh là một trong “ba người khổng lồ của tâm lý học hiện đại”, sánh ngang với Freud và Jung. Khác với Freud cho rằng quá khứ và hoàn cảnh là động lực làm nên con người ta của hiện tại, Adler chủ trương “cuộc đời ta là do ta lựa chọn”, và tâm lý học Adler được gọi là “tâm lý học của lòng can đảm”. Bạn bất hạnh không phải do quá khứ và hoàn cảnh, càng không phải do thiếu năng lực. Bạn chỉ thiếu “can đảm” mà thôi. Nói một cách khác, bạn không đủ “can đảm để dám hạnh phúc”. [...] Bởi can đảm để dám hạnh phúc bao gồm cả “can đảm để dám bị ghét” nữa. [...] Chỉ khi dám bị người khác ghét bỏ, chúng ta mới có được tự do, có được hạnh phúc.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935235249219.jpg', 334, 2026, 50, 0, N'Dân Trí', N'8935235249219', 14, 1, 29, 29, CAST(89460.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (465, N'Bảy Đại Tội - Góc Nhìn Sinh Học Về Bản Chất Người', N'Guy Leschziner', N'CÔNG TY CỔ PHẦN SÁCH OMEGA VIỆT NAM', CAST(242100.00 AS Decimal(18, 2)), N'Bảy Đại Tội - Góc Nhìn Sinh Học Về Bản Chất Người “Bảy đại tội – sinh học của bản chất con người” - Giải mã những điều sâu kín nhất trong con người bằng khoa học thần kinh và được Financial bình chọn là cuốn sách hay nhất năm. Vì sao có người không thể kiểm soát cơn giận? Vì sao có những người luôn bị thôi thúc bởi thức ăn, tình dục, tiền bạc hoặc quyền lực? Điều gì khiến một người bình thường trở nên bạo lực, ích kỷ hoặc ám ảnh cực đoan? Trong “Bảy đại tội – Sinh học của bản chất con người”, Giáo sư thần kinh học Guy Leschziner dẫn dắt người đọc vào một hành trình khám phá những khía cạnh như tình dục, giết người, ngoại tình, tội phạm và bạo lực của con người. Những mặt này của bản chất con người không tồn tại đơn lẻ. Chúng được dệt lại với nhau bằng những sợi chỉ bền chắc của di truyền học, tâm lý học tiến hóa và bệnh học. Chính những khía cạnh sinh học ấy của con người đã định hình nên những động lực in dấu không thể xóa nhòa trong quá trình chúng ta kiến tạo thế giới của mình, đồng thời đặt nền tảng căn bản cho những hành vi ấy cũng như những lỗi lầm khác. CUỐN SÁCH CÓ GÌ ĐẶC BIỆT? - Khám phá Bảy mối tội đầu nổi tiếng trong văn hóa phương Tây bằng lăng kính khoa học thần kinh. - Dựa trên những ca bệnh có thật liên quan đến chấn thương não, động kinh, khối u, đột biến gen và tác dụng phụ của thuốc. - Giải thích các hành vi như bạo lực, ngoại tình, nghiện tình dục, tham ăn, ghen tuông, lòng tham hay chứng ái kỷ bằng các cơ chế sinh học trong não bộ. - Kết hợp kiến thức từ thần kinh học, di truyền học, tâm lý học tiến hóa và y học lâm sàng. - Văn phong gần gũi, giàu tính kể chuyện, dễ tiếp cận với độc giả đại chúng. NHỮNG CÂU HỎI HẤP DẪN MÀ CUỐN SÁCH ĐẶT RA - Một người trở nên hung hăng sau chấn thương não có hoàn toàn chịu trách nhiệm về hành vi của mình không? - Lòng tham là lựa chọn cá nhân hay là một cơ chế sinh tồn được lập trình từ quá trình tiến hóa? - Vì sao có người dễ nổi nóng, trong khi người khác lại bình tĩnh trước cùng một tình huống? - Điều gì khiến một số người rơi vào trạng thái ghen tuông hoặc ái kỷ cực đoan? - Ranh giới giữa "kẻ xấu" và "người bệnh" thực sự nằm ở đâu? BỐ CỤC CUỐN SÁCH Cuốn sách gồm 8 chương, được xây dựng như một hành trình đi từ những hành vi quen thuộc trong đời sống đến câu hỏi lớn nhất về con người. Phần 1: Giải mã Bảy đại tội Thịnh nộ Tham ăn Dục vọng Ganh tị Lười biếng Lòng tham Kiêu ngạo Ở mỗi chương, tác giả kể những câu chuyện có thật về các bệnh nhân với những thay đổi bất thường trong hành vi, từ đó giải thích vai trò của các vùng não, hormone và yếu tố di truyền đứng sau những biểu hiện tưởng chừng chỉ thuộc về đạo đức. Phần 2: Ý chí tự do Sau khi phân tích bảy đại tội, tác giả đặt ra câu hỏi trung tâm: Nếu hành vi của con người bị chi phối mạnh mẽ bởi cấu trúc não bộ, gen và môi trường sống, liệu chúng ta có thực sự sở hữu ý chí tự do? Đây cũng là phần sâu sắc nhất của cuốn sách khi mở rộng cuộc thảo luận sang các vấn đề về công lý, trách nhiệm cá nhân và cách xã hội nhìn nhận tội lỗi. Bìa sách sử dụng hình ảnh con rắn và quả táo – biểu tượng quen thuộc trong câu chuyện Adam và Eva của Kinh Thánh. Theo truyền thuyết, việc ăn trái cấm giúp con người có được tri thức để phân biệt thiện – ác, nhưng cũng mở đầu cho những đau khổ và sai lầm của nhân loại. Hình ảnh này chính là ẩn dụ cho chủ đề trung tâm của cuốn sách: hành trình tìm hiểu nguồn gốc của những "tội lỗi" đã đi cùng con người từ thuở sơ khai, và câu hỏi liệu chúng bắt nguồn từ lựa chọn đạo đức hay từ chính bản chất sinh học của chúng ta. Cuốn sách dành cho độc giả yêu thích: Khoa học thần kinh và tâm lý học, về bản chất con người, đạo đức và ý chí tự do, các câu chuyện khoa học được kể theo lối hấp dẫn, dễ đọc. “Bảy đại tội – Sinh học của bản chất con người” không chỉ giúp chúng ta hiểu rõ hơn về bộ não, mà còn buộc mỗi người phải nhìn lại những điều tưởng như quen thuộc nhất ở chính mình: những ham muốn, cảm xúc, sai lầm và lựa chọn tạo nên con người hôm nay. THÔNG TIN TÁC GIẢ Guy Leschziner Giáo sư chuyên ngành thần ki', N'https://cdn1.fahasa.com/media/catalog/product/c/c/ccfb08d9-0990-43f8-bebc-08e187b7.jpg', 392, 2026, 50, 0, N'Hà Nội', N'8935270705541', 14, 1, 50, 11, CAST(169470.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (466, N'Trị Liệu Nhận Thức Hành Vi Tích Hợp Chánh Niệm - Nguyên Tắc Và Thực Hành', N'Bruno A. Cayoun', N'CÔNG TY TNHH LP BOOKS', CAST(295200.00 AS Decimal(18, 2)), N'Trị Liệu Nhận Thức Hành Vi Tích Hợp Chánh Niệm - Nguyên Tắc và Thực Hành Trong tâm lý học hiện đại, CBT (Cognitive Behavioral Therapy - Liệu pháp Nhận thức Hành vi) là một trong những phương pháp trị liệu hiệu quả và phổ biến. Phương pháp CBT dựa trên giả định rằng cảm xúc và hành vi tiêu cực phần lớn bắt nguồn từ cách chúng ta suy nghĩ về sự việc, chứ không phải hoàn toàn do hoàn cảnh bên ngoài. Do đó, mục tiêu chính của CBT là giúp thân chủ nhận ra và thay đổi những suy nghĩ sai lệch, từ đó điều chỉnh cảm xúc và hành vi theo hướng tích cực. CBT là một phương pháp linh hoạt, có thể kết hợp với nhiều kỹ thuật trị liệu khác để tăng hiệu quả. Một trong những hướng kết hợp nổi bật là với Chánh niệm (Mindfulness) - một khái niệm có nguồn gốc từ Phật giáo, nay đã được ứng dụng trong tâm lý học lâm sàng như một kỹ thuật mang tính khoa học. Chánh niệm giúp người thực hành rèn luyện khả năng quan sát nội tâm, tiếp xúc trực tiếp với cảm xúc thay vì né tránh hay phản ứng theo thói quen. Từ sự kết hợp này, MiCBT (Mindfulness-integrated Cognitive Behavioral Therapy - Liệu pháp Nhận thức Hành vi tích hợp Chánh niệm) ra đời. Phương pháp này được phát triển bởi Tiến sĩ Bruno Cayoun, một nhà trị liệu, cũng là người thực hành chánh niệm, với trên 22 năm kinh nghiệm trị liệu, giảng dạy, điều hành viện MiCBT và có kinh nghiệm nghiên cứu tại đại học Tasmania, Úc. Ông xây dựng MiCBT như một mô hình trị liệu có cấu trúc rõ ràng, hướng đến điều trị các rối loạn như lo âu, trầm cảm, OCD, rối loạn lo âu xã hội và các khó khăn về điều tiết cảm xúc. Điểm đặc biệt là, MiCBT không mang màu sắc tôn giáo, dù sử dụng kỹ thuật thực hành Chánh niệm có nguồn gốc từ Phật giáo.Các kỹ thuật được điều chỉnh phù hợp với bối cảnh trị liệu hiện đại, dựa trên bằng chứng thực nghiệm. Chánh niệm trong MiCBT không chỉ giúp người học “nghĩ khác đi” như trong CBT, mà còn “trải nghiệm khác đi” - chấp nhận cảm xúc khó chịu một cách tỉnh thức thay vì né tránh. Từ nền tảng đó, cuốn sách Trị liệu Nhận thức Hành vi Tích hợp Chánh niệm: Nguyên tắc và Thực hành ra đời như một hướng dẫn toàn diện cho các nhà trị liệu, giảng viên và cả những người thực hành quan tâm đến MiCBT. Sách không chỉ trình bày lý thuyết một cách rõ ràng mà còn cung cấp hướng dẫn cụ thể từng bước để ứng dụng trong thực tế lâm sàng. Nội dung sách được chia thành 5 phần chính: - Phần 1: Làm rõ các khái niệm nền tảng; - Phần 2: Tập trung vào việc hiểu cách học các kỹ năng trị liệu; - Phần 3: Thể hiện các kỹ năng - hướng dẫn cách tiếp xúc với cảm xúc khó chịu; - Phần 4: Mô tả cách áp dụng MiCBT trong điều trị các rối loạn theo phân loại; - Phần 5: Dành cho việc huấn luyện người hướng dẫn MiCBT. Một điểm đáng lưu ý là cuốn sách hướng đến cả các nhà trị liệu tâm lý, người học và thực hành thiền Chánh niệm, cũng như những ai đang tìm kiếm một phương pháp tự giúp bản thân vượt qua khó khăn tâm lý. Dù chuyên sâu, nhưng sách được trình bày rõ ràng, giàu ví dụ thực tế, và đặc biệt là có thể trở thành một tài liệu tham khảo có giá trị lâu dài cho người hành nghề và người thực hành. Tác giả: Bruno A. Cayoun là nhà tâm lý học lâm sàng và nghiên cứu nổi tiếng, đặc biệt trong lĩnh vực chánh niệm và liệu pháp nhận thức hành vi (CBT). Ông đã hoàn thành học vị Tiến sĩ Tâm lý học Lâm sàng (DPsych) tại Đại học Tasmania. Bruno là người sáng lập Viện Chánh niệm Tích hợp (MiCBT Institute) tại Úc. Bruno đã xuất bản nhiều sách, bao gồm: - Mindfulness-integrated CBT: Principles and Practice (Wiley, 2011) - Mindfulness-integrated CBT for Well-Being and Personal Growth: Four Steps to Enhance Inner Calm, Self-Confidence and Relationships (Wiley, 2015) - The Clinical Handbook of Mindfulness-integrated Cognitive Behaviour Therapy (Wiley, 2019) (đồng tác giả) - The Mindfulness and Meditation Workbook for Anxiety and Depression (New Harbinger, 2024) (đồng tác giả) Ông cũng tham gia nhiều nghiên cứu quan trọng về giảm đau mãn tính, phát triển thang đo Equanimity Scale-16, và hiệu quả của MiCBT trong việc giảm trầm cảm và lo âu.', N'https://cdn1.fahasa.com/media/catalog/product/t/r/tr_-li_u-bia-chuyenin-_1_.jpg', 494, 2025, 50, 0, N'Tri Thức', N'9786044849331', 14, 1, 50, 15, CAST(206640.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (467, N'Bộ Cẩm Nang Tuổi Dậy Thì Dành Cho Bạn Trai (Tái Bản 2026)', N'Hà Minh', N'Minh Long', CAST(63000.00 AS Decimal(18, 2)), N'Cẩm Nang Tuổi Dậy Thì Dành Cho Bạn Trai Cho dù có là cậu bé vô tư đến thế nào đi chăng nữa thì chắc hẳn khi bước vào tuổi dậy thì các em cũng sẽ cảm nhận và chú ý đến những biến đổi về tâm sinh lí của bản thân và thấy chúng cũng vô cùng rắc rối. Trong khi rất nhiều chuyện mới chỉ hiểu biết nửa vời, các em đã phải đối diện với nhiều vấn đề như chuyện cơ thể dậy thì, chuyện quan hệ tình cảm hay những trách nhiệm mà giới tính của các em phải gánh vác, thậm chí còn phải đối diện với những mối nguy hiểm và cám dỗ xấu xa. Phải làm thế nào mới có thể hóa giải những bí ẩn này? Nên giữ kín trong lòng hay tâm sự với bạn bè? Nên thẳng thắn hỏi bố mẹ, thầy cô hay vụng trộm tìm hiểu từ những kênh thông tin “ngầm”… Hãy đọc cuốn sách này nhé!', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936067608748_2.jpg', 268, 2026, 50, 0, N'Thanh Niên', N'8936238102136', 15, 1, 23, 28, CAST(44100.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (468, N'Bộ 1001 Bí Quyết Dành Cho Tuổi Học Trò - Hướng Dẫn Sử Dụng Tình Bạn', N'Hoàng Anh Tú', N'Đinh Tị', CAST(51750.00 AS Decimal(18, 2)), N'“Bạn là người vươn ra tìm tay ta và chạm đến trái tim ta.” Bạn bè là không thể thiếu, là nguồn ánh sáng vô tận cho tâm hồn chúng ta. Nhưng nhiều khi kết bạn lại không dễ chút nào, nhất là khi ta là người hướng nội chẳng hạn? Rồi khi đã làm bạn rồi mà chẳng may xích mích, giận nhau thì làm thế nào? Và nếu người bạn đó phản bội, bỏ rơi ta hết lần này đến lần khác thì phải xử lý ra sao? Chúng ta phải làm như thế nào để tình bạn sẽ “nhân đôi niềm vui và chia sẻ nỗi buồn”, chứ không phải xóa tan niềm vui và làm lòng ta nặng trĩu? Trong cuốn sách này bạn sẽ tìm thấy toàn bộ những “cẩm nang” cần thiết để “sử dụng” tình bạn đấy! Làm sao để “sử dụng” tình bạn một cách hữu hiệu nhất, để chơi với bạn thật vui, để được chia sẻ nỗi buồn cùng bạn, để trái tim thực sự kết nối đến trái tim và tình bạn trở nên bền chặt? Ngoài ra còn là cách làm thế nào để kết thúc một tình bạn (điều mà hy vọng bạn sẽ cực kỳ hiếm khi phải thực hiện), bởi vì không phải người bạn nào cũng sẽ đi cùng ta đến hết cuộc đời.', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_223383.jpg', 152, 2021, 50, 0, N'NXB Hà Nội', N'8935212353410', 15, 1, 23, 24, CAST(36225.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (469, N'Bộ Kỷ Luật Tích Cực Trong Lớp Học (Tái Bản 2022)', N'Jane Nelsen, Linn Lott, H. Stephen Glenn', N'Phụ Nữ', CAST(62000.00 AS Decimal(18, 2)), N'Kỷ Luật Tích Cực Trong Lớp Học Với cuốn sách này, bạn sẽ học được cách: . Tạo một môi trường lớp học thúc đẩy tinh thần học thuật . Sử dụng hiệu quả sự khích lệ thay vì phần thưởng và lời khen ngợi . Giúp trẻ thấm nhuần những kỹ năng xã hội quan trọng và các hành vi tích cực qua các buổi sinh hoạt lớp . Hiểu được tại sao mời gọi trẻ tham gia vào quá trình giải quyết vấn đề lại hiệu quả hơn việc áp dụng hình phạt . Hiểu được động lực đằng sau hành vi của trẻ thay vì tìm kiếm nguyên nhân Và nhiều điều khác nữa… Nhiều năm qua, hàng triệu phụ huynh và giáo viên đã sử dụng những chiến lược hiệu quả của phương pháp Kỷ luật Tích cực để tìm lại sự ổn định và nền nếp tại gia đình và lớp học. Và trong các lớp học hiện nay, nơi giáo viên phải cạnh tranh với vô số thiết bị điện tử để dành được sự chú ý của học sinh, đồng thời vẫn phải đáp ứng những tiêu chuẩn chuyên môn và học thuật ngày càng cao, thì điều quan trọng hơn bao giờ hết là thầy cô cần có khả năng để chiến đấu với sự thờ ơ nơi các em, để lồng ghép những kỹ năng giải quyết vấn đề và để tạo một môi trường tối ưu hóa khả năng tiếp thu và học hỏi cho học sinh của mình.', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_219815_1.jpg', 256, 2022, 50, 0, N'Phụ Nữ Việt Nam', N'8935069921930', 15, 1, 51, 36, CAST(43400.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (470, N'Tâm Lý Học Đồng Hành - Bước Cùng Con, Đừng Bước Thay Con - Đồng Hành Dạy Con Đúng Cách Thông Qua 36 Câu Chuyện Thực Tế', N'Nhạc Hiểu Đông', N'Công ty TNHH Ecoblader', CAST(132000.00 AS Decimal(18, 2)), N'Tâm Lý Học Đồng Hành - Bước Cùng Con, Đừng Bước Thay Con - Đồng Hành Dạy Con Đúng Cách Thông Qua 36 Câu Chuyện Thực Tế Nuông chiều thì dễ, yêu thương mới khó. Áp đặt thì dễ, đồng hành mới khó. Nhưng là cha mẹ, bạn phải làm được. Bạn dành nhiều thời gian cho con, nhưng liệu bạn có thực sự đồng hành đúng cách? Nhiều bậc cha mẹ luôn ở bên con, nhưng lại thiếu sự hướng dẫn vào những thời điểm quan trọng. Họ lo cho con từng bữa ăn, giấc ngủ, chuyện học, chuyện chơi, dù có thể con không hề yêu cầu. Họ nghĩ rằng sự quan tâm ấy là trọn vẹn. Nhưng đến khi con thực sự cần cha mẹ—khi gặp mâu thuẫn với bạn bè, hay phải đối mặt với những thay đổi tâm lý tuổi mới lớn—thì cha mẹ lại lúng túng, né tránh, hoặc thậm chí gạt đi. Và rồi, họ tự hỏi: Tại sao mình hy sinh nhiều như vậy mà con lại không thấu hiểu? Bởi vì đồng hành không phải là kiểm soát, không phải là làm thay, mà là hướng dẫn và trao quyền. Bạn không thể mãi nắm tay con, nhưng có thể cho con đôi chân vững vàng để tự bước đi. Mỗi khi bạn làm giúp con một việc, bạn đang lấy đi cơ hội để con tự học hỏi. Thay vì chỉ giúp con giải bài tập, hãy dạy con cách tư duy. Thay vì bảo vệ con khỏi mọi thất bại, hãy dạy con cách đứng lên sau vấp ngã. Bạn không thể dạy một đứa trẻ 15 tuổi theo cách bạn dạy khi con 5 tuổi. Nếu bạn cảm thấy khó khăn khi đồng hành cùng con, thì đó là dấu hiệu con đang trưởng thành—và chính bạn cũng cần trưởng thành cùng con. Quyển sách này sẽ giúp bạn làm được điều đó.', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786043464269.jpg', 288, 2025, 50, 0, N'Kinh Tế Thành Phố Hồ Chí Minh', N'9786043464269', 17, 1, 0, 14, CAST(92400.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (471, N'90% Trẻ Thông Minh Nhờ Cách Trò Chuyện Đúng Đắn Của Cha Mẹ (Tái Bản 2019)', N'Urako Kanamori', N'Nhà Xuất Bản Kim Đồng', CAST(34000.00 AS Decimal(18, 2)), N'Bạn có bao giờ thốt ra những câu dù biết là không nên nói như “Còn lề mề đến bao giờ nữa hả?” hay “Chẳng được cái trò trống gì, đưa đây xem nào!”… nhưng vẫn lỡ lời không? Trong quá trình trẻ trưởng thành, những lời lẽ kiểu “Mày chẳng được cái tích sự gì!” trẻ phải nghe ngày ngày sẽ thẩm thấu qua vô thức, rồi sau đó trở thành ý thức coi mình chỉ là loại “vô dụng”. Không biết từ lúc nào, trẻ sẽ bắt đầu thực hiện những hành vi, lối sống không tốt. Trong cuốn sách này, chúng tôi sẽ giới thiệu tới quý vị phụ huynh những câu nói “có phép lạ” khiến các con trở thành những đứa trẻ “tự có ý thức” mà cha mẹ không cần cằn nhằn nhiều. Hơn nữa, đây hoàn toàn là những câu chúng ta có thể áp dụng ngay từ ngày hôm nay như “Mẹ luôn đứng về phía con!”, “Mẹ con mình cùng làm nhé!”… Về bản chất, mỗi đứa trẻ đều mang trong mình một “sức mạnh” tuyệt vời. Nhưng trước hết, chúng ta phải tin tưởng vào sức mạnh ấy đã! Khi được tin cậy, “sức mạnh” bên trong trẻ sẽ được nuôi dưỡng một cách tự nhiên. Cuốn sách này sẽ giới thiệu cách trò chuyện giúp khai phá sức mạnh ấy từ nhiều góc độ. Chắc chắn không chỉ các con mà ngay cả chính các bậc phụ huynh cũng sẽ thay đổi. Cuộc sống sẽ lại một lần nữa trở nên thật tuyệt vời. Cuốn sách này sẽ giúp mở rộng tiềm năng của trẻ tới vô hạn!', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_182756.jpg', 176, 2019, 50, 0, N'NXB Kim Đồng', N'8935244820799', 17, 1, 0, 1, CAST(23800.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (472, N'Khi Cha Mẹ Chưa Trưởng Thành Cảm Xúc', N'Lindsay C.Gibson', N'Thái Hà', CAST(120000.00 AS Decimal(18, 2)), N'Khi Cha Mẹ Chưa Trưởng Thành Cảm Xúc Cuốn sách này là một tài liệu hữu ích cho tất cả mọi người, những người đã từng chịu tổn thương trong quá khứ do những bậc cha mẹ chưa trưởng thành cảm xúc gây ra. Cuốn sách cũng dành cho những nhà tâm lý học, những nhà giáo dục quan tâm tới việc nuôi dạy và chăm sóc trẻ em. Các hành vi chưa trưởng thành cảm xúc ngày nay đang trở nên phổ biến, và những người chưa trưởng thành cảm xúc gây rất nhiều đau khổ cho mọi tầng lớp xã hội. Bởi vì các cá nhân chưa trưởng thành cảm xúc đeo đuổi việc thống trị người khác và coi mình là trung tâm, họ không để chỗ hoặc nguồn lực nào cho người khác được hoàn toàn là chính mình. Việc đặt quyền lợi của bản thân lên trên hết và tự biện minh cho mình đã chà đạp lên quyền lợi của người khác, cho họ quyền tự do ngược đãi, quấy rối, gây hại, bóc lột và có hành vi sai trái dưới mọi hình thức. Tuổi thơ mà những người có cha mẹ chưa trưởng thành cảm xúc đã trải qua có thể dẫn đến cảm giác cô đơn lâu dài, cũng như sự mâu thuẫn về các mối quan hệ nói chung. Cô đơn là kết quả của cảm giác không được quan tâm và không được đáp lại, cho dù bạn có cố gắng giao tiếp và kết nối đến đâu. Ở tuổi trưởng thành, những đứa trẻ này thường bị thu hút bởi những người bạn đời và bạn bè khiến họ bất mãn và thất vọng, những người dường như đều chỉ biết đến bản thân và từ chối thân thiết sâu sắc hơn. Đây đích thực là ngược đãi, một sự ngược đãi đầy độc hại. Không những thế, toàn bộ phương pháp nuôi dạy con cái của những bậc cha mẹ này là không lành mạnh về mặt cảm xúc, nó tạo ra một bầu không khí lo lắng và không đáng tin cậy giữa cha mẹ và con cái. Họ đối xử với trẻ theo những cách hời hợt, ép buộc và phán xét đến mức làm suy giảm lòng tin vào suy nghĩ và cảm xúc của chính bản thân trẻ, do đó, hạn chế sự phát triển trực giác, khả năng tự dẫn đường, khả năng hành động hiệu quả và tự chủ của trẻ. Cuốn sách sẽ giúp bạn hiểu được sự thiếu trưởng thành về mặt cảm xúc của cha mẹ đã ảnh hưởng đến bạn như thế. Bạn có thể tự trách bản thân hoặc tiếp tục hy vọng cha mẹ sẽ thay đổi, trong khi họ sẽ không bao giờ làm thế. Cuốn sách này sẽ giúp bạn nhìn ra được mình đang phải đương đầu với cái gì trong khi hiểu về cha mẹ mình sâu sắc nhất có thể. Trích đoạn sách Cuộc sống bên cạnh những người chưa trưởng thành cảm xúc Cha mẹ chưa trưởng thành cảm xúc và các cá nhân EI khác có phong cách giao tiếp rất dễ nhận biết. Mười trải nghiệm sau đây sẽ mô tả những gì bạn có thể gặp phải trong mối quan hệ với họ. 1. Bạn cảm thấy cô đơn khi ở cạnh họ Được nuôi dưỡng bởi cha mẹ chưa trưởng thành cảm xúc sẽ hình thành trong bạn sự cô đơn về mặt cảm xúc. Mặc dù họ có thể luôn ở đó với bạn nhưng về mặt tình cảm, bạn vẫn cảm thấy mình bị bỏ rơi. Cho dù bạn có cảm giác gia đình với cha mẹ chưa trưởng thành cảm xúc thì nó cũng rất khác với mối quan hệ cha mẹ và con cái gắn bó về mặt tình cảm. Cha mẹ chưa trưởng thành cảm xúc thích bảo ban con cái mình phải làm điều này điều kia nhưng họ không hề thoải mái trong việc vun đắp tình cảm với con. Họ có thể chăm sóc bạn chu đáo khi bạn đau ốm, nhưng lại không biết phải làm gì với những cảm xúc bị tổn thương hoặc trái tim tan vỡ của bạn. Do đó, họ có vẻ giả tạo và lúng túng khi phải cố gắng xoa dịu một đứa trẻ đang buồn khổ. 2. Cảm giác như đang tương tác một chiều và thấy chán nản Cha mẹ chưa trưởng thành cảm xúc chỉ quan tâm đến bản thân và thiếu đồng cảm khiến cho việc tương tác với họ mang tính chất một chiều. Cứ như thể họ đang tự giam cầm mình trong sự quan tâm vị kỷ vậy. Khi bạn cố gắng chia sẻ điều gì đó quan trọng về bạn, họ có thể sẽ ngắt lời bạn, thay đổi chủ đề và bắt đầu nói về bản thân họ hoặc bác bỏ những gì bạn đang nói. Con cái của những bậc cha mẹ chưa trưởng thành cảm xúc thường biết nhiều về các vấn đề của cha mẹ hơn những gì cha mẹ biết về mình. … 3. Bạn cảm thấy bị cưỡng ép và mắc kẹt Cha mẹ chưa trưởng thành cảm xúc bắt bạn phải đặt họ lên hàng đầu và để họ nắm quyền kiểm soát. Vì vậy, họ sẽ khiến bạn phải xấu hổ, cảm thấy tội lỗi hoặc sợ hãi cho đến k', N'https://cdn1.fahasa.com/media/catalog/product/k/h/khi-cha-me-chua-truong-thanh-cam-xuc_bia-1.jpg', 324, 2023, 50, 0, N'Lao Động', N'8935280914803', 17, 1, 52, 39, CAST(84000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (473, N'Nuôi Dạy Em Bé Có Chính Kiến', N'Alicia Vu', N'Skybooks', CAST(87000.00 AS Decimal(18, 2)), N'Nuôi Dạy Em Bé Có Chính Kiến Cuốn sách giúp bạn trong hành trình tìm lại chính kiến của mình Nuôi dạy con trong kỷ luật nhưng không làm thui chột chính kiến của trẻ Duy trì mối quan hệ lành mạnh, bình đẳng giữa cha mẹ - con cái Nuôi con, sẽ có lúc nhiều bậc phụ huynh phải đối mặt với trường hợp bé nói “KHÔNG” với tất cả mọi thứ bố mẹ yêu cầu. Con thường hành động trái ý và từ chối lắng nghe những lời dạy bảo của người lớn. Nhưng những lúc trẻ bướng bỉnh, khó bảo, nếu bố mẹ phản ứng mà không suy nghĩ thì chỉ khiến thái độ của con càng trở nên tiêu cực. Bởi trẻ con sinh ra đều có chính kiến và biết bản thân muốn gì. Bằng chứng là ngay từ khi sơ sinh, chúng đã biết quay đầu đi không bú nữa khi đã no. Chỉ cần người lớn đừng can thiệp và cố gắng thay đổi chúng, chúng sẽ giữ được cá tính và chính kiến đến khi trưởng thành. “Nuôi dạy em bé có chính kiến” - một cuốn sách giúp bạn trong hành trình tìm lại chính kiến của mình và bảo vệ chính kiến của con, trong khi vẫn duy trì mối quan hệ lành mạnh, bình đẳng giữa cha mẹ - con cái. Cuốn sách gồm có 3 phần: Phần 1: Nền tảng tâm lý học cơ bản Được viết bằng ngôn ngữ thông dụng, cách truyền tải dễ hiểu và ngắn gọn, giúp phụ huynh có nền tảng cơ bản về tâm lý trẻ. Đi kèm là các bài tập thực hành dễ áp dụng. Phần 2: Nuôi dạy em bé có chính kiến Bóc tách những lầm tưởng phổ biến về chính kiến, làm rõ ranh giới giữa kỷ luật và trừng phạt, định nghĩa lại về "giáo dục sớm", làm rõ lại khái niệm "giáo dục ôn hoà". Làm sao để nuôi dạy con trong kỷ luật mà không làm thui chột chính kiến của trẻ? Làm sao để duy trì những kết nối và yêu thương mà không trở thành nuông chiều thái quá? Phần 3: Những tình huống thường gặp Phân tích những tình huống thường gặp ở trẻ 0-6 tuổi và gợi ý cách xử lý cụ thể. Các trường hợp đó bao gồm: "ăn vạ", nói dối, xô xát, bắt nạt, tranh chấp, bám mẹ, không tự lập, đòi mua đồ chơi, vv... Một đứa trẻ tự tin với những lựa chọn của mình chính là đứa trẻ có chính kiến. Một đứa trẻ dám bảo vệ chính kiến của mình trước cha mẹ mới có thể bảo vệ chính kiến và bản thân trước xã hội. Bởi vậy, đừng uốn nắn con theo một phiên bản khuôn mẫu. Hãy là người đồng hành, yêu thương và giúp đỡ con trên hành trình trưởng thành tự tin, tự lập, được là chính mình bạn nhé!', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935325014062.jpg', 248, 2023, 50, 0, N'Thế Giới', N'8935325014062', 17, 1, 52, 37, CAST(60900.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (474, N'Mao - Tập 2', N'Rumiko Takahashi', N'NXB Trẻ', CAST(40850.00 AS Decimal(18, 2)), N'Mao - Tập 2 Nữ sinh trung học Nanoka Kiba 8 năm trước đã suýt chết vì một sự kiện siêu nhiên. Nhưng rồi một ngày nọ, cô nhận ra mình lại vướng vào những sự kiện siêu nhiên đầy nguy hiểm. May thay, lần này cô được Mao - một chàng trai bí ẩn đến từ không gian khác - giải cứu. Từ đó, câu chuyện về “vùng đất nơi hai thế giới giao nhau” bắt đầu.', N'https://cdn1.fahasa.com/media/catalog/product/n/x/nxbtre_full_03582026_035812.jpg', 190, 2026, 50, 0, N'Trẻ', N'8934974217404', 22, 1, 56, 34, CAST(28595.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (475, N'Bộ Who? Chuyện Kể Về Danh Nhân Thế Giới - Louis Pasteur (Tái Bản 2020)', N'Lee, Heejung, Team kids', N'Nhà Xuất Bản Kim Đồng', CAST(47000.00 AS Decimal(18, 2)), N'Các bạn có biết nhà bác học lỗi lạc thời Pháp Louis Pasteur đã phát minh ra vắc xin phòng bệnh than và bệnh dại, cứu nhân loại thoát khỏi những căn bệnh đáng sợ không? Tuy nhiên, ông không đăng kí bảo hộ những phát minh của mình mà cho phép mọi cá nhân, tổ chức có quyền sử dụng để phục vụ cuộc sống cộng đồng. Nhân loại sẽ mãi biết ơn Louis Pasteur, cha đẻ của thuyết học vi trùng, nhà bác học không chỉ có bộ óc thiên tài mà còn có trái tim ấm áp, tràn đầy tình yêu thương con người. “Khoa học không có ranh giới quốc gia, bởi vì kiến thức là tài sản của nhân loại.” - Louis Pasteur', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_45998.jpg', 160, 2020, 50, 0, N'NXB Kim Đồng', N'8935244846720', 23, 1, 4, 1, CAST(32900.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (476, N'Kỷ Luật Tích Cực Cho Ba Năm Đầu Đời', N'Jane Nelsen, Cheryl Erwin, Roslyn Duffy', N'Phụ Nữ', CAST(149760.00 AS Decimal(18, 2)), N'Kỷ Luật Tích Cực Cho Ba Năm Đầu Đời Kỷ luật Tích cực cho ba năm đầu đời nằm trong series sách best-seller Kỷ luật Tích cực của tác giả Jane Nelsenvới hơn hai triệu bản đã được bán ra trên toàn thế giới. Ấn bản nàyđược cập nhật với những công cụ mới nhất dành cho cha mẹ và người nuôi dưỡng trẻ tận hưởng khoảng thời gian ba năm đầu đời của trẻ một cách bình tĩnh, thư giãn, không căng thẳng, bấn loạn… Cuốn sách đồng thời cung cấp cho cha mẹ những kiến thức và kỹ năng thiết yếu để giúp đứa con bé bỏng của bạn hình thành những thới quen và đức tính tốt trong tương lai. ** “Một số phụ huynh nhiều năm qua đã thắc mắc: “Anh/chị có thể áp dụng Kỷ luật Tích cực với trẻ nhỏ ở những năm tháng đầu đời được thật sao? Tại sao chúng tôi cần phải áp dụng kỷ luật với trẻ sơ sinh và trẻ mới chập chững tập đi?”. Khi đọc cuốn sách này, bạn sẽ nhận ra rằng chúng tôi không hề khuyến khích bạn sử dụng hình phạt với trẻ nhỏ ở bất kỳ độ tuổi nào. Thay vào đó, chúng tôi tin tưởng rằng phương pháp Kỷ luật Tích cực dạy trẻ theo phương thức linh hoạt, tử tế và tôn trọng; truyền tải các kỹ năng xã hội và kỹ năng sống quý báu làm nền tảng cho sự thành công của các em trong các mối quan hệ xã hội và trong cuộc sống…” ** “ Kỷ luật Tích cực không phải là giải quyết vấn đề một cách tức thì, mà Kỷ luật Tích cực chính là tạo nên một môi trường để trẻ em có thể tự đưa ra quyết định lành mạnh đi theo các em trong suốt cuộc đời. ”', N'https://cdn1.fahasa.com/media/catalog/product/_/c/_ch_t_-04q---k_-lu_t-t_ch-c_c-155x235_3-nam-dau-doi_out_01.jpg', 450, 2023, 50, 0, N'Phụ Nữ Việt Nam', N'8935069923224', 18, 1, 20, 36, CAST(104832.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (477, N'Bộ Who? Chuyện Kể Về Danh Nhân Thế Giới - Leonardo Da Vinci (Tái Bản 2020)', N'Choe, Byeongkuk, Ahn, Hyungmo', N'Nhà Xuất Bản Kim Đồng', CAST(47000.00 AS Decimal(18, 2)), N'Leonardo da Vinci, thiên tài toàn năng, một trong những đại diện xuất sắc nhất của nghệ thuật và khoa học thời Phục Hưng. Không chỉ là tác giả của những tuyệt phẩm được ngợi ca là nổi tiếng nhất mọi thời đại như “Mona Lisa”, “Bữa ăn tối cuối cùng”…, Leonardo còn xuất sắc ở nhiều lĩnh vực khác như khoa học, triết học, sinh vật học, kiến trúc. Cho đến nay con người và tài năng xuất chúng của Leonardo vẫn là nguồn cảm hứng sáng tác, nghiên cứu của các nghệ sĩ. Nhà khoa học ở mọi lĩnh vực trên thế giới. “Tôi muốn biết về mọi thứ trên thế gian này, và khi đã biết thêm một điều, tôi càng muốn biết thêm nhiều hơn nữa!” Bộ tranh truyện WHO? người bạn thân thiết của thiếu nhi. Những câu chuyện về cuộc đời và sự nghiệp vĩ đại của các danh nhân sẽ đem đến cho các em những ước mơ và hoài bão cao đẹp!', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_34210.jpg', 160, 2020, 50, 0, N'NXB Kim Đồng', N'8935244841602', 23, 1, 4, 1, CAST(32900.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (478, N'Phương Pháp Giáo Dục Con Của Người Do Thái - Giúp Trẻ Tự Tin Bước Vào Cuộc Sống', N'Hà Minh', N'Minh Long', CAST(59500.00 AS Decimal(18, 2)), N'Phương Pháp Giáo Dục Con Của Người Do Thái - Giúp Trẻ Tự Tin Bước Vào Cuộc Sống Xem trọng giáo dục của cha mẹ với con cái là truyền thống tốt đẹp nổi bật nhất của dân tộc Do Thái. Mặc dù phải trải qua rất nhiều khó khăn và luôn phải phiêu bạt khắp nơi nhưng người Do Thái vẫn không quên dành cho con nền giáo dục tốt nhất. Và, họ còn tìm ra những phương pháp giáo dục con đặc biệt. Trí tuệ là tài sản lớn nhất của con Người Do Thái sùng bái trí tuệ, trân trọng kiến thức, họ không chỉ có ý thức bồi dưỡng cho con cái khả năng tự học mà còn thường xuyên cổ vũ trẻ thu nhận kiến thức qua nhiều con đường khác nhau. Khi trẻ còn nhỏ, đại đa số bố mẹ Do Thái dùng những vật dụng hằng ngày để giúp trẻ học ngoại ngữ. Ví dụ, họ thường sử dụng cốc, chậu rửa mặt, khăn mặt,… để đặt câu hỏi, giúp trẻ học những từ mới đơn giản. Ngoài ra, lúc dẫn con cái đi mua đồ, cha mẹ Do Thái thường chú ý đến ánh mắt của trẻ, chọn những đồ mà trẻ thích, nhân cơ hội đó dạy trẻ ngoại ngữ. Có thể thấy, cha mẹ Do Thái giống như người làm vườn chăm chỉ chăm chồi cây non, họ sẽ phân loại tri thức theo hứng thú và sở thích của con ở từng giai đoạn rồi mới truyền thụ cho trẻ, giúp trẻ tiếp thu nhẹ nhàng và hiệu quả. Tự lập tự cường là kĩ năng sinh tồn của con Cha mẹ Do Thái thường không nuông chiều con cái. Tình yêu của họ dành cho con đều có nguyên tắc, có mức độ. Nếu hành vi của trẻ vi phạm nguyên tắc, vượt quá giới hạn, cha mẹ sẽ không nương tay mà nghiêm khắc phê bình khuyên bảo. Những việc làm này khiến trẻ sống trẻ sống độc lập và có nguyên tắc, để khi trưởng thành là một người độc lập. Kỹ năng sống độc lập có vai trò rất quan trọng đối với sự trưởng thành và phát triển của trẻ. Từ nhỏ, cha mẹ Do Thái đã hướng dẫn con làm các công việc trong gia đình như đổ rác, gấp quần áo, lau nhà,… để rèn luyện khả năng sống độc lập cho trẻ. Dù đôi lúc việc dạy những kĩ năng này mất nhiều thời gian hơn so với việc bố mẹ tự làm nhưng họ vẫn kiên trì chỉ bảo cho trẻ đến cùng. Vì họ hiểu rằng: Chỉ khi để trẻ học kĩ năng sống, trẻ mới có thể thực sự tách khỏi bố mẹ, thích nghi với cuộc sống, với xã hội. Cho nên trong quá trình dạy con, các bậc cha mẹ cần học theo phương pháp này, hết sức kiên nhẫn để chỉ bảo cho trẻ. Quản lí tài chính là kĩ năng cơ bản của con Người Do Thái ngoài việc hiểu giá trị của đồng tiền còn truyền dạy những kiến thức đó cho con cái để thế hệ sau hiểu được giá trị của nó. Khi trẻ được 3 tuổi, cha mẹ bắt đầu giảng giải cho trẻ hiểu giá trị và công dụng của đồng tiền. Họ thường cùng trẻ chơi trò chơi đoán giá trị tiền tệ để nâng cao khả năng nhận biết đồng tiền cho con. Khi đi mua sắm, cha mẹ Do Thái thường để trẻ so sánh giá cả của các loại sản phẩm khác nhau nhằm bồi dưỡng khả năng chi tiêu của trẻ. Người Do Thái cho rằng dạy trẻ những kiến thức tài chính này là rất quan trọng vì người có khả năng quản lí tài chính và ý thức đầu tư giỏi sẽ biết kiếm tiền và nắm giữ tiền bạc. Các bậc cha mẹ nên học tập cách làm của người Do Thái, bồi dưỡng khả năng đầu tư, quản lí cho trẻ từ nhỏ để trẻ có một nền tảng vững chắc trong tương lai. Cuốn sách chia sẻ với các bậc cha mẹ bí quyết giáo dục trẻ của một trong những dân tộc thông minh nhất Thế giới. Còn chần chừ gì mà không mở cuốn sách này ra và chào đón tương lai thành công của con bạn!', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8936067605211.jpg', 244, 2022, 50, 0, N'NXB Phụ Nữ Việt Nam', N'8936067605211', 18, 1, 20, 28, CAST(41650.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (479, N'Bộ Kinh Nghiệm Từ Nước Nhật - 49 Bí Quyết Giúp Trẻ Lắng Nghe Và Truyền Đạt (Tái Bản 2023)', N'Arimoto Hidefumi, Koshimizu Kaori', N'Nhà Xuất Bản Kim Đồng', CAST(60000.00 AS Decimal(18, 2)), N'Kinh Nghiệm Từ Nước Nhật - 49 Bí Quyết Giúp Trẻ Lắng Nghe Và Truyền Đạt GIÁO DỤC GIAO TIẾP CHO TRẺ EM BẮT ĐẦU TỪ GIA ĐÌNH VÀ NHÀ TRƯỜNG - Làm thế nào để lắng nghe câu chuyện của bạn bè một cách tốt nhất? - Làm thế nào để trò chuyện một cách hiệu quả? - Làm thế nào để giải quyết mâu thuẫn hay ngăn chặn một cuộc xung đột? Ngày càng có nhiều trẻ em không giỏi lắng nghe câu chuyện của bạn bè và không biết cách thể hiện cảm xúc của chính mình, khả năng giải quyết các vấn đề thông qua giao tiếp tích cực của trẻ cũng gặp nhiều hạn chế. Trong cuốn sách này, chúng tôi hướng dẫn trẻ có được các cách thức giao tiếp hiệu quả, thông qua các tình huống sinh động và minh hoạ hấp dẫn. Đây là tài liệu cần thiết cho phụ huynh và giáo viên nuôi dạy nên những đứa trẻ giỏi giao tiếp và truyền đạt. MỜI CÁC BẠN TÌM ĐỌC BỘ SÁCH KINH NGHIỆM TỪ NƯỚC NHẬT - 42 bí quyết giúp trẻ tự tin và dũng cảm trong quan hệ bạn bè - 49 bí quyết giúp trẻ lắng nghe và truyền đạt - 43 bí quyết giúp trẻ kiểm soát tức giận - 49 cách thức cùng con chia sẻ', N'https://cdn1.fahasa.com/media/catalog/product/k/i/kinh-nghiem-tu-nuoc-nhat_-49-bi-quyet-giup-tre-lang-nghe-va-truyen-dat_tb-2023.jpg', 112, 2023, 50, 0, N'Kim Đồng', N'8935244894653', 18, 1, 53, 1, CAST(42000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (480, N'Bộ Học Montessori Để Dạy Trẻ Theo Phương Pháp Montessori - 100 Hoạt Động Montessori: Con Không Cần Ipad Để Lớn Khôn', N'Ève Herrmann, Trần Thị Huế', N'Đinh Tị', CAST(63000.00 AS Decimal(18, 2)), N'Học Montessori Để Dạy Trẻ Theo Phương Pháp Montessori - 100 Hoạt Động Montessori: Con Không Cần Ipad Để Lớn Khôn Dạy trẻ theo phương pháp Montessori không chỉ giúp phát huy tất cả năng lực nhận thức và cảm nhận giác quan theo đúng độ tuổi phát triển của trẻ mà còn thỏa mãn lòng ham muốn tìm tòi, khám phá thế giới của trẻ nhỏ. Các cuốn sách trong bộ Học Montessori để dạy trẻ theo phương pháp Montessori, bên cạnh việc giới thiệu những lý thuyết khoa học về dạy trẻ của Montessori còn đặc biệt chú trọng tới việc đưa ra các hoạt động thú vị và hữu ích cho trẻ. Lời hướng dẫn thực hiện hoạt động rất ngắn gọn, dễ hiểu và kết hợp với các hình ảnh sinh động, trực quan để cha mẹ có thể hướng dẫn trẻ thực hiện tại nhà. Cuốn 100 hoạt động Montessori: Con không cần iPad để lớn khôn gồm các hướng dẫn giúp trẻ làm quen với những hoạt động quen thuộc của cuộc sống thường nhật. Trẻ khoảng một tuổi rưỡi đã có khả năng thực hiện các hoạt động như tự rửa tay, mặc quần áo, dọn bàn ăn,.. nếu cha mẹ hướng dẫn trẻ đúng cách và tin tưởng vào khả năng tự lập của trẻ.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935212328395.jpg', 220, 2016, 50, 0, N'NXB Phụ Nữ', N'8935212328395', 18, 1, 53, 24, CAST(44100.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (481, N'Bộ Năng Lực Tư Duy IQ 3-6 Tuổi - 365 Ngày Cùng Con Phát Triển Trí Tuệ - Tập 2', N'Huyền Linh', N'Cty Văn Hóa & Truyền Thông Trí Việt.', CAST(26280.00 AS Decimal(18, 2)), N'Năng Lực Tư Duy IQ 3-6 Tuổi - 365 Ngày Cùng Con Phát Triển Trí Tuệ - Tập 2 Mỗi đứa trẻ là một thiên tài nên thầy cô, cha mẹ chính là những nhà giáo dục thiên tài. Đồng hành và góp sức cùng sứ mệnh cao quý ấy, bộ sách 365 ngày cùng con phát triển trí tuệ với nội dung hay, hình thức đẹp đã sẵn sàng mở ra cánh cửa dẫn vào kho báu tri thức nhân loại. Hãy để bộ sách thú vị này dẫn dắt bé khám phá thế giới, rèn luyện trí tuệ và phát triển trí thông minh một cách tự nhiên - hiệu quả nhất! 365 ngày cùng con phát triển trí tuệ thuộc tủ sách Năng lực tư duy IQ 3-6 tuổi sẽ là món quà ý nghĩa dành tặng cho bé yêu!', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935230009511.jpg', 34, 2025, 50, 0, N'Văn Học', N'8935230009511', 19, 1, 19, 22, CAST(18396.00 AS Decimal(18, 2)))
