INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (483, N'Bộ Năng Lực Tư Duy IQ 3-6 Tuổi - 365 Ngày Cùng Con Phát Triển Trí Tuệ - Tập 5', N'Huyền Linh', N'Cty Văn Hóa & Truyền Thông Trí Việt.', CAST(26280.00 AS Decimal(18, 2)), N'Năng Lực Tư Duy IQ 3-6 Tuổi - 365 Ngày Cùng Con Phát Triển Trí Tuệ - Tập 5 Mỗi đứa trẻ là một thiên tài nên thầy cô, cha mẹ chính là những nhà giáo dục thiên tài. Đồng hành và góp sức cùng sứ mệnh cao quý ấy, bộ sách 365 ngày cùng con phát triển trí tuệ với nội dung hay, hình thức đẹp đã sẵn sàng mở ra cánh cửa dẫn vào kho báu tri thức nhân loại. Hãy để bộ sách thú vị này dẫn dắt bé khám phá thế giới, rèn luyện trí tuệ và phát triển trí thông minh một cách tự nhiên - hiệu quả nhất! 365 ngày cùng con phát triển trí tuệ thuộc tủ sách Năng lực tư duy IQ 3-6 tuổi sẽ là món quà ý nghĩa dành tặng cho bé yêu!', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935230010005.jpg', 34, 2025, 50, 0, N'Văn Học', N'8935230009559', 19, 1, 54, 22, CAST(18396.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (484, N'Kể Chuyện Cuộc Đời Các Thiên Tài - Louis Pasteur - Thầy Thuốc Vĩ Đại Của Nhân Loại', N'Rasmus Hoài Nam', N'Tân Việt', CAST(32000.00 AS Decimal(18, 2)), N'Kể Chuyện Cuộc Đời Các Thiên Tài - Louis Pasteur - Thầy Thuốc Vĩ Đại Của Nhân Loại Chưa bao giờ chính thức theo học y khoa, nhưng Louis Pasteur vẫn được coi là một thầy thuốc vĩ đại bởi những đóng góp to lớn của ông cho y học. Có thể khẳng định rằng, hiếm có người cứu sống được nhiều sinh mạng hơn Louis Pasteur. Những vắc-xin ông phát triển cho đến nay vẫn tiếp tục cứu sống và bảo vệ hàng triệu người trên thế giới. Những nghiên cứu của ông về vi trùng đã cách mạnh hóa y tế. Louis Pasteur - Thầy thuốc vĩ đại của nhân loại là cuốn sách kể về câu chuyện cuộc đời của nhà khoa học Louis Pasteur. Cuốn sách mang đến cho bạn đọc thêm những góc nhìn rất mới về ông - một cậu bé sống tình cảm và ham học, một tuổi trẻ dám dấn thân hết mình cho đam mê, một nhà khoa học không ngừng cống hiến cho nhân loại đến tận những ngày cuối đời. Trên hành trình khoa học ấy của ông không chỉ có những vinh quang, mà có cả những cay đắng, khó khăn, những sự hi sinh lặng thầm để theo đuổi đam mê khoa học của cuộc đời mình. Hơn 70 năm cuộc đời là hơn 70 năm nhà khoa học Louis Pasteur sống vinh quang, không ngừng nỗ lực, toàn tâm toàn ý nghiên cứu cống hiến cho nhân loại. Ông là một nhà bác học vĩ đại, được nhân loại muôn đời tôn vinh và kính trọng. Ông được vinh danh là vị ân nhân của toàn nhân loại. Thông tin về Louis Pasteur Louis Pasteur (27/12/1822 - 28/9/1895) là nhà sinh học, nhà vi sinh vật học, nhà hóa học và là một giáo sư, bác sĩ nổi tiếng người Pháp. Ông đã khám phá vắc-xin phòng bệnh dại, vắc-xin bệnh than, vắc-xin bệnh tả.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935210307347.jpg', 104, 2023, 50, 0, N'Thanh Niên', N'8935210307347', 27, 1, 1, 38, CAST(22400.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (485, N'Kinh Nghiệm Từ Nước Nhật - Kĩ Năng Xã Hội Của Trẻ Em - 42 Bí Quyết Giúp Trẻ Tự Tin Và Dũng Cảm Trong Quan Hệ Bạn Bè', N'Aikawa Atsushi, Igari Emiko', N'Nhà Xuất Bản Kim Đồng', CAST(53000.00 AS Decimal(18, 2)), N'Nếu được dạy các kĩ năng xã hội, những đứa trẻ sẽ học được cách truyền đạt, cách lắng nghe và thấu hiểu ý nghĩ của người khác. Kết quả là, tình trạng trẻ bị tẩy chay, bị bắt nạt trong lớp sẽ giảm đi và giả sử trẻ bị bắt nạt thì sẽ biết tìm sự giúp đỡ từ các trẻ khác hoặc từ người lớn để nhanh chóng ra khỏi tình trạng bị cô lập. Khi có kĩ năng xã hội, các hành động hợp tác, trao đổi qua lại với bạn bè sẽ tăng lên và lớp học sẽ trở thành nơi “dễ chịu”, tác động tích cực đến thành tích học tập của trẻ. Các kĩ năng xã hội cho trẻ từ bậc tiểu học hay trung học cơ sở, sẽ là nền móng vững chắc trong các hoạt động giao tiếp xã hội theo trẻ đến tận lúc trưởng thành, giúp con người có được sự tự tin và độc lập, sức khoẻ tinh thần vững vàng. Cuốn sách này là những kĩ năng xã hội cần thiết và hết sức cụ thể dành cho trẻ em, giúp trẻ có được sự tự tin và độc lập trong quan hệ bạn bè và các mối quan hệ xã hội. -------------------------------------------------------- KĨ NĂNG XÃ HỘI LÀ KĨ THUẬT TRUYỀN ĐẠT QUA LẠI TỪNG “Ý NGHĨ” VÀ “TƯ DUY”. NẾU ĐƯỢC TRANG BỊ KĨ NĂNG XÃ HỘI TỐT THÌ CÁC EM SẼ CÓ SỰ TỰ TIN VÀ LÒNG DŨNG CẢM TRONG MỐI QUAN HỆ VỚI BẠN BÈ. • Bạn cất lời chào “Chào cậu…” khi gặp mặt bạn bè thì họ sẽ thấy họ được coi trọng và sẽ tỏ ra thân thiện. • Bạn nói “Tớ phản đối ý kiến này” thì bạn sẽ đưa ra được ý kiến đối lập mà không làm bạn bè bị tổn thương. • Khi nói “Tớ không muốn làm điều xấu” thì bạn có thể từ chối thẳng lời rủ rê xấu của bạn bè. • Khi hít thở sâu và đếm từ 1 đến 10, bạn sẽ làm dịu được cảm xúc tức giận. • Khi đi ra chỗ khác bạn sẽ tránh được cuộc cãi vã với bạn bè. • Khi xin lỗi đi xin lỗi lại bạn sẽ khôi phục được quan hệ bạn bè. -------------------------------------------------------- MỜI CÁC BẠN TÌM ĐỌC BỘ SÁCH KINH NGHIỆM TỪ NƯỚC NHẬT - KĨ NĂNG CHO TRẺ EM • 42 bí quyết giúp trẻ tự tin và dũng cảm trong quan hệ bạn bè • 49 bí quyết giúp trẻ lắng nghe và truyền đạt • 43 bí quyết giúp trẻ kiểm soát tức giận.', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_188266.jpg', 111, 2020, 50, 0, N'Kim Đồng', N'8935244812978', 19, 1, 54, 1, CAST(37100.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (486, N'Quẳng Cái Cân Đi Mà Khôn Lớn - Cẩm Nang Ăn Dặm Bé Tự Chỉ Huy Của Mẹ Việt', N'Mẹ Tee', N'Phụ Nữ', CAST(87360.00 AS Decimal(18, 2)), N'Chắc hẳn không ít những bà mẹ bỉm sữa cũng từng lo lắng khi em bé của bạn chuẩn bị bước vào giai đoạn ăn dặm với hàng tá những câu hỏi như: Khi nào thì bắt đầu? Bắt đầu như thế nào? Cháo hay bột? Nấu với gì? Tỷ lệ ra sao? Ăn bao nhiêu là đủ? Không chỉ dừng lại ở đó, chúng ta – những bà mẹ hiện đại còn hết sức ám ảnh với những bữa ăn dặm đầy nước mắt, đổ mồ hôi từ không ít những tấm gương xung quanh. Đó là những em bé rong ruổi trên xe đẩy với bát cháo bên cạnh, cứ mỗi lần bé ô a gì đó, người nhà lại tranh thủ đút tọt một miếng vô miệng. Đó là những em bé ngồi dán mắt vào chiếc ti vi đang phát những quảng cáo nhảy nhót hoặc điện thoại bật hoạt hình vui nhộn, mở miệng một cách vô thức để đón nhận đồ ăn. Là những em bé giãy giụa trên tay mẹ, phun phì phì thìa cháo, nước mắt rơi lã chã, miệng gào thét không ngớt chỉ với mong muốn duy nhất là bữa ăn chấm dứt. Đúng thật chẳng khác nào một cuộc chiến! Cho đến một ngày, tôi bắt gặp hình ảnh một em bé xinh tươi ngồi ngoan ngoãn trong chiếc ghế ăn dặm, say mê gặm những thanh cà rốt, nhai ngấu nghiến những mẩu bánh mì, mút chùn chụt miếng thịt luộc, rồi còn cả gặm ngô, ăn chuối lê táo… Điều làm tôi mê mẩn, xem đi xem lại những đoạn băng ghi lại bữa ăn của em chính là sự vụng về nhưng lại rất khéo léo của một cô bé mới có 6 tháng tuổi khi điều khiển những miếng thức ăn đưa lên miệng; rồi cả chiếc miệng xinh nhai móm mém mà mãi sau này tôi mới biết khi đó bé chưa hề có một chiếc răng nào; và ánh mắt mỗi khi bé ngẩng lên nhìn mẹ, trong đó ánh lên niềm vui thích, sự hào hứng với bữa ăn, thứ mà tôi gần như chưa từng thấy ở bất cứ em bé ăn dặm kiểu truyền thống nào. Ngay từ phút giây đó, tôi đã tự nhủ với thiên thần nhỏ trong bụng rằng đây sẽ là phương pháp tôi cho con ăn dặm. 6 tháng 10 ngày, lần đầu tiên tôi chính thức cho em bé ăn dặm theo phương pháp bé tự chỉ huy (Baby led weaning – BLW). Hồi hộp, lo lắng, tôi nín thở chờ đợi phản ứng của con. Thật tuyệt vời, Tee vô cùng hứng thú. Thậm chí, bé chỉ mất 2 tuần để bắt nhịp thay vì 1 tháng như trong các tài liệu hướng dẫn. 8 tháng, tôi bắt đầu cho con ăn cơm. 9 tháng, tôi lần đầu giới thiệu dĩa cho bé. 10 tháng, con đã có thể sử dụng dĩa để ăn các miếng hoa quả cắt nhỏ mà không cần bốc tay. 11 tháng, tôi dạy con làm quen với thìa. 14 tháng, Tee xúc thìa thành thạo. Lúc này, con đã có thể tự xúc hết một bát rưỡi cơm trộn thịt mỗi bữa. Thịt, cá, rau, canh đều ăn đầy đủ, không hề kén chọn. Tráng miệng thêm một bát hoa quả cắt nhỏ. 18 tháng, ngày đầu tiên đi học, cô giáo khen con tự giác xúc ăn như một đứa trẻ 3 tuổi. 19 tháng, con tự học cách sử dụng đũa bằng việc quan sát mọi người xung quanh. Và con đã hoàn thành “khóa huấn luyện” BLW trong thời gian này (sớm hơn dự kiến 5 tháng) với việc có thể tay thìa, tay đũa, ăn hết bát bún/phở y hệt người lớn. Không xay nhuyễn đồ ăn, không ăn rong, không ti vi, không điện thoại, không nài ép, không tiếng gào khóc… Những em bé ăn dặm BLW vẫn luôn có một niềm háo hức vô bờ bến với đồ ăn và cảm giác thích thú khi tới mỗi bữa ăn. Đó chính là những gì BLW đã đem lại cho mẹ con tôi. Dĩ nhiên, bên cạnh những thành công mà hai mẹ con tôi đạt được, cũng không thể quên kể đến cả những “cuộc cân não” đầy gam
GO

, khốc liệt. Những giai đoạn bé biếng ăn nhưng không được nài ép, áp lực từ phía người thân trong gia đình khi thấy con ăn ít, mệt mỏi với bãi chiến trường sau mỗi bữa ăn, những nguyên tắc cần tuân thủ nghiêm ngặt, tước quyền được ăn của con… Tôi tin chắc rằng không một bà mẹ nào thành công với BLW mà chưa từng trải qua một trong những khủng hoảng đó. Nhưng cũng như việc “muốn nhìn thấy cầu vồng, bạn phải biết chịu đựng cơn mưa”, chỉ cần bạn kiên định, vững tâm và vượt qua được, thành công với bạn đang ở rất gần phía trước. Và khoảnh khắc bạn nhìn thấy con ăn ngoan, tự xúc ăn hết bát cơm, biết dừng lại khi no và tự giác rời khỏi ghế… những điều mà với một em bé 3 tuổi ăn dặm kiểu truyền thống còn khó để làm, bạn sẽ hiểu cảm giác hạnh phúc mà tôi đã từng trải qua. Mà tôi cảm thấy như hai từ hạnh phúc còn không', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_47018.jpg', 180, 2019, 50, 0, N'NXB Phụ Nữ', N'9786045661208', 20, 1, 18, 36, CAST(61152.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (487, N'Giúp Con Đạt Được Chiều Cao Lý Tưởng - Tăng Thêm 10 cm Không Khó', N'Fir Forest', N'CÔNG TY CỔ PHẦN SÁCH OMEGA VIỆT NAM', CAST(87200.00 AS Decimal(18, 2)), N'Giúp Con Đạt Được Chiều Cao Lý Tưởng - Tăng Thêm 10 cm Không Khó Trong xã hội hiện đại, chiều cao không chỉ ảnh hưởng tới ngoại hình mà còn ảnh hưởng đến lòng tự tôn và địa vị xã hội của một người. Về cơ bản, chúng ta đều biết rằng chiều cao được quyết định bởi di truyền, và những bậc cha mẹ có tầm vóc thấp thường lo lắng rằng vóc dáng con mình sẽ thấp bé. Tuy nhiên nếu cha mẹ và trẻ cùng nỗ lực trong thời kỳ tăng trưởng, trẻ có thể cao thêm 10 cm hoặc hơn thế nữa so với chiều cao dự kiến. Cuốn sách này được chia thành 4 phần. Trong đó, phần 1 và 2 phân tích các yếu tố ảnh hưởng đến sự phát triển chiều cao. Phần 3 cung cấp hướng dẫn về các bài tập giúp kích thích đĩa tăng trưởng. Phần 4 chỉ ra các yếu tố gây cản trở sự tăng trưởng chiều cao của trẻ và những lời khuyên để thanh lọc những yếu tố này. Hi vọng với những thông tin có trong sách này, cha mẹ và con cái có thể cùng nhau nỗ lực để trẻ cao lớn hơn, hạnh phúc hơn. Một số trích đoạn: Nghĩa là, điều quan trọng là phải tuân thủ tuyệt đối các nguyên tắc cơ bản về dinh dưỡng, giấc ngủ và vận động trong sinh hoạt hằng ngày. Ba thói quen sinh hoạt này cũng đóng vai trò quan trọng trong việc phát triển trí tuệ, hình thành tính cách và nhân phẩm của trẻ; nếu tuân thủ và thực hiện đều đặn thì sẽ có ý nghĩa giáo dục rất lớn. Điều quan trọng là sự tăng trưởng chiều cao diễn ra nhanh chóng vào thời điểm nhất định. Thời điểm này được gọi là giai đoạn tăng trưởng mạnh. Giai đoạn tăng trưởng mạnh chỉ xảy ra hai lần trong đời, mặc dù mỗi người có sự khác biệt, nhưng giai đoạn tăng trưởng mạnh đầu tiên thường xảy ra trước ba tuổi và giai đoạn tăng trưởng mạnh thứ hai diễn ra ở tuổi dậy thì. Vào thời điểm này, cha mẹ nên quan tâm đến sự phát triển chiều cao của con mình nhiều hơn thường lệ.', N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia_chieu-cao.jpg', 136, 2023, 50, 0, N'Thế Giới', N'8936158591812', 20, 1, 18, 11, CAST(61040.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (488, N'Kỷ Luật Bàn Ăn - Dinh Dưỡng Cân Bằng: Để Ăn Rong Chỉ Còn Là Dĩ Vãng (Tái Bản 2024)', N'Hachun Lyonnet (Hà Chũn), BS Nguyễn Hồng Thu', N'Thái Hà', CAST(240000.00 AS Decimal(18, 2)), N'Kỷ Luật Bàn Ăn - Dinh Dưỡng Cân Bằng: Để Ăn Rong Chỉ Còn Là Dĩ Vãng Chào mừng mẹ đến với hành trình mới đầy thú vị nhưng cũng không kém phần căng thẳng. Đã qua rồi cái thời kì nhàn hạ, cả ngày quanh đi quẩn lại với vài bình sữa, mỗi lần đến bữa mẹ chỉ thủng thỉnh vén áo cho ti hay cùng lắm là chuẩn bị một bình – một núm là xong một bữa ăn. 6 tháng đến như một cơn gió, cùng với bao hứng khởi của việc bắt đầu ăn dặm, đa dạng hóa thức ăn. Vài ngày đầu trôi đi thật êm đềm, thế nhưng rồi kì vọng của mẹ về em bé ngồi ăn ngoan từ đầu đến cuối bữa bị đập tan tành bởi cái hiện thực con biếng ăn, con gào khóc – đập phá, chạy khắp nhà, không chịu ăn, thậm chí kèm nôn ọe … Bây giờ phải làm sao? Mẹ sẽ có hai sự lựa chọn. Một là, “ ăn rong và ép ăn ” với những hệ quả như: làm tiêu hóa kém hiệu quả; làm trẻ sợ hãi, cáu kỉnh, có thể gây ức chế thần kinh và ở nhiều trẻ những điều này gây ức chế tiêu hóa, nôn theo chủ ý, ăn uống lệch dinh dưỡng; làm mất thời gian và công sức của chamẹ và gia đình; làm hỏng răng trong lâu dài. Do sợ nôn nên mẹ không đánh răng cho bé sau ăn, những hàm răng sữa cứ thế tạo tầng lớp mảng bám dày, mủn răng, sún răng.; mất cơ hội học tập và phát triển: Ép ăn lấy đi ở trẻ cơ hội được khám phá ẩm thực, học tập kĩ năng cử động tinh… Hai là, “ ăn chủ động và kỷ luật bàn ăn ” với những ảnh hưởng tích cực như: rèn kỹ năng phối hợp của tay – mắt – miệng; tăng sự tự tin, khi con xoay xở qua khó khăn, và đạt được điều mình muốn: cho được thức ăn vào miệng, cầm được chiếc thìa, ăn được bằng nĩa, thìa, hay đũa; tính tự lập tự chủ được nuôi dưỡng: con ăn cho chính bản thân mình, và con làm được; hệ tiêu hóa có cơ hội được hoàn thiện, quá trình tiêu hóa là toàn diện. Phản ứng sinh hóa trong tiêu hóa là tự nhiên và hiệu quả; và cuối cùng là con ăn đủ chất, cân bằng và dinh dưỡng tốt nhất để phát triển tối đa theo khả năng tiềm tàng của chính mình. Đến đây chắc hẳn cha mẹ đã biết mình nên chọn theo hướng nào rồi, nhưng đâu sẽ là chỉ dẫn khi đứa trẻ: không chịu ngồi vào bàn; ngậm thức ăn trong miệng; ăn rất ít; ăn lệch; hoặc uống rất ít nước… Thì tất cả những vấn đề đó đã được tác giả Hachun Lyonnet (Hà Chũn) hệ thống lại và chia sẻ trong cuốn sách Kỷ luật bàn ăn - Dinh dưỡng cân bằng với hình thức vô cùng tươi mới và khoa học. Cuốn sách được xuất bản với hy vọng mỗi đứa trẻ đều được Ăn cân bằng – Tại bàn – Cùng gia đình và trong niềm vui. “ Nhờ việc áp dụng kỷ luật bàn ăn mà rất nhiều em bé đã ngồi ngoan trên ghế để ăn dặm, thay vì vừa chạy chơi vừa ăn, ảnh hưởng đến hệ tiêu hóa và khiến người lớn “phát điên”. Nhờ áp dụng kỷ luật bàn ăn, nhiều em bé cảm nhận được sự đáng quý của thức ăn, biết trân trọng đồ ăn và ăn uống tự giác, ăn theo nhu cầu. Nhờ kỷ luật bàn ăn, các bé học được cách ăn uống cân bằng và lành mạnh, thay vì ăn lệch và chỉ ăn những món mà mình thích. Do đó, cuốn sách này sẽ giúp các bậc cha mẹ dù theo phương pháp ăn dặm nào cũng có thể áp dụng kỷ luật bàn ăn hiệu quả, đúng đắn và phù hợp, để mọi em bé đều tìm được niềm vui trong ăn uống.” – trích lời giới thiệu của Mẹ Ong Bông , đồng tác giả bộ sách bán chạy Nuôi con không phải là cuộc chiến – Ăn dặm không phải là cuộc chiến . “Liệu có một thứ gọi là “bí-kíp toàn-thư tuyệt-phẩm” về dinh dưỡng và ăn uống cho trẻ nhỏ giữa “ma trận” thông tin trong thời điểm hiện tại không? Hỡi những bà mẹ trẻ đang cảm thấy hoang mang và bối rối với việc tìm hiểu về dinh dưỡng cho con, cùng nỗi ám ảnh “ăn rong”, “ép ăn” trong thời kì con ăn dặm! Xin thưa với bạn là không có đâu! Đừng đi tìm cái bí kíp hoàn hảo ấy. Nhưng may thay, bạn lại đang cầm trên tay cuốn sách này.” – trích lời giới thiệu của Phan Anh (Esheep) Mục lục: Ăn dặm: Bắt đầu một hành trình đầy hứng khởi Kỉ luật bàn ăn: Chìa khó đến dinh dưỡng tích cực Dinh dưỡng cân bằng: Để con là lực sĩ tí hon của mẹ Giúp tôi với, con không chịu ăn… Để bàn ăn không phải nơi tranh giành quyền lực giữ con và người lớn Một số điều mẹ cần biết Chuyện người trong cuộc: Các mẹ đã áp dụng thành công Kỉ luật bàn ăn như thế nào?', N'https://cdn1.fahasa.com/media/catalog/product/b/i/bia-1---ky-luat-ban-an-dinh-duong-can-bang_2.jpg', 300, 2024, 50, 0, N'Lao Động', N'8935280915442', 20, 1, 55, 39, CAST(168000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (489, N'Chăm Sóc Con Giải Đáp Những Vấn Đề Thường Gặp', N'Carol Cooper', N'FIRST NEWS', CAST(108040.00 AS Decimal(18, 2)), N'Chăm sóc con - Giải đáp những vấn đề thường gặp được chia thành 9 chương, bao gồm: Chuẩn bị cho sự chào đời của bé, Cho bé bú (ăn) và những vấn đề về dinh dưỡng, Dỗ bé ngủ, Chăm sóc bé hằng ngày, Bé quấy khóc và cách dỗ bé, Quá trình tăng trưởng và phát triển của bé, Tìm hiểu về cách ứng xử, hành vi của bé và cách dạy dỗ, Cuộc sống gia đình, Vấn đề sức khỏe của bé. Ngoài ra, quyển sách còn đề cập đến những vấn đề khác ít gặp trong các quyển sách khác cũng viết về cách chăm sóc bé nói chung, ví dụ như các tình huống: cha chăm sóc bé ra sao lúc rảnh rỗi, cha mẹ đơn thân cần nuôi dạy bé ra sao, ứng xử như thế nào khi xảy ra mất mát, và làm thế nào để hài hòa giữa việc đi làm và việc nuôi dạy bé...', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935086823163.jpg', 212, 2012, 50, 0, N'NXB Phụ Nữ', N'8935086823163', 20, 1, 55, 25, CAST(75628.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (490, N'Bộ Who? Chuyện Kể Về Danh Nhân Thế Giới - Elon Musk', N'Toon-Jangee, Oh Gi-Su', N'Nhà Xuất Bản Kim Đồng', CAST(51000.00 AS Decimal(18, 2)), N'Who? Chuyện Kể Về Danh Nhân Thế Giới - Elon Musk Thời niên thiếu, Elon Musk từng đọc sách 10 tiếng mỗi ngày và tự đặt câu hỏi rằng đâu là vấn đề quan trọng nhất đối với loài người. “SpaceX” thành công trong việc tái sử dụng tên lửa. “Tesla Motors” phân phối ô tô điện khắp thế giới. “Solar City” cung cấp năng lượng sạch, bảo vệ môi trường Trái Đất. Đó là những thành tựu đạt được nhưng Elon Musk vẫn chưa dừng lại mà sẽ tiếp tục dấn thân vào thử thách vì tương lai của nhân loại. Một kĩ sư thiên tài đã biến điều không tưởng thành hiện thực! Liệu ước mơ đưa con người lên Sao Hoả của ông sẽ trở thành hiện thực? --- "Who? - Chuyện kể về danh nhân thế giới" là bộ truyện thú vị kể về cuộc đời của các danh nhân nổi tiếng nhất thế giới, từ thời niên thiếu cho đến khi họ đạt được những thành công rực rỡ trong sự nghiệp. Những câu chuyện về cuộc đời và sự nghiệp vĩ đại của các danh nhân sẽ đem đến cho các em những ước mơ và hoài bão cao đẹp! Bộ tranh truyện WHO? Chuyện kể về danh nhân thế giới - người bạn thân thiết của thiếu nhi.', N'https://cdn1.fahasa.com/media/catalog/product/d/a/danh-nhan-who_elon-musk_bia.jpg', 176, 2024, 50, 0, N'Kim Đồng', N'8935352605554', 23, 1, 57, 1, CAST(35700.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (491, N'Bộ Lịch Sử Nước Ta - Cùng Bé Tô Màu', N'Hồ Chí Minh', N'NXB Chính Trị Quốc Gia', CAST(22000.00 AS Decimal(18, 2)), N'Lịch Sử Nước Ta - Cùng Bé Tô Màu Với 208 câu thơ lục bát của Chủ tịch Hồ Chí Minh, “Lịch sử nước ta” đã tái hiện hành trình hàng nghìn năm dựng nước và giữ nước của dân tộc thật gần gũi, giàu cảm xúc. Trong lần xuất bản mới nhất, chúng tôi làm mới tác phẩm với hệ thống tranh minh họa sinh động cùng nhiều trang tô màu, giúp bạn đọc nhỏ tuổi vừa đọc, vừa khám phá lịch sử bằng trí tưởng tượng.', N'https://cdn1.fahasa.com/media/catalog/product/z/7/z7870367406508_917b2815988d9212f0d1899ca424885b.jpg', 96, 2026, 50, 0, N'Chính Trị Quốc Gia Sự Thật', N'8935279194025', 23, 1, 57, 32, CAST(15400.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (492, N'Bộ Những Câu Chuyện Truyền Cảm Hứng - I Will Be Better - Dũng Cảm Thử Lại Lần Nữa', N'Yunan', N'Nhà Xuất Bản Kim Đồng', CAST(50000.00 AS Decimal(18, 2)), N'Cuốn sách kể những câu chuyện giúp ta xây dựng lòng kiên trì. Mỗi nhân vật trong cuốn sách này đều kể những câu chuyện rất riêng về quá trình học tập của mình. Trên con đường trưởng thành, nếu biết tự nhận thức bản thân, hiểu rõ mục tiêu phát triển của mình, bồi đắp lòng tự tin, dám đối mặt với thử thách và kiên trì phát huy năng lực bản thân, chúng ta đều có thể thực hiện được ước mơ và trở nên tốt đẹp hơn, thành công hơn. Bộ sách Những câu chuyện truyền cảm hứng được chia thành các chủ đề thiết thực, giúp bạn đọc nhỏ tuổi tìm hiểu và rèn những thói quen, đức tính tốt. Mỗi cuốn gồm nhiều câu chuyện nhỏ, trong đó có cả những hồi ức đáng nhớ của các nhân vật nổi tiếng trên thế giới... Mong rằng bộ sách sẽ trở thành bạn đồng hành tích cực, cùng các em bước vào tương lai rực rỡ. Cùng tìm đọc: Những Câu Chuyện Truyền Cảm Hứng - I Will Be Better: Nguồn Năng Lượng Tích Cực Những Câu Chuyện Truyền Cảm Hứng - I Will Be Better: Dũng Cảm Thử Lại Lần Nữa Những Câu Chuyện Truyền Cảm Hứng - I Will Be Better: Khoản Tiết Kiệm Của Mẹ Những Câu Chuyện Truyền Cảm Hứng - I Will Be Better: Con Sẽ Không Dựa Dẫm Những Câu Chuyện Truyền Cảm Hứng - I Will Be Better: Con Cảm Ơn Mẹ', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_244718_1_3599.jpg', 229, 2021, 50, 0, N'NXB Kim Đồng', N'8935244861570', 24, 1, 28, 1, CAST(35000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (493, N'Đắc Nhân Tâm Cho Trẻ Em - Phiên Bản Truyện Tranh Thú Vị', N'Lý Hàm', N'CÔNG TY TNHH TIÊN PHONG BOOKS', CAST(87000.00 AS Decimal(18, 2)), N'Đắc Nhân Tâm Cho Trẻ Em Bạn có lo lắng về việc bị "xa lánh" không? Bạn có cảm thấy bối rối vì "lỡ lời làm phật lòng người khác" không? Bạn có biết cách giải quyết những mâu thuẫn và tranh cãi với bạn bè không? Khi đối mặt với những yêu cầu vô lý, làm thế nào để từ chối? Trước sự lựa chọn giữa lợi ích và tình bạn, bạn sẽ quyết định ra sao? Khi bất đồng ý kiến với người khác, làm thế nào để giao tiếp hiệu quả? Hãy lật mở cuốn sách Đắc nhân tâm cho trẻ em này, học hỏi những kỹ năng ứng xử và giao tiếp, dễ dàng nâng cao khả năng xã hội của bạn.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935380700481.jpg', 160, 2025, 50, 0, N'Tri Thức', N'8935380700481', 24, 1, 28, 16, CAST(60900.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (494, N'Bộ EQ - IQ Giúp Trẻ Làm Chủ Cảm Xúc - Lo Lắng', N'Audrey Bouquet, Fabien Öckto Lambert', N'Đinh Tị', CAST(26000.00 AS Decimal(18, 2)), N'Đối với nhiều bậc phụ huynh, hướng dẫn trẻ từ 3-9 tuổi biểu lộ cảm xúc một cách lành mạnh, đúng mực, không cư xử ích kỷ, hờn dỗi, quậy phá là một thử thách thật sự. Liệu có cách nào hiệu quả để giúp các em hiểu rõ những cảm xúc hết sức tự nhiên đang xuất hiện trong lòng, từng bước điều hòa và bày tỏ chúng theo cách có lợi nhất cho sức khỏe tinh thần của mình? Để trả lời câu hỏi đó, Đinh Tị Books xin giới thiệu với bạn đọc bộ sách EQ-IQ giúp trẻ làm chủ cảm xúc được tác giả người Pháp Audrey Bouquet viết theo phương pháp tâm thể (sophrology) rất phổ biến ở châu Âu. Bộ sách gồm 8 cuốn với minh họa dễ thương sẽ kể cho các em nghe câu chuyện của bạn Mèo con ngộ nghĩnh, lồng ghép vào đó những bài học, lời khuyên và giải pháp để các em biết cách đối diện với nỗi sợ, nỗi lo lắng, cơn giận, niềm vui cũng như nhiều cảm xúc khác nữa. Về hai tác giả của bộ sách - Tác giả Audrey Bouquet vốn là một nhà khoa học. Bà học chuyên ngành sinh học và dinh dưỡng học, sau đó được đào tạo về phương pháp tâm thể. Cơ duyên thú vị khiến bà đến với sách thiếu nhi bắt nguồn từ chính những đứa con của bà. Từ đây, bà bắt đầu kết hợp kiến thức khoa học vào những câu chuyện thú vị và ngộ nghĩnh, giúp trẻ ứng xử phù hợp với cảm xúc của mình và với thế giới xung quanh. Qua từng trang sách, ta có thể thấy sự yêu thương, tận tâm và mong ước đồng hành cùng các bạn nhỏ trên con đường trưởng thành của Audrey Bouquet. - Fabien Öckto Lambert là họa sĩ minh họa, từng học truyền thông thị giác tại trường Brassart de Tours. Ông có nhiều tác phẩm tham dự những cuộc triển lãm và có khoảng 10 năm kinh nghiệm trong lĩnh vực đồ họa và mỹ thuật. Hiện ông đang hợp tác với nhiều tác giả để vẽ minh họa cho những dự án sách thiếu nhi. Ông chia sẻ: “Tranh vẽ của tôi được dành cho thiếu nhi nhưng tôi hy vọng nó cũng thắp nên niềm vui trong trái tim người lớn”. Thật vậy, trong bộ sách EQ-IQ giúp trẻ làm chủ cảm xúc, những minh họa của Lambert rất ấn tượng, tập trung vào biểu cảm chân thực của những chú mèo, đem tới muôn vàn hứng thú cho độc giả nhí.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935212357531.jpg', 28, 2022, 50, 0, N'Thanh Niên', N'8935212357531', 24, 1, 58, 24, CAST(18200.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (495, N'Con Gái À! - Tự Bảo Vệ Mình Là Quan Trọng Nhất', N'Lý Bình', N'CÔNG TY TNHH TIÊN PHONG BOOKS', CAST(84000.00 AS Decimal(18, 2)), N'Con Gái À! - Tự Bảo Vệ Mình Là Quan Trọng Nhất Cuốn sách cung cấp các kiến thức về an toàn và phòng tránh nguy hiểm cho bé gái, từ những tình huống trong gia đình, trường học, ngoài xã hội, môi trường mạng, các tình huống bất ngờ trong cuộc sống. Thông qua những ví dụ cụ thể và minh họa trực quan, cuốn sách giúp các bé gái hiểu được cách bảo vệ chính mình và giảm thiểu nguy cơ bị tổn thương.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935380700511.jpg', 112, 2025, 50, 0, N'Lao Động', N'8935380700511', 24, 1, 58, 16, CAST(58800.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (496, N'Bộ Rèn Luyện IQ-EQ-CQ Cho Bé - Mẹ Hỏi Bé Trả Lời - Bé Thông Minh Học Cùng Mẹ - Dành Cho Bé 2-3 Tuổi - Bìa Cứng', N'Linh Lan', N'Cty Văn Hóa & Truyền Thông Trí Việt.', CAST(26000.00 AS Decimal(18, 2)), N'Rèn Luyện IQ-EQ-CQ Cho Bé - Mẹ Hỏi Bé Trả Lời - Bé Thông Minh Học Cùng Mẹ - Dành Cho Bé 2-3 Tuổi Bộ sách nhỏ xinh “Mẹ hỏi bé trả lời” là tập hợp những trò chơi phong phú, câu đố thông minh giúp bé và cha mẹ có thể “học mà chơi, chơi mà học” qua các chủ đề: cách ứng xử, câu hỏi về tự nhiên, không gian, phân biệt hình khối, ngôn ngữ, toán học... Sách phân chia theo từng lứa tuổi với nội dung phong phú, những câu hỏi đáp hàm súc trí tuệ, hình ảnh dễ thương cùng nhiều phương pháp rèn luyện có thể khơi dậy trí thông minh và khả năng tiềm ẩn của bé. Bộ sách “Mẹ Hỏi Bé Trả Lời” gồm: - Mẹ Hỏi Bé Trả Lời 1-2 Tuổi - Mẹ Hỏi Bé Trả Lời 2-3 Tuổi - Mẹ Hỏi Bé Trả Lời 3-4 Tuổi - Mẹ Hỏi Bé Trả Lời 4-5 Tuổi - Mẹ Hỏi Bé Trả Lời 5-6 Tuổi', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786326062151.jpg', 80, 2025, 50, 0, N'Văn Học', N'9786326062151', 25, 1, 39, 22, CAST(18200.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (497, N'Bộ Họa Sĩ Tài Ba - 6 Bước Vẽ Trái Cây', N'HHJelly', N'AZ Việt Nam', CAST(23000.00 AS Decimal(18, 2)), N'Họa Sĩ Tài Ba - 6 Bước Vẽ Trái Cây Chỉ với 6 bước đơn giản, bé có thể vẽ cả thế giới! Từ những bạn động vật dễ thương, các món ăn hấp dẫn cho đến vô vàn vật dụng, phương tiện,... quen thuộc xung quanh, bé đều có thể tự mình vẽ thật dễ dàng khi bám sát từng bước hướng dẫn đơn giản, trực quan trong sách. Đây sẽ là cuốn sách lý tưởng để bé tự tin làm quen với kĩ năng vẽ, bước đầu khơi mở trí tưởng tượng và khả năng sáng tạo cho bé. Bộ sách được thiết kế với các nét vẽ và thao tác phù hợp với khả năng vận động tinh của trẻ nhỏ. Thông qua việc quan sát, làm theo từng bước và luyện tập các nét cơ bản, bé không chỉ học cách vẽ mà còn rèn luyện khả năng phối hợp tay - mắt, kiểm soát bút và tăng sự tập trung. Đây sẽ là cuốn sách lý tưởng để bé tự tin làm quen với hội họa, đồng thời khơi mở trí tưởng tượng, khả năng sáng tạo và niềm yêu thích khám phá thế giới xung quanh. Không chỉ có phần hướng dẫn vẽ chi tiết, bộ sách còn mang đến những hoạt động bổ ích khác như: - Từ vựng song ngữ Việt - Anh giúp bé mở rộng vốn từ và ghi nhớ từ mới một cách tự nhiên - Các trò chơi thú vị cuối sách giúp bé rèn luyện khả năng quan sát, ghi nhớ và suy luận trong lúc vui chơi Cùng bé vẽ cả cả thế giới với trọn bộ 6 cuốn Họa sĩ tài ba: - 6 bước vẽ trái cây - 6 bước vẽ động vật - 6 bước vẽ đồ ăn - 6 bước vẽ đồ vật - 6 bước vẽ phương tiện - 6 bước vẽ thiên nhiên', N'https://cdn1.fahasa.com/media/catalog/product/3/8/386.jpg', 32, 2026, 50, 0, N'Phụ Nữ Việt Nam', N'8935325036934', 25, 1, 39, 8, CAST(16100.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (498, N'Sách Dán Hình Tương Tác - Những Cầu Thủ Bóng Đá Nổi Tiếng Thế Giới - Những Sự Thật Thú Vị Về Các Cầu Thủ Bóng Đá Nổi Tiếng Nhất Thế Giới', N'Nhiều Tác Giả', N'Tân Việt', CAST(68000.00 AS Decimal(18, 2)), N'Sách Dán Hình Tương Tác - Những Cầu Thủ Bóng Đá Nổi Tiếng Thế Giới - Những Sự Thật Thú Vị Về Các Cầu Thủ Bóng Đá Nổi Tiếng Nhất Thế Giới Một kì World Cup mới sắp đến – World Cup 2026 diễn ra tại Mỹ, Canada và Mexico. Liệu những cầu thủ tài năng nổi tiếng như Lionel Messi, Cristiano Ronaldo, Luka Modrić, Neymar, Virgil van Dijk… có tạo nên kì tích gì trong mùa giải năm nay? Nhà vô địch năm 2026 sẽ gọi tên đội tuyển quốc gia nào? Hòa chung niềm vui, sự háo hức và đầy mong chờ đó, Tân Việt Books xin trân trọng giới thiệu 2 cuốn sách mới về chủ đề bóng đá trong bộ Sách dán hình tương tác sắp ra mắt trong tháng 5 tới đây. Bộ sách cung cấp cho độc giả vô vàn thông tin chính xác, những hình ảnh minh họa tuyệt đẹp về 80 đội tuyển bóng đá nam hàng đầu thế giới theo bảng xếp hạng của FIFA và 80 cầu thủ bóng đá tài năng nhất hành tinh. Đội ngũ độc giả và biên tập đã tìm kiếm, cập nhật và đưa đến bạn những con số chuẩn xác nhất về thành tích thi đấu của mỗi đội, những bí mật hay ho về mỗi cầu thủ, hay trận đấu diễn ra vào thời gian và địa điểm cụ thể nào. Đặc biệt bộ sách được in bìa với hiệu ứng ánh kim rực rỡ, thể hiện hình ảnh các siêu sao bóng đá, các áo đấu đội tuyển trong thiết kế lấp lánh sang trọng, xứng đáng là món quà sưu tầm của độc giả nhí yêu bóng đá. Chi tiết nội dung mỗi cuốn sách bao gồm: 1. CÁC ĐỘI TUYỂN BÓNG ĐÁ TRÊN THẾ GIỚI – Những điều thú vị về các đội tuyển bóng đá trên thế giới Một cuốn sách giúp bạn khám phá những thông tin thú vị về 80 đội tuyển quốc gia hàng đầu theo bảng xếp hạng bóng đá nam FIFA. Trong cuốn sách này, bạn sẽ được tìm hiểu logo của các kì World Cup – từ kì đầu tiên diễn ra tại Uruguay vào năm 1930 cho đến logo World Cup tổ chức tại Qatar vào năm 2022, hay khám phá sự phát triển của các loại bóng đấu xuyên suốt lịch sử, và các thông tin được cập nhật chuẩn xác khác, như: cầu thủ ghi bàn nhiều nhất, chiến thắng đậm nhất và các đội tuyển vinh dự giành được một hoặc nhiều chức vô địch World Cup. 2. NHỮNG CẦU THỦ BÓNG ĐÁ NỔI TIẾNG THẾ GIỚI – Những sự thật thú vị về các cầu thủ bóng đá nổi tiếng nhất thế giới Cuốn sách sẽ tiết lộ cho các độc giả những sự thật và bí mật thú vị về 80 cầu thủ bóng đá nổi tiếng nhất thế giới: từ những huyền thoại mà ông bà, bố mẹ bạn từng cổ vũ như Pele, Franz Beckenbauer, David Beckham, Roberto Baggio cho đến những ngôi sao bạn đang thấy thi đấu trên màn hình tivi như Cristiano Ronaldo, Lionel Messi, Kylian Mbappé, hay Erling Haaland… Ngoài ra, tên tuổi, biệt danh, đặc điểm nổi bật, kĩ năng đặc trưng và những thành tích huyền thoại của họ cũng sẽ khiến các bạn đọc không thể rời mắt khỏi những trang sách. Điểm nổi bật của mỗi cuốn sách là tặng kèm 4 trang sticker theo chủ đề tương ứng, sau đó độc giả có thể thỏa sức giải trí với hoạt động tương tác cùng hình dán trong các cuốn sách này. Bạn có thể dán hình vào chỗ trống cho chính xác, hay dán những miếng sticker nên dụng cụ học tập hoặc bất cứ đâu bạn muốn. Với những hình minh họa tuyệt đẹp sẽ giúp bạn nhận biết và nhận diện từng cầu thủ bóng đá, từng áo đấu hay quốc kì của mỗi đội tuyển. Và hi vọng thông qua hai cuốn sách về chủ đề bóng đá hấp dẫn này, các độc giả sẽ hiểu biết thêm về môn thể thao vua được quan tâm số 1 thế giới, cũng như trải qua một kì World Cup 2026 thật vui vẻ, đáng nhớ.', N'https://cdn1.fahasa.com/media/catalog/product/b/_/b_a-_-nhung-cau-thu-bong-da-noi-tieng-tg.jpg', 36, 2026, 50, 0, N'Mỹ Thuật', N'8935210315045', 25, 1, 59, 38, CAST(47600.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (499, N'Bộ Trò Chơi Dán Hình IQ-EQ-CQ - Sticker - Siêu Xe - Tập 2', N'Louis Ben', N'Cty Văn Hóa Việt Thư', CAST(22050.00 AS Decimal(18, 2)), N'Trò Chơi Dán Hình IQ-EQ-CQ - Sticker - Siêu Xe - Tập 2 3-6 tuổi là giai đoạn bộ não của trẻ phát triển nhanh nhất để có thể nhận thức được màu sắc, hình khối, đồ vật, phát triển mạnh mẽ về cả ngôn ngữ, tư duy logic và khả năng sáng tạ Cũng bởi thế mà trẻ cần để có thể nâng cao được toàn diện những kỹ năng của mình. Bóc dán thông minh luôn là đề tài khiến các bé tò mò và thích khám phá nhất trong các loại sách. Bộ Bóc dán thông minh dành cho trẻ từ 3-6 tuổi, giúp trẻ kết hợp khéo léo giữa bàn tay và trí não. Với 4 chủ đề về các loại xe: Xe Công Trình, Xe Thể Thao, Xe Thông Dụng, Siêu Xe sẽ nâng cao trí tuệ toàn diện cho trẻ như: khả năng quan sát, trí nhớ, trí tưởng tượng và khả năng sáng tạo. Phát triển đồng bộ IQ, EQ và CQ. Cùng với việc kích thích não bộ, vận dụng đôi tay linh hoạt cho trẻ, giúp trẻ nhanh nhẹn và bồi dưỡng kỹ năng toán học cho các em theo một trình tự khoa học, hợp lí và có hệ thống. Tập sách bao gồm những hình vẽ đa dạng, bao quát nhiều phương diện, mới mẻ, sinh động, thú vị nhằm thu hút trẻ đọc sách và mang lại cho bé yêu cảm nhận trực quan nhất, hình ảnh bóc dán trong sáng, tranh có nhiều màu sắc giúp trẻ lĩnh hội được tốt hơn, từ đó trẻ học được cách chủ động suy nghĩ và tiến hành chơi mà học vui vẻ.', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786044903019.jpg', 12, 2024, 50, 0, N'Phụ Nữ Việt Nam', N'9786044903019', 25, 1, 59, 23, CAST(15435.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (500, N'Kể Chuyện Cuộc Đời Các Thiên Tài: Albert Einstein - Tuổi Thơ Gian Khó Và Cuộc Đời Khoa Học Vĩ Đại', N'Rasmus Hoài Nam', N'Tân Việt', CAST(44000.00 AS Decimal(18, 2)), N'Cuốn sách gồm những âu chuyện viết về cuộc đời của nhà khoa học thiên tài Albert Einstein, người đã làm thay đổi cả thế giới cũng như quan niệm khoa học đương thời. Do xuất thân có nguồn gốc Do Thái nên ngay từ khi bắt đầu đi học Albert Einstein đã chịu nhiều sự phân biệt kì thị. Cuộc đời nghiên cứu khoa học của Albert Einstein cũng gặp nhiều khó khăn do hoàn cảnh khách quan và thời cuộc đem lại, nhưng bằng trí tuệ phi thường, ông đã cho ra những công trình nghiên cứu làm thay đổi khoa học hiện đại. Vào năm 1999, ông được tạp chi Time của Mỹ vinh danh là con người của Thế kỷ. Trước khi qua đời, ông đã viết giấy hiến tặng bộ óc của mình cho các nhà nhân chủng học nghiên cứu. Đại văn hào Bernard Shaw đã gọi Albert Einstein là “VĨ NHÂN THỨ TÁM” của thế giới khoa học, sau Pythagoras, Aristotle, Ptolemy, Copernicus, Galileo, Kepler và Newton.', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_237520.jpg', 158, 2021, 50, 0, N'NXB Thanh Niên', N'8935210274816', 27, 1, 1, 38, CAST(30800.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (501, N'Kể Chuyện Thiên Tài Nổi Tiếng - Albert Einstein - Nhà Khoa Học Thiên Tài', N'Tuệ Minh, Bích Ngọc', N'Cty Văn Hóa & Truyền Thông Trí Việt.', CAST(30800.00 AS Decimal(18, 2)), N'Kể Chuyện Thiên Tài Nổi Tiếng - Albert Einstein - Nhà Khoa Học Thiên Tài Bộ sách “KỂ CHUYỆN THIÊN TÀI NỔI TIẾNG” giới thiệu các danh nhân như: Alfred Nobel, Edison, Victor Hugo, Leonardo Da Vinci, Albert Einstein, Beethoven, Newton, Hans Christian Andersen, Marie Curie, Lev Tolstoy… Mỗi danh nhân đại diện cho một đỉnh cao trong lĩnh vực tri thức, và những sáng tạo cũng như đóng góp phi thường của họ đã trở thành những thành tựu vĩ đại và các tác phẩm kiệt xuất cho văn hóa nhân loại. Thông qua những câu chuyện về cuộc đời của các danh nhân, bộ sách này sẽ giúp các bạn học sinh có được kiến thức toàn diện về các thời đại khác nhau, những biến cố, tính cách và những thành tựu to lớn mà các danh nhân đã đạt được, từ đó giúp các em tiếp cận và thấy được nhân cách các vĩ nhân, tăng thêm hiểu biết và được truyền thêm cảm hứng để kiên trì theo đuổi đam mê, tiếp thêm nguồn năng lượng cho quá trình trưởng thành của mình. Bộ sách này cũng để giúp các bạn học sinh tiếp cận và hiểu thêm về các danh nhân ấy, từ đó giúp các em hoàn thiện tâm hồn và mang lại những lợi ích cho cuộc sống của chính mình.', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786044771267.jpg', 116, 2023, 50, 0, N'Văn Học', N'9786044771267', 27, 1, 60, 22, CAST(21560.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (502, N'Bộ Lấy Nước Đường Xa (Tái Bản)', N'Linda Sue Park', N'Thái Hà', CAST(80000.00 AS Decimal(18, 2)), N'Lấy Nước Đường Xa (Tái Bản) Lấy nước đường xa - Cuốn tiểu thuyết dựa trên một câu chuyện có thật tại Châu Phi. Hai câu chuyện đan xen nhau kể về hai đứa trẻ tại Sudan – sống ở hai thời kỳ khác nhau – hai bộ tộc đối lập nhau và hai cuộc “đấu tranh” không giống nhau. Câu chuyện thứ nhất, Nya là một cô bé mười một tuổi (năm 2008). Cô bé phải đi bộ mỗi ngày 8 tiếng để lấy nước từ một chiếc ao bị ô nhiễm. Cô bé không có thời gian cho trường học, cho vui chơi, cho tất cả những điều mà hầu hết các cô gái nhỏ đều trải qua. Cho đến một ngày nọ, những người lạ vào làng của họ để đào giếng và xây trường học. Câu chuyện thứ hai, Salva là cậu bé 11 tuổi đi bộ xuyên lục địa Châu Phi để tìm thức ăn, gia đình và một nơi trú ẩn. Đó là năm 1985 khi Salva đang đi học và chiến tranh nổ ra. Salva phải băng qua sa mạc để đến một trại tị nạn ở Ethiopia. Sau một thời gian dài ở lại, Salva một lần nữa băng qua sa mạc để đến Kenya. Trên chặng đường dài ấy nhiều người đã không vượt qua được. Họ chết vì đói, vì bị thú dữ và binh lính tấn công. Salva là số ít người còn sống sót và được một gia đình người Mỹ nhận nuôi. Câu chuyện của Nya và Salva đã giao thoa và kết nối với nhau. Nya kết thúc hành trình 8 tiếng mỗi ngày đi lấy nước cho gia đình và được đến trường học. Còn hành trình của Salva thì vẫn tiếp tục với một diễn biến khác nhiều ý nghĩa và tươi sáng hơn!', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935280910737.jpg', 160, 2022, 50, 0, N'NXB Lao Động', N'8935280910737', 27, 1, 60, 39, CAST(56000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (503, N'Donald J.Trump - Đã Đến Lúc Phải Cứng Rắn Để Khôi Phục Sự Vĩ Đại Của Nước Mỹ (Tái Bản 2024)', N'Donald J. Trump', N'Alpha Books', CAST(110000.00 AS Decimal(18, 2)), N'Donald J.Trump - Đã Đến Lúc Phải Cứng Rắn Để Khôi Phục Sự Vĩ Đại Của Nước Mỹ Ứng cử viên tổng thống của Đảng Cộng hòa trong mùa tranh cử 2016 Donald J. Trump lên kế hoạch làm cho nước Mỹ vĩ đại trở lại như xưa. Bởi theo Trump, Tổng thống Obama là một thảm họa đối với đất nước này. Ông ta đã phá tung nền kinh tế, mở cửa biên giới cho những tên tội phạm bạo lực bước vào, thòng lên vai con cháu chúng ta gánh nặng nợ nần và đi khắp thế giới xin lỗi cho nước Mỹ như thể đất nước vĩ đại nhất thế giới này cần xin lỗi vì là mảnh đất của cơ hội và tự do như trước khi Obama trở thành Tổng thống. Giờ đây, nước Mỹ trông như một đất nước kiệt quệ, bị tước mất việc làm, sự thịnh vượng, sự tôn trọng. Và Tổng thống Obama làm gì với hiện trạng này? Ông ta chơi bài tử tế với chính những chính phủ nước ngoài đang háo hức nhìn nước Mỹ bị thiêu thành tro. Chuyện này không thể tiếp diễn. Và nếu Donald Trump có gì để nói về chuyện này, thì đó là nó phải kết thúc. Trong cuốn sách bestseller của New York Times, Trump đưa ra những câu trả lời mà nước Mỹ đang tìm kiếm như: - Làm sao để đảm bảo an ninh biên giới và chặn dòng người nhập cư ồ ạt vào Mỹ. - Làm sao để tạo ra việc làm cho người Mỹ bằng cách buộc Trung Quốc phải tiến hành hoạt động mậu dịch thật sự công bằng. - Làm sao để trả dứt nợ mà không đe dọa các chương trình lâu đời như An sinh Xã hội, Chăm sóc Y tế và Trợ giúp Y tế mà hàng triệu người Mỹ đang phải sống dựa vào. - Làm sao để sửa đổi sự gian trá của học thuyết kinh tế Obama và thảm họa Obamacare. Thẳng thắn, gay gắt và hấp dẫn từ đầu đến cuối, cuốn sách vạch ra một nghị trình dựa trên hiểu biết thông thường để khôi phục sự thịnh vượng của nước Mỹ và khiến đất nước này trở lại với vị trí dẫn đầu thế giới. "Tôi yêu nước Mỹ. Tôi buồn lòng trước những gì mắt thấy đang xảy ra trên đất nước mình. Chúng ta đang bị nhạo báng, bị đẩy vòng quanh, bị bất kính và bị đối xử tàn tệ. Obama là một thí nghiệm tả khuynh thất bại và trở nên cực kỳ sai lầm, và đó là điều ai cũng biết. Ngay cả những người bạn tôi từng bỏ phiếu cho người đàn ông này cũng thừa nhận riêng rằng ông ta là một nỗi thất vọng to lớn. Chúng ta không đủ sức chịu đống bừa bộn này thêm bốn năm nữa. Tương lai của con cháu chúng ta đang lâm nguy - và chúng ta phải vì chúng mà khắc phục chuyện này. Chúng ta phải cứng rắn để đất nước của chúng ta có thể trở lại vĩ đại như xưa." Donald Trump', N'https://cdn1.fahasa.com/media/catalog/product/d/a/da-den-luc-phai-cung-ran.u547.d20161215.t090546.604305.jpg', 272, 2024, 50, 0, N'Thế Giới', N'8935251422177', 28, 1, 2, 7, CAST(77000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (504, N'Lịch Sử 12 (Kết Nối) (Chuẩn)', N'Nhiều Tác Giả', N'Nhà xuất bản Giáo Dục', CAST(13900.00 AS Decimal(18, 2)), N'Lịch Sử 12 (Kết Nối) (Chuẩn) Sách được biên soạn theo chương trình giáo dục phổ thông mới, thuộc bộ sách kết nối tri thức. Với việc lựa chọn các nội dung học tập đảm bảo tính chuẩn mực, hiện đại, phong phú và đa dạng; hình thức thể hiện đẹp, có sự kết hợp hài hoà giữa kênh hình và kênh chữ sẽ gây hứng thú học tập giúp các em yêu thích học tập môn lịch sử hơn.', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786040392718.jpg', 112, 2024, 50, 0, N'Giáo Dục Việt Nam', N'9786040392718', 32, 1, 24, 31, CAST(9730.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (505, N'Bộ Khoa Học Tự Nhiên 6 (Kết Nối Tri Thức) (Chuẩn)', N'Nhiều Tác Giả', N'Nhà xuất bản Giáo Dục', CAST(24800.00 AS Decimal(18, 2)), N'Khoa Học Tự Nhiên 6 (Kết Nối Tri Thức) (2023)', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786040287427_1.jpg', 196, 2023, 50, 0, N'Giáo Dục Việt Nam', N'9786040339089', 32, 1, 24, 31, CAST(17360.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (506, N'Dầu Và Máu - Bìa Cứng', N'Bradley Hope, Justin Scheck', N'CÔNG TY CỔ PHẦN SÁCH OMEGA VIỆT NAM', CAST(212000.00 AS Decimal(18, 2)), N'Dầu Và Máu Dầu và máu không chỉ là một cuốn sách đơn thuần về chính trị và kinh tế, mà còn là một tác phẩm văn học, là một câu chuyện tuyệt vời về quyền lực, tham vọng và những biến động của thế giới hiện đại. Đối với độc giả, cuốn sách này là một cửa sổ mở ra một thế giới mới, một cơ hội để hiểu rõ hơn về những sức mạnh và mâu thuẫn địa chính trị đang định hình thế giới xung quanh chúng ta. Cuốn sách cũng làm cho độc giả hiểu hơn về một Trung Đông phát triển về kinh tế và đang dần độc lập về chính trị nơi tôi cũng đã có dịp ghé thăm và làm việc lâu dài. - Đại sứ Trần Ngọc Thạch, Nguyên Đại sứ Việt Nam tại Các Tiểu vương quốc Ả Rập Thống nhất Dầu và Máu đã mở cánh cửa hiểu biết tới với thế giới kín đáo và quyền lực Ả-rập Xê-út thông qua nhân vật trung tâm – Thủ tướng, Thái tử Mohammed Bin Salman. Từ những khoản đầu tư khổng lồ vào công nghệ; sử dụng dầu mỏ như một vũ khí kinh tế; cho đến những cải cách mạnh mẽ trong nước... Cuốn sách đã cung cấp cái nhìn về sự nổi lên của Thủ tướng, Thái tử Mohammed Bin Salman. Điều gì đã đưa vị thái tử sinh năm 1985 không chỉ nhanh chóng nắm bắt quyền lực tại Ả-rập Xê-út, mà giờ đây đã trở thành một trong những nhân vật chính trị và kinh tế quan trọng nhất thế giới? Nội dung cuốn sách vẫn còn có những điều gây tranh cãi. Nhưng đây là tác phẩm không thể thiếu cho những ai muốn hiểu rõ hơn về sức mạnh, sự tham vọng, và tương lai của Ả-rập Xê-út dưới thời Mohammed bin Salman. - Lê Anh Phương, Trưởng Cơ quan Thường trú VTV tại Trung Đông', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935251419948.jpg', 378, 2024, 50, 0, N'Thế Giới', N'8935251419948', 28, 1, 2, 11, CAST(148400.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (507, N'Bộ Hồi Ký Lý Quang Diệu - Tập 2: Từ Thế Giới Thứ Ba Vươn Lên Thứ Nhất (Tái Bản 2023)', N'Lý Quang Diệu', N'Alpha Books', CAST(391000.00 AS Decimal(18, 2)), N'Hồi Ký Lý Quang Diệu - Tập 2: Từ Thế Giới Thứ Ba Vươn Lên Thứ Nhất Lý Quang Diệu đã viết bộ hồi ký dài hai tập: Tập 1 – “Câu chuyện Singapore” – trình bày quan điểm của ông về lịch sử Singapore cho đến khi tách rời khỏi Malaysia năm 1965, và tập 2 – “Từ thế giới thứ ba vươn lên thứ nhất” – thuật lại sự chuyển đổi của Singapore để trở mình từ đất nước nghèo khổ thành một “Con rồng châu Á”. Sau khi lãnh đạo đất nước Singapore độc lập ở cương vị Thủ tướng trong vòng 3 thập kỷ, năm 1990, Lý Quang Diệu lui về làm cố vấn và dành nhiều tâm sức thu thập tài liệu để viết nên bộ hồi ký này, nhìn lại toàn bộ cuộc đời ông. Cuốn tập 1 – Câu chuyện Singapore – được bắt đầu viết từ năm 1994, và xuất bản lần đầu tiên năm 1998, kể lại những ký ức đáng tự hào của một chàng sinh viên giỏi trong những ngày tháng du học trên đất Anh; từ câu chuyện tình yêu cảm động của ông với người vợ, đến những hoài bão của chàng thanh niên trẻ tuổi: những kết giao, những mối quan hệ, từng bước thâm nhập chính trường, học cách đối nhân xử thế, xây dựng đảng, lèo lái đất nước vượt qua những khó khăn. Tập 1 kết thúc ở thời điểm Singapore tuyên bố độc lập năm 1965, sau khi tách ra từ Liên bang Malaysia, cũng là lúc đánh dấu một cột mốc quan trọng trong quá trình hình thành suy nghĩ, tính cách của ông Lý. Những bước đi “bươn chải” của một nhà lãnh đạo năng động được tả lại trong cuốn sách cũng giúp người đọc có thêm một góc nhìn về tình hình thế giới thời Chiến tranh Lạnh, phong trào không liên kết, Mỹ, Anh, Nga, Trung Quốc và các cường quốc khác ở thời điểm còn đang “ẩn tàng” giữa hai bên màn sắt; về Liên minh châu Âu thời kỳ hình thành, về khối Thịnh vượng chung, và những liên minh, hiệp ước khác. Lý Quang Diệu viết trong tập 2 – “Từ thế giới thứ ba vươn lên thứ nhất”, xuất bản năm 1999: “Nếu Singapore là một đứa trẻ, tôi tự hào vì đã chăm sóc và nuôi dưỡng đứa trẻ ấy”. Năm 1965, nhà nước Singapore non trẻ giành độc lập, và sự tồn tại của quốc đảo nhỏ bé lúc đó rất mong manh. Từng là thuộc địa của Vương quốc Anh với vai trò là cảng giao thương, Singapore nay trở thành quốc gia hiện đại ở châu Á, nắm trong tay hãng hàng không lớn nhất thế giới, sân bay lớn, cảng thương mại đông đúc nhất, và mức thu nhập bình quân đầu người cao thứ 4 thế giới. Câu chuyện về sự chuyển đổi của Singapore được kể một cách lôi cuốn, và cũng gây tranh cãi. Đất nước Singapore sinh ra từ sự tan rã chế độ thực dân, sau sự tàn phá của Chiến tranh thế giới thứ 2, tình trạng đói nghèo phổ biến, sự rối loạn sau sự rút lui của lực lượng nước ngoài. Singapore hiện đang được ca ngợi là một thành phố của tương lai. Hiện tượng lịch sử phi thường này được kể bởi 1 người không chỉ sống qua tất cả các giai đoạn khó khăn đó, mà chính là nhân vật kiến tạo quốc gia, mở đường cho đất nước. Cuốn sách được viết dựa trên những ghi chú tỉ mỉ của ông, cũng như các giấy tờ của chính phủ chưa được công bố, và những hồ sơ chính thức của chính phủ trước đây. Ông nêu ra những nỗ lực phi thường để duy trì sự tồn tại của đảo quốc nhỏ bé ở Đông Nam Á. Ông giải thích cách ông và các thành viên chính phủ dập tắt mối đe dọa từ bên ngoài tới an ninh của nhà nước non trẻ này, và bắt đầu quá trình gian khổ xây dựng đất nước: xây dựng hệ thống đường sá, cơ sở hạ tầng, từ vùng đất chủ yếu là đầm lầy; xây dựng lực lượng quân đội từ nguồn dân số nhỏ bé, nạn phân biệt chủng tộc phổ biến, chia rẽ ý thức hệ; loại bỏ vấn đề tham nhũng còn tồn tại từ thời thuộc địa; cung cấp hệ thống nhà ở xã hội; thành lập hãng hàng không và sân bay quốc gia. Ông cũng viết một cách thẳng thắn về cách tiếp cận sắc bén của mình để loại bỏ đối thủ chính trị và những người có quan điểm không chính thống về nhân quyền, dân chủ,… nhằm “luôn đúng khuôn mẫu, không chỉ về mặt chính trị”. Cũng trong cuốn sách, Lý Quang Diệu khắc họa chân dung người đàn bà thép Margaret Thatcher và Ronald Reagan, Giang Trạch Dân, George Bush và Đặng Tiểu Bình. Ông vén bức màn bí mật về gia đình, viết một cách cẩn trọng và yêu thương về vợ ông và người con trai Lý Hiển Long. Ông', N'https://cdn1.fahasa.com/media/catalog/product/i/m/image_195509_1_35053_1.jpg', 602, 2023, 50, 0, N'Thế Giới', N'8935270704322', 28, 1, 61, 7, CAST(273700.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (508, N'Cách Mạng', N'Emmanuel Macron', N'FIRST NEWS', CAST(93440.00 AS Decimal(18, 2)), N'Cách Mạng Cuốn sách những người quan tâm đến chính trị đều phải đọc Cách Mạng được xuất bản ngày 24-11-2016, đã bán được gần 200.000 bản và là một trong những quyển sách bán chạy nhất nước Pháp trong năm 2016. Không phải ngẫu nhiên mà bản quyền dịch thuật cuốn sách này bán được cho hơn 20 quốc gia, một con số chưa từng có đối với một chính trị gia người Pháp. Điều gì khiến cuốn sách nhỏ này hấp dẫn đến vậy? Ngày 14-5-2017, một người đàn ông mới 39 tuổi tuyên thệ trước điện Elysée trong buổi lễ nhậm chức Tổng thống Pháp. Đó chính là Emmanuel Macron, tổng thống thứ 25 và cũng là tổng thống trẻ nhất của nước Pháp từ trước đến nay. Cuộc đời riêng và sự nghiệp chính trị của Macron kể từ khi ông nổi lên từ cuộc chạy đua vào chức tổng thống đã trở thành tâm điểm của giới truyền thông. Xuất thân từ tỉnh lẻ, gia đình căn bản theo nghề y, không hề có truyền thống chính trị, cưới một người vợ là cô giáo của ông và hơn ông 24 tuổi, đã có 3 con riêng. Đam mê văn chương từ nhỏ, lớn lên theo học triết rồi lại chuyển hướng sang ngành hành chính công. Thế rồi đột ngột từ bỏ lĩnh vực hành chính công để theo đuổi một sự nghiệp rất thành công trong lĩnh vực tài chính ngân hàng. Sau đó tham gia vào chính phủ của Tổng thống François Hollande, làm Phó Tổng Thư ký Văn phòng Tổng thống rồi Bộ trưởng Bộ Kinh tế, Công nghiệp và Kỹ thuật số. Tháng 4-2016, Macron bỗng nhiên quyết định từ chức bộ trưởng và thành lập phong trào Tiến bước! (En Marche!), một đảng chính trị mà theo ông là theo đường lối ôn hòa, không phải cánh tả cũng không phải cánh hữu. Sau một cuộc chạy đua tranh cử ngoạn mục, ông đã đánh bại ứng viên cực hữu Marine Le Pen, bước lên tột đỉnh vinh quang trong lĩnh vực chính trị: Trở thành chủ nhân của điện Elysée. Từ một nhân vật vô danh trở thành tổng thống, cuộc đời của Macron, cả về đời tư lẫn sự nghiệp, phải nói là rất kỳ lạ và đầy mê hoặc vì những bước ngoặt bất ngờ. Và có vẻ như những bất ngờ xuất phát từ bộ óc đầy nhiệt huyết ấy vẫn chưa dừng lại. Như Macron đã nói ngay trong Lời nói đầu cuốn sách tự sự nêu rõ những quan điểm nhân sinh và chính trị của mình – Cách Mạng: “Tất cả chúng ta cần phải thoát khỏi những thói quen của chính mình. Từ Nhà nước đến các nhà lãnh đạo, các quan chức cấp cao, các lãnh đạo doanh nghiệp, các tổ chức công đoàn hay các cơ quan trung gian, đều có trách nhiệm phải thay đổi. Sẽ thật sai lầm nếu chúng ta cứ trốn tránh hay cố thích nghi với thực tại. Chúng ta đã quá quen với một thế giới đáng lo ngại. Một thế giới mà thật lòng chúng ta không muốn nhắc đến, cũng không hề muốn đối mặt. Và chúng ta phàn nàn, chúng ta càu nhàu. Những bi kịch thì cứ diễn ra. Thất vọng. Lo sợ. Chúng ta đùa giỡn với những điều này. Chúng ta muốn thay đổi, nhưng chưa thực sự thiết tha.” Vậy phải thay đổi những gì để làm được một cuộc cách mạng dân chủ sâu sắc? Tân Tổng thống Pháp, trong hơn 250 trang sách đã đưa ra những kiến giải và giải pháp về tất cả các lĩnh vực của đời sống: từ việc làm, kinh tế, giáo dục, y tế, an sinh xã hội, đến môi trường, ngoại giao, quân sự và cải tổ cơ cấu hành chính. Đặc biệt, một quan điểm xuyên suốt của Macron trong Cách mạng là số mệnh nước Pháp gắn liền với khả năng hồi phục sức mạnh của Liên minh châu Âu: “Chúng ta sẽ chỉ có thể thành công với hai điều kiện. Một là phát triển lại mô hình châu Âu, đây là cơ hội của chúng ta trong bối cảnh toàn cầu hóa. Hai là lấy lại niềm tin vào chính mình”. Và không chỉ nói suông, trong cuốn sách này, ông thật sự đã vạch ra một viễn cảnh rõ ràng để hồi phục Liên minh châu Âu. Vượt qua ranh giới của một ấn phẩm xuất bản với mục đích hỗ trợ chiến dịch tranh cử của tổng thố', N'https://cdn1.fahasa.com/media/catalog/product/c/a/cachmang.jpg', 256, 32018, 50, 0, N'NXB Tổng hợp TP.HCM', N'8935086845066', 28, 1, 61, 25, CAST(65408.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (509, N'Keynes - Tư Tưởng Kinh Tế Hữu Ích Cho Nền Kinh Tế Hiện Nay', N'Peter Temin, David Vines', N'CÔNG TY TNHH TRUYỀN THÔNG VÀ GIÁO DỤC LYCEUM', CAST(135000.00 AS Decimal(18, 2)), N'Keynes - Tư Tưởng Kinh Tế Hữu Ích Cho Nền Kinh Tế Hiện Nay Cuốn sách “Keynes – Tư tưởng kinh tế hữu ích cho nền kinh tế thế giới ngày nay” của Peter Temin và David Vines là một hành trình khám phá tư tưởng kinh tế của John Maynard Keynes, một trong những nhà kinh tế học vĩ đại nhất thế kỷ 20. Với cách viết giàu tính thực tiễn và dẫn dắt chặt chẽ, tác phẩm không chỉ giới thiệu về cuộc đời và sự nghiệp của Keynes mà còn giải thích rõ ràng các khái niệm kinh tế học Keynesian qua bối cảnh lịch sử cụ thể. Sách khởi đầu bằng cách trình bày nền kinh tế trước thời Keynes, từ các lý thuyết của Hume đến Marshall, để minh họa những trở ngại mà Keynes phải đối mặt khi xây dựng hệ thống tư tưởng của mình. Qua các chương, độc giả sẽ được làm quen với những khái niệm kinh tế quan trọng như bẫy thanh khoản, biểu đồ IS-LM, và các chính sách tài chính Keynesian, được minh họa bằng các mô hình và biểu đồ dễ hiểu. Điểm đặc biệt của cuốn sách là cách nó liên kết tư tưởng của Keynes với các vấn đề kinh tế hiện đại, bao gồm cả cuộc khủng hoảng tài chính toàn cầu 2008 và những bài học có thể áp dụng vào các nền kinh tế đang phát triển như Việt Nam. Các tác giả cũng tập trung vào việc tái khám phá vai trò của nhà nước trong điều tiết kinh tế, mở ra những hướng đi mới mẻ và thiết thực.', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786048481872.jpg', 236, 2024, 50, 0, N'Đà Nẵng', N'9786048481872', 29, 1, 5, 17, CAST(94500.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (510, N'Kinh Tế Nhật Bản - Giai Đoạn Phát Triển Thần Kỳ 1955-1973', N'Trần Văn Thọ', N'Phanbook', CAST(182400.00 AS Decimal(18, 2)), N'Kinh Tế Nhật Bản - Giai Đoạn Phát Triển Thần Kỳ 1955-1973 Giáo sư Trần Văn Thọ là chuyên gia tầm chính phủ về kinh tế. Góc nhìn của ông về kinh tế thế giới – Nhật Bản – và Việt Nam luôn được các nhà hoạch định chính sách quan tâm lắng nghe để đưa ra quyết sách ở tầm vĩ mô. *** Đây là một cuốn sách cực kỳ quan trọng, được biên soạn rất công phu, phản ảnh kiến thức sâu và rộng của tác giả về cả lý thuyết lẫn thực hành của ngành kinh tế phát triển. Sách được đúc kết dựa trên các phân tích số lượng chặt chẽ và đem lại những kiến thức mới để hiểu quá trình Nhật Bản trở thành một cường quốc kính tế. Những bài học được tác giả rút ra từ Nhật Bản sẽ giúp Việt Nam trên đường công nghiệp hoá và phát triển. Đặc biệt ấn tượng là kinh nghiệm Nhật Bản được tổng kết qua hai khái niệm nhà nước kiến tạo phát triển và năng lực xã hội. *** KINH TẾ NHẬT BẢN Giai đoạn phát triển thần kỳ 1955-1973 Tác giả: GIÁO SƯ TRẦN VĂN THỌ PHANBOOK và NXB ĐÀ NẴNG trân trọng giới thiệu! Trong lịch sử Nhật Bản, giai đoạn 1955-1973 rất đặc biệt. Giai đoạn đó làm nên một thời đại, thời đại phát triển thần kỳ. Trung bình mỗi năm tăng trưởng 10%, kéo dài gần 20 năm, rất hiệu suất và đạt toàn dụng lao động. Giai đoạn này đã đưa Nhật Bản vươn lên thành một cường quốc công nghiệp, theo kịp các nước tiên tiến phương Tây, thực hiện giấc mơ và mục tiêu của lãnh đạo thời Minh Trị Duy tân. Xoay quanh hai từ khóa nhà nước kiến tạo phát triển và năng lực xã hội, cuốn sách này phân tích những yếu tố làm nên giai đoạn phát triển thần kỳ ấy. Ngoài khung phân tích kinh tế học phát triển để khảo sát chiến lược, chính sách về đầu tư, hội nhập, giáo dục đào tạo, du nhập và sử dụng công nghệ, , cuốn sách còn đặt vấn đề từ một cái nhìn rộng hơn, khảo sát tư tưởng và hành động của các chủ thể như lãnh đạo chính trị, quan chức, lãnh đạo doanh nghiệp, Sách kể nhiều mẩu chuyện kèm theo hình ảnh của những chính trị gia, quan chức, học giả, nhà doanh nghiệp tiêu biểu thời hậu chiến Nhật Bản, những người đã làm nên giai đoạn thần kỳ này. Cuốn sách có thêm hai phụ chương để giúp các độc giả muốn biết về kinh tế Nhật sau giai đoạn phát triển thần kỳ (1974-2020). Kinh nghiệm Nhật Bản với hai từ khóa nhà nước kiến tạo phát triển và năng lực xã hội cho thấy nhiều hàm ý đối với Việt Nam trong giai đoạn phát triển sắp tới.', N'https://cdn1.fahasa.com/media/catalog/product/u/n/untitled-1_4_26.jpg', 292, 2022, 50, 0, N'NXB Đà Nẵng', N'8936144201510', 29, 1, 5, 35, CAST(127680.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (511, N'Jesse Livermore - Reminiscences Of A Stock Operator - Hồi Ức Của Một Thiên Tài Đầu Tư Chứng Khoán', N'Edwin Lefèvre', N'CÔNG TY CỔ PHẦN SÁCH OMEGA VIỆT NAM', CAST(170000.00 AS Decimal(18, 2)), N'Jesse Livermore - Reminiscences Of A Stock Operator - Hồi Ức Của Một Thiên Tài Đầu Tư Chứng Khoán I. AI NÊN ĐỌC CUỐN SÁCH NÀY - Những nhà đầu tư chứng khoán: Người đã có kinh nghiệm và muốn nâng cao kiến thức và hiểu biết sâu hơn về thị trường. - Những người mới bắt đầu: Người tìm kiếm lời khuyên đầu tư và hiểu biết cơ bản về cách thị trường hoạt động. - Sinh viên và học giả: Những người quan tâm đến lịch sử và phát triển của thị trường tài chính và các nhà đầu cơ. - Những người yêu thích đọc về các nhân vật lịch sử và tự truyện: Cuốn sách cung cấp cái nhìn sâu sắc vào cuộc đời và sự nghiệp của Jesse Livermore, một nhân vật có thật và rất nổi tiếng trong lịch sử chứng khoán. II. TÓM TẮT SÁCH Hồi ức của một thiên tài đầu tư chứng khoán lần đầu được xuất bản vào năm 1923. Đó là bức chân dung được tiểu thuyết hoá về cuộc đời của Jesse Livermore, một trong những nhà đầu cơ xuất sắc nhất mọi thời đại. Rất nhiều nhà đầu tư thuộc các thế hệ khác nhau đều thừa nhận những bài học họ rút ra được từ cuốn sách thậm chí còn nhiều hơn từ kinh nghiệm hoạt động thị trường. Lần đầu tiên được xuất bản vào năm 1923, Hồi ức của một thiên tài đầu tư chứng khoán là một cuốn sách về đầu tư chứng khoán được đón nhận và đánh giá cao trên toàn thế giới. Đây là một câu chuyện không bị ảnh hưởng bởi thời gian. Những lời khuyên về kinh doanh và phân tích nhạy bén về những hoạt động thái giá cả của thị trường trong cuốn sách vẫn còn nguyên giá trị cho tới tận ngày nay. Hồi ức của một thiên tài đầu tư chứng khoán khắc hoạ sinh động về quyền lực của Livermore trên thị trường chứng khoán kể từ năm 14 tuổi. Khởi đầu với một vụ đầu tư 5 đô-la, Livermore đã tích luỹ được một sản nghiệp ngay từ tuổi 20 và sớm chứng tỏ mình như một nhân vật chính tại phố Wall. Ông tuyên bố rằng trên thị trường chỉ có những gã khờ, non nớt như chơi trò đánh bạc. Livermore đã ba lần phá sản, nhưng rồi đã trở lại, và sau mỗi lần như vậy, ông lại trở nên giàu có hơn nhờ những bài học kinh nghiệm tích luỹ được. Hồi ức của một thiên tài đầu tư chứng khoán là một cuốn cẩm nang kể chuyện có giá trị xuyên thời gian sẽ làm phong phú thêm kinh nghiệm và đời sống đầu tư của những nhà kinh doanh cổ phiếu ngày nay, giống như điều cuốn sách này đã làm được trong nhiều thế hệ qua. III. CUỐN SÁCH CÓ GÌ ĐẶC BIỆT - Chân dung chi tiết về một nhà đầu cơ huyền thoại: Cuốn sách cung cấp cái nhìn sâu sắc vào cuộc đời và sự nghiệp của Jesse Livermore, một trong những nhà đầu cơ chứng khoán vĩ đại nhất. Điều này giúp người đọc hiểu rõ hơn về các chiến lược và quyết định mà ông đã áp dụng để đạt được thành công cũng như những sai lầm dẫn đến thất bại. - Lời khuyên và chiến lược đầu tư: Livermore chia sẻ những bài học và chiến lược cụ thể mà ông đã sử dụng, như việc theo dõi và phân tích xu hướng thị trường, kiểm soát rủi ro, và tầm quan trọng của tâm lý trong đầu tư. Những lời khuyên này không chỉ có giá trị với thời đại của ông mà còn có ứng dụng rộng rãi đối với những nhà đầu tư hiện đại. - Minh họa rõ nét về tâm lý đầu tư và kỷ luật cá nhân: Cuốn sách đi sâu vào các vấn đề tâm lý mà nhà đầu tư phải đối mặt, như lòng tham, sợ hãi, và sự thiếu kiên nhẫn. Cách mà Livermore đối mặt và kiểm soát những cảm xúc này là bài học quý giá cho bất kỳ ai muốn thành công trong đầu tư. - Cảnh báo về rủi ro và thất bại: Livermore không ngại chia sẻ về những thất bại của mình, điều này làm nổi bật rủi ro trong đầu tư chứng khoán. Các câu chuyện về sự mất mát lớn nhấn mạnh tầm quan trọng của việc quản lý vốn và rủi ro. - Cuộc sống cá nhân phức tạp: Ngoài những thành công trong sự nghiệp, Livermore cũng có cuộc sống cá nhân khá phức tạp với nhiều cuộc hôn nhân và vấn đề cá nhân. Những chi tiết này làm cho cuốn sách thêm phần hấp dẫn, không chỉ là một cuốn sách kinh doanh mà còn là một câu chuyện về cuộc đời một con người. IV. CÁC TRÍCH ĐOẠN HAY - Về tính kiên nhẫn và kỷ luật: ""Tôi đã học được rằng tính kiên nhẫn là một trong những đức tính quan trọng nhất của một nhà đầu cơ. Không phải lúc nào cũng có cơ hội tốt xuất hiện,', N'https://cdn1.fahasa.com/media/catalog/product/h/o/hoi-uc-ve-mot-thien-tai-dau-tu-chung-khoan.jpg', 468, 2024, 50, 0, N'Lao Động', N'8935251422061', 29, 1, 62, 11, CAST(119000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (512, N'Bộ Ngữ Văn 12 - Tập 1 (Kết Nối) (Chuẩn)', N'Nhiều Tác Giả', N'Nhà xuất bản Giáo Dục', CAST(20300.00 AS Decimal(18, 2)), N'Ngữ Văn 12 - Tập 1 (Kết Nối) (Chuẩn) Sách được biên soạn theo Chương trình giáo dục phổ thông năm 2018. Với quan điểm giáo dục mới, các chủ đề, các bài học được thiết kế nhằm giúp học sinh hình thành và phát triển các kỹ năng môn ngữ văn của mình. Đặc biệt sách chú trọng nội dung, giúp học sinh chủ động học. Tác giả là những nhà khoa học, nhà sư phạm, nhà giáo giàu kinh nghiệm trong giáo dục phổ thông.', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786040392763.jpg', 168, 2024, 50, 0, N'Giáo Dục Việt Nam', N'9786040392763', 32, 1, 64, 31, CAST(14210.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (513, N'Bộ Bill Gates - Tham Vọng Lớn Lao Và Quá Trình Hình Thành Đế Chế Microsoft (Tái Bản 2023)', N'James Wallace, Jim Erickson', N'Alpha Books', CAST(212000.00 AS Decimal(18, 2)), N'Bill Gates: Tham Vọng Lớn Lao Và Quá Trình Hình Thành Đế Chế Microsoft Cuốn sách này mở ra một câu chuyện sinh động và chân thực nhất về sự nổi lên của một thiên tài độc đoán, cách thức ông làm thay đổi cả một nền công nghiệp máy tính, và lý do tại sao mọi người quyết tâm tìm hiểu ông bằng được. Trong tiết lộ thú vị này, hai phóng viên điều tra Wallace và Erickson đã lần theo bước chân của Gates từ những ngày còn là một hacker 13 tuổi tóc tai bù xù đến địa vị trở thành CEO lừng danh của một tập đoàn hàng đầu thế giới - Microsoft. Một phần doanh nhân, một phần lập dị, Gates đã trở thành nhân vật quyền lực nhất, giàu có nhất và cũng đáng sợ nhất trong ngành công nghiệp máy tính. Hai tác giả đã nói chuyện với tất cả những ai biết bất cứ điều gì đó về Gates và Microsoft - từ những người bạn thời thơ ấu cho tới những nhân viên và các đối thủ kinh doanh, những người có thể thiết lộ thông tin về chiều cao, những hạn chế, và cả những ma thuật của Gates. Từ những thành tích xuất sắc của Gates cho đến sự thô lỗ, ngạo mạn không kém bất thường của ông, và cả sự thù địch (không khí rất căng thẳng tại Microsoft tới nỗi những lập trình viên phải cho nổ bom tự tạo để giảm bớt căng thẳng), đây là một tiết lộ độc đáo thể hiện cái nhìn về một con người đã nổi lên như một ông vua của một ngành công nghiệp nổi tiếng tàn bạo. Trong cuốn sách này đầy ắp những phân tích khách quan về chiến thắng trong kinh doanh của một tập đoàn hàng đầu và chân dung người lãnh đạo cừ khôi nhưng cũng lập dị đáng kinh ngạc đứng sau tất cả những thành quả đó.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935251406115_1_1.jpg', 416, 2023, 50, 0, N'Thế Giới', N'8935251421088', 29, 1, 62, 7, CAST(148400.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (514, N'Bộ Toán 12 - Tập 2 (Kết Nối) (Chuẩn)', N'Nhiều Tác Giả', N'Nhà xuất bản Giáo Dục', CAST(11700.00 AS Decimal(18, 2)), N'Toán 12 - Tập 2 (Kết Nối) (Chuẩn) Sách biên soạn theo chương trình giáo dục phổ thông mới. Các kiến thức trong sách được chủ yếu xuất phát từ những tình huống của cuộc sống quanh ta và trở lại giúp ta giải quyết những vấn đề của cuộc sống. Vì thế, khi học Toán theo cuốn sách này, các em sẽ cảm nhận được rằng, Toán học thật là gần gũi. Cung cấp cho các em những kiến thức chuyên sâu, bổ ích, lí thú và thiết thực, giúp các em hình thành kĩ năng thực hành, khả năng logic, kĩ năng vận dụng kiến thức đã học ở phần nội dung cơ bản vào giải quyết vấn đề thực tế.', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786040392749.jpg', 92, 2024, 50, 0, N'Giáo Dục Việt Nam', N'9786040392749', 32, 1, 64, 31, CAST(8190.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (515, N'Hồi Tưởng Gần 10 Năm Nghề "Rệp" Và Những Câu Chuyện Đằng Sau Tấm Thẻ Platinum-Dimond', N'Phạm Hoàng Phúc', N'CÔNG TY TNHH XUẤT BẢN VÀ GIÁO DỤC MOCHIBOOKS', CAST(151200.00 AS Decimal(18, 2)), N'Hồi Tưởng Gần 10 Năm Nghề "Rệp" Và Những Câu Chuyện Đằng Sau Tấm Thẻ Platinum-Dimond “Hồi tưởng gần 10 năm nghề ‘Rệp’ và những câu chuyện đằng sau tấm thẻ Platinum Diamond” của Phạm Hoàng Phúc là một cuốn sách được viết ra không để kể chiến công, mà để kể sự thật về một nghề ít được gọi tên đúng nghĩa, về những con người đứng phía sau thành công của người khác và về một hành trình dài đầy va vấp, nơi thành công và thất bại luôn đi song hành như hai mặt của cùng một đồng xu. “Nghề rệp” hiện lên trong cuốn sách này không hào nhoáng, không được tô vẽ bằng những con số đẹp hay khẩu hiệu truyền cảm hứng quen thuộc. Đó là nghề tuyển sinh với tất cả những gì trần trụi nhất: áp lực doanh số, những cuộc gọi bị từ chối, những ngày làm việc kéo dài đến cạn năng lượng và cả cảm giác lạc lõng khi nỗ lực của mình hiếm khi được nhìn thấy. Phạm Hoàng Phúc chọn kể lại từ những ngày đầu non nớt bước vào nghề, những tháng ngày hăm hở tin rằng chỉ cần cố gắng là sẽ có kết quả, cho đến khi chạm tay vào thành công và rồi ngã xuống thật đau. Điểm chạm sâu nhất của cuốn sách nằm ở những lần vấp ngã, đó là những cú ngã buộc người ta phải nhìn lại chính mình. Khi mọi thứ sụp đổ, khi danh xưng, vị trí, tấm thẻ Platinum Diamond từng là biểu tượng cho thành tựu không còn bảo vệ được ai, tác giả đối diện với câu hỏi căn bản nhất: mình là ai khi không còn hào quang? Từ đó, hành trình “làm lại từ đầu” hiện ra lặng lẽ nhưng bền bỉ, với những lựa chọn khó khăn, những bài học phải trả giá bằng thời gian, niềm tin và cả tổn thương. Cuốn sách không chỉ là hồi ký nghề nghiệp, mà còn là một bản ghi chép chân thực về sự trưởng thành. Qua từng câu chuyện, người đọc thấy được cách một người làm nghề học cách hiểu con người, hiểu thị trường, hiểu hệ thống và quan trọng hơn, học cách hiểu chính mình. Những kinh nghiệm tuyển sinh được chia sẻ không mang màu sắc khô khan, mà được rút ra từ thực tế va đập: từ cách xây dựng mối quan hệ, giữ chữ tín, cho đến cách đứng dậy sau thất bại mà không đánh mất lòng tự trọng. “Hồi tưởng gần 10 năm nghề ‘Rệp’ và những câu chuyện đằng sau tấm thẻ Platinum Diamond” vì thế không chỉ dành cho người làm tuyển sinh hay giáo dục. Đó là cuốn sách dành cho bất kỳ ai từng đi qua một hành trình dài với nghề, từng tin, từng mơ, từng ngã và từng phải bắt đầu lại khi tưởng chừng không còn gì trong tay. Ở đó, tấm thẻ Platinum Diamond không còn là đích đến, mà trở thành một cột mốc để nhìn lại: điều gì thật sự có giá trị sau tất cả những được - mất của một đời làm nghề.', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786320204854.jpg', 192, 2026, 50, 0, N'Thế Giới', N'9786320204854', 30, 1, 13, 19, CAST(105840.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (516, N'Vẻ Đẹp Của Kẻ Chán Chường', N'Nguyễn Ngọc Thuần', N'Phanbook', CAST(121600.00 AS Decimal(18, 2)), N'Vẻ Đẹp Của Kẻ Chán Chường Vẻ đẹp của kẻ chán chường là tác phẩm đánh dấu sự trở lại đầy mới mẻ của nhà văn Nguyễn Ngọc Thuần sau gần 10 năm vắng bóng trên văn đàn, chiến đấu với bệnh nan y. Được viết bằng thể loại bán tự truyện, với không gian chủ yếu ở bệnh viện, với những câu từ giàu chất thơ, buồn bã trong khoái hoạt, điên rồ trong tỉnh táo, cực thực trong mơ tưởng, khốn cùng trong lãng mạn,… cuốn sách mang đến một thể nghiệm văn chương độc đáo, vừa quyến rũ vừa ma mị, vừa huyễn hoặc vừa hiện thực. Con người bày ra những gì còn lại của vốn liếng một đời, để hít thở và chối từ hít thở. Một tác phẩm văn học đương đại ngắn gọn, được viết từ trải nghiệm đời sống bất định của chính tác giả, chắc chắn sẽ tạo ra những rung chấn sâu xa trong tâm hồn độc giả!', N'https://cdn1.fahasa.com/media/catalog/product/z/7/z7380481074828_ea630e43bb1916a579b03c8e22273c7e.jpg', 164, 2026, 50, 0, N'Hội Nhà Văn', N'8936144202852', 30, 1, 13, 35, CAST(85120.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (517, N'Trở Về - Phần 1: Châu Âu', N'Phan Công Thiết', N'CÔNG TY CỔ PHẦN SÁCH OMEGA VIỆT NAM', CAST(80000.00 AS Decimal(18, 2)), N'Trở Về - Phần 1: Châu Âu Chúng ta sống trong một thế giới đầy sự hoài nghi và sợ hãi? Chúng ta có rất nhiều lý do để không đi du lịch nước ngoài: Thiếu tiền, thiếu giấy tờ, sợ nguy hiểm…. Cuốn hồi ký 173 ngày trở về chính là câu trả lời của Phan dành tới những bạn trẻ có ước mơ khám phá thế giới nhưng không có nhiều kinh phí. Anh đã sử dụng rất nhiều giải pháp để đi du lịch từ Pháp trở về Vietnam trong điều kiện eo hẹp về tài chính nhưng không làm mất đi sự đẹp đẽ của hành trình. Phần 1 : Châu Âu với tên gọi là độc lập-tự do-hạnh phúc là một lời tuyên bố hùng hồn cho tuổi thanh xuân, cho những bạn có khát khao, đam mê khám phá thế giới, khám phá văn hoá quốc tế. Qua các ứng dụng Couchesurfing ( xin ở nhờ ), Workaway ( làm tình nguyện) và Hichhiking ( xin đi đường). Phan đã có rất nhiều câu chuyện thú vị và chân thực trên hành trình từ Pháp trở về Vietnam. Đó là cuốn nhật ký được ghi chép lại một cách chân thực từng ngày trên hành trình. Sau mỗi ngày, Phan lại ghi chép những gì đã xẩy ra, câu chữ và mạch văn gần gũi, không trau chuốt vì nó được ghi trong suốt hành trình, nhằm tôn trọng những cảm xúc chân thật nhất và góc nhìn của anh tại thời điểm đó về những con ngừoi, những câu chuyện trong văn hoá hội nhập quốc tế. Khởi nguồn từ Pháp, Phan dịch chuyển lên Ba Lan và đi dọc đất nước Phần Lan xinh đẹp, đi phượt qua phía Bắc của Nauy , trở về Helsinki để đi tàu qua Thuỵ Điển… Phan đã truyền tải về một chuyến đi diễn ra với nhiều cảm xúc tự nhiên, không trói buộc bởi những kế hoạch, Phan để cho mọi người hoà vào chuyến hành trình của mình, vào tâm hồn của Anh, vào các ý kiến đa chiều về nhiều chủ để của cuộc sống. Đó là những câu chuyện đơn giản, không có kết cấu, không có cấu trúc bố cục, không có điểm đầu và điểm kết thúc, nhẹ nhàng và sâu sắc, gần gũi và có ý nghĩa, sự đọng lại cuối cùng của cuốn hành trình có lẽ đó là sự đơn giản, sự tích cực, sự đẹp đẽ như bản chất của cuộc sống này mà tác giả muốn chứng minh cho mọi người thấy. Đó là thông điệp mà anh muốn truyền tải cho những thế hệ trẻ hơn : Hãy dám đi ra, thế giới bên ngoài đầy đủ sự tốt đẹp nếu bạn xứng đáng!', N'https://cdn1.fahasa.com/media/catalog/product/9/7/9786043929973.jpg', 324, 2023, 50, 0, N'Thế Giới', N'9786043929973', 30, 1, 63, 11, CAST(56000.00 AS Decimal(18, 2)))
INSERT [dbo].[Books] ([book_id], [title], [author], [supplier], [price], [description], [image], [number_page], [yearOfPublish], [stock_quantity], [sold_quantity], [publisher], [ISBN], [category_id], [is_active], [location_id], [supplier_id], [cost_price]) VALUES (518, N'Danh Tác Việt Nam - Những Ngày Thơ Ấu (In Theo Bản Của NXB Đời Nay Năm 1940)', N'Nguyên Hồng', N'Nhà Sách Minh Thắng', CAST(40000.00 AS Decimal(18, 2)), N'Danh Tác Việt Nam - Những Ngày Thơ Ấu (In Theo Bản Của NXB Đời Nay Năm 1940) Tác phẩm “Những ngày thơ ấu” của Nguyên Hồng là một trong những hồi ký văn học nổi bật trong nền văn học Việt Nam hiện đại. Dưới đây là phân tích những điểm hay và đặc sắc của tác phẩm: 1. Tình cảm chân thật, sâu sắc 2. Phản ánh hiện thực xã hội 3. Nghệ thuật kể chuyện và miêu tả tinh tế 4. Giá trị nhân đạo sâu sắc 5. Tự truyện giàu giá trị văn học và tư tưởng “Những ngày thơ ấu” không chỉ là một tác phẩm tự truyện mà còn là lời kêu cứu của một tâm hồn non nớt giữa một xã hội đầy định kiến và thiếu tình người. Với văn phong giàu cảm xúc, lối kể chuyện tự nhiên và giá trị nhân văn sâu sắc, tác phẩm xứng đáng là một tác phẩm kinh điển của văn học Việt Nam.', N'https://cdn1.fahasa.com/media/catalog/product/8/9/8935236437066_1.jpg', 152, 2025, 50, 0, N'Văn Học', N'8935236437066', 30, 1, 63, 30, CAST(28000.00 AS Decimal(18, 2)))
